const List<String> layoutMadina15Pages5 = <String>[
  '21;41;1;\nT;0;30:6:3:وَعۡدَ ٱللَّهِۖ لَا يُخۡلِفُ ٱللَّهُ وَعۡدَهُۥ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَعۡلَمُونَ\nT;0;30:7:1:يَعۡلَمُونَ ظَٰهِرࣰا مِّنَ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَهُمۡ عَنِ ٱلۡأٓخِرَةِ هُمۡ\nT;0;30:7:2:غَٰفِلُونَ¦30:8:1:أَوَلَمۡ يَتَفَكَّرُواْ فِيٓ أَنفُسِهِمۗ مَّا خَلَقَ ٱللَّهُ ٱلسَّمَٰوَٰتِ\nT;0;30:8:0:وَٱلۡأَرۡضَ وَمَا بَيۡنَهُمَآ إِلَّا بِٱلۡحَقِّ وَأَجَلࣲ مُّسَمࣰّىۗ وَإِنَّ كَثِيرࣰا\nT;0;30:8:2:مِّنَ ٱلنَّاسِ بِلِقَآيِٕ رَبِّهِمۡ لَكَٰفِرُونَ¦30:9:1:أَوَلَمۡ يَسِيرُواْ فِي\nT;0;30:9:0:ٱلۡأَرۡضِ فَيَنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبۡلِهِمۡۚ كَانُوٓاْ\nT;0;30:9:0:أَشَدَّ مِنۡهُمۡ قُوَّةࣰ وَأَثَارُواْ ٱلۡأَرۡضَ وَعَمَرُوهَآ أَكۡثَرَ مِمَّا\nT;0;30:9:0:عَمَرُوهَا وَجَآءَتۡهُمۡ رُسُلُهُم بِٱلۡبَيِّنَٰتِۖ فَمَا كَانَ ٱللَّهُ\nT;0;30:9:2:لِيَظۡلِمَهُمۡ وَلَٰكِن كَانُوٓاْ أَنفُسَهُمۡ يَظۡلِمُونَ¦30:10:1:ثُمَّ كَانَ\nT;0;30:10:0:عَٰقِبَةَ ٱلَّذِينَ أَسَٰٓـُٔواْ ٱلسُّوٓأَىٰٓ أَن كَذَّبُواْ بِـَٔايَٰتِ ٱللَّهِ وَكَانُواْ بِهَا\nT;0;30:10:2:يَسۡتَهۡزِءُونَ¦30:11:3:ٱللَّهُ يَبۡدَؤُاْ ٱلۡخَلۡقَ ثُمَّ يُعِيدُهُۥ ثُمَّ إِلَيۡهِ تُرۡجَعُونَ\nT;0;30:12:3:وَيَوۡمَ تَقُومُ ٱلسَّاعَةُ يُبۡلِسُ ٱلۡمُجۡرِمُونَ¦30:13:1:وَلَمۡ يَكُن لَّهُم مِّن\nT;0;30:13:2:شُرَكَآئِهِمۡ شُفَعَٰٓؤُاْ وَكَانُواْ بِشُرَكَآئِهِمۡ كَٰفِرِينَ\nT;0;30:14:3:وَيَوۡمَ تَقُومُ ٱلسَّاعَةُ يَوۡمَئِذࣲ يَتَفَرَّقُونَ¦30:15:1:فَأَمَّا ٱلَّذِينَ\nT;0;30:15:2:ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ فَهُمۡ فِي رَوۡضَةࣲ يُحۡبَرُونَ',
  '21;41;1;\nT;0;30:16:1:وَأَمَّا ٱلَّذِينَ كَفَرُواْ وَكَذَّبُواْ بِـَٔايَٰتِنَا وَلِقَآيِٕ ٱلۡأٓخِرَةِ\nT;0;30:16:2:فَأُوْلَٰٓئِكَ فِي ٱلۡعَذَابِ مُحۡضَرُونَ¦30:17:1:فَسُبۡحَٰنَ ٱللَّهِ حِينَ تُمۡسُونَ\nT;0;30:17:2:وَحِينَ تُصۡبِحُونَ¦30:18:1:وَلَهُ ٱلۡحَمۡدُ فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ\nT;0;30:18:2:وَعَشِيࣰّا وَحِينَ تُظۡهِرُونَ¦30:19:1:يُخۡرِجُ ٱلۡحَيَّ مِنَ ٱلۡمَيِّتِ وَيُخۡرِجُ\nT;0;30:19:2:ٱلۡمَيِّتَ مِنَ ٱلۡحَيِّ وَيُحۡيِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَاۚ وَكَذَٰلِكَ تُخۡرَجُونَ\nT;0;30:20:1:وَمِنۡ ءَايَٰتِهِۦٓ أَنۡ خَلَقَكُم مِّن تُرَابࣲ ثُمَّ إِذَآ أَنتُم بَشَرࣱ\nT;0;30:20:2:تَنتَشِرُونَ¦30:21:1:وَمِنۡ ءَايَٰتِهِۦٓ أَنۡ خَلَقَ لَكُم مِّنۡ أَنفُسِكُمۡ\nT;0;30:21:0:أَزۡوَٰجࣰا لِّتَسۡكُنُوٓاْ إِلَيۡهَا وَجَعَلَ بَيۡنَكُم مَّوَدَّةࣰ وَرَحۡمَةًۚ\nT;0;30:21:2:إِنَّ فِي ذَٰلِكَ لَأٓيَٰتࣲ لِّقَوۡمࣲ يَتَفَكَّرُونَ¦30:22:1:وَمِنۡ ءَايَٰتِهِۦ\nT;0;30:22:0:خَلۡقُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَٱخۡتِلَٰفُ أَلۡسِنَتِكُمۡ وَأَلۡوَٰنِكُمۡۚ\nT;0;30:22:2:إِنَّ فِي ذَٰلِكَ لَأٓيَٰتࣲ لِّلۡعَٰلِمِينَ¦30:23:1:وَمِنۡ ءَايَٰتِهِۦ مَنَامُكُم\nT;0;30:23:0:بِٱلَّيۡلِ وَٱلنَّهَارِ وَٱبۡتِغَآؤُكُم مِّن فَضۡلِهِۦٓۚ إِنَّ فِي ذَٰلِكَ\nT;0;30:23:2:لَأٓيَٰتࣲ لِّقَوۡمࣲ يَسۡمَعُونَ¦30:24:1:وَمِنۡ ءَايَٰتِهِۦ يُرِيكُمُ ٱلۡبَرۡقَ\nT;0;30:24:0:خَوۡفࣰا وَطَمَعࣰا وَيُنَزِّلُ مِنَ ٱلسَّمَآءِ مَآءࣰ فَيُحۡيِۦ بِهِ ٱلۡأَرۡضَ\nT;0;30:24:2:بَعۡدَ مَوۡتِهَآۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتࣲ لِّقَوۡمࣲ يَعۡقِلُونَ',
  '21;41;1;163\nT;0;30:25:1:وَمِنۡ ءَايَٰتِهِۦٓ أَن تَقُومَ ٱلسَّمَآءُ وَٱلۡأَرۡضُ بِأَمۡرِهِۦۚ ثُمَّ إِذَا دَعَاكُمۡ\nT;0;30:25:2:دَعۡوَةࣰ مِّنَ ٱلۡأَرۡضِ إِذَآ أَنتُمۡ تَخۡرُجُونَ¦30:26:1:وَلَهُۥ مَن فِي ٱلسَّمَٰوَٰتِ\nT;0;30:26:2:وَٱلۡأَرۡضِۖ كُلࣱّ لَّهُۥ قَٰنِتُونَ¦30:27:1:وَهُوَ ٱلَّذِي يَبۡدَؤُاْ ٱلۡخَلۡقَ ثُمَّ\nT;0;30:27:0:يُعِيدُهُۥ وَهُوَ أَهۡوَنُ عَلَيۡهِۚ وَلَهُ ٱلۡمَثَلُ ٱلۡأَعۡلَىٰ فِي ٱلسَّمَٰوَٰتِ\nT;0;30:27:2:وَٱلۡأَرۡضِۚ وَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ¦30:28:1:ضَرَبَ لَكُم مَّثَلࣰا\nT;0;30:28:0:مِّنۡ أَنفُسِكُمۡۖ هَل لَّكُم مِّن مَّا مَلَكَتۡ أَيۡمَٰنُكُم مِّن\nT;0;30:28:0:شُرَكَآءَ فِي مَا رَزَقۡنَٰكُمۡ فَأَنتُمۡ فِيهِ سَوَآءࣱ تَخَافُونَهُمۡ\nT;0;30:28:0:كَخِيفَتِكُمۡ أَنفُسَكُمۡۚ كَذَٰلِكَ نُفَصِّلُ ٱلۡأٓيَٰتِ لِقَوۡمࣲ\nT;0;30:28:2:يَعۡقِلُونَ¦30:29:1:بَلِ ٱتَّبَعَ ٱلَّذِينَ ظَلَمُوٓاْ أَهۡوَآءَهُم بِغَيۡرِ عِلۡمࣲۖ\nT;0;30:29:2:فَمَن يَهۡدِي مَنۡ أَضَلَّ ٱللَّهُۖ وَمَا لَهُم مِّن نَّٰصِرِينَ¦30:30:1:فَأَقِمۡ\nT;0;30:30:0:وَجۡهَكَ لِلدِّينِ حَنِيفࣰاۚ فِطۡرَتَ ٱللَّهِ ٱلَّتِي فَطَرَ ٱلنَّاسَ عَلَيۡهَاۚ\nT;0;30:30:0:لَا تَبۡدِيلَ لِخَلۡقِ ٱللَّهِۚ ذَٰلِكَ ٱلدِّينُ ٱلۡقَيِّمُ وَلَٰكِنَّ أَكۡثَرَ\nT;0;30:30:2:ٱلنَّاسِ لَا يَعۡلَمُونَ¦30:31:1:۞ مُنِيبِينَ إِلَيۡهِ وَٱتَّقُوهُ وَأَقِيمُواْ\nT;0;30:31:2:ٱلصَّلَوٰةَ وَلَا تَكُونُواْ مِنَ ٱلۡمُشۡرِكِينَ¦30:32:1:مِنَ ٱلَّذِينَ فَرَّقُواْ\nT;0;30:32:2:دِينَهُمۡ وَكَانُواْ شِيَعࣰاۖ كُلُّ حِزۡبِۭ بِمَا لَدَيۡهِمۡ فَرِحُونَ',
  '21;41;2;\nT;0;30:33:1:وَإِذَا مَسَّ ٱلنَّاسَ ضُرࣱّ دَعَوۡاْ رَبَّهُم مُّنِيبِينَ إِلَيۡهِ ثُمَّ إِذَآ أَذَاقَهُم\nT;0;30:33:2:مِّنۡهُ رَحۡمَةً إِذَا فَرِيقࣱ مِّنۡهُم بِرَبِّهِمۡ يُشۡرِكُونَ¦30:34:1:لِيَكۡفُرُواْ بِمَآ\nT;0;30:34:2:ءَاتَيۡنَٰهُمۡۚ فَتَمَتَّعُواْ فَسَوۡفَ تَعۡلَمُونَ¦30:35:1:أَمۡ أَنزَلۡنَا عَلَيۡهِمۡ\nT;0;30:35:2:سُلۡطَٰنࣰا فَهُوَ يَتَكَلَّمُ بِمَا كَانُواْ بِهِۦ يُشۡرِكُونَ¦30:36:1:وَإِذَآ أَذَقۡنَا\nT;0;30:36:0:ٱلنَّاسَ رَحۡمَةࣰ فَرِحُواْ بِهَاۖ وَإِن تُصِبۡهُمۡ سَيِّئَةُۢ بِمَا قَدَّمَتۡ أَيۡدِيهِمۡ\nT;0;30:36:2:إِذَا هُمۡ يَقۡنَطُونَ¦30:37:1:أَوَلَمۡ يَرَوۡاْ أَنَّ ٱللَّهَ يَبۡسُطُ ٱلرِّزۡقَ لِمَن يَشَآءُ\nT;0;30:37:2:وَيَقۡدِرُۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتࣲ لِّقَوۡمࣲ يُؤۡمِنُونَ¦30:38:1:فَـَٔاتِ ذَا ٱلۡقُرۡبَىٰ\nT;0;30:38:0:حَقَّهُۥ وَٱلۡمِسۡكِينَ وَٱبۡنَ ٱلسَّبِيلِۚ ذَٰلِكَ خَيۡرࣱ لِّلَّذِينَ يُرِيدُونَ\nT;0;30:38:2:وَجۡهَ ٱللَّهِۖ وَأُوْلَٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ¦30:39:1:وَمَآ ءَاتَيۡتُم مِّن رِّبࣰا\nT;0;30:39:0:لِّيَرۡبُوَاْ فِيٓ أَمۡوَٰلِ ٱلنَّاسِ فَلَا يَرۡبُواْ عِندَ ٱللَّهِۖ وَمَآ ءَاتَيۡتُم مِّن\nT;0;30:39:2:زَكَوٰةࣲ تُرِيدُونَ وَجۡهَ ٱللَّهِ فَأُوْلَٰٓئِكَ هُمُ ٱلۡمُضۡعِفُونَ\nT;0;30:40:1:ٱللَّهُ ٱلَّذِي خَلَقَكُمۡ ثُمَّ رَزَقَكُمۡ ثُمَّ يُمِيتُكُمۡ ثُمَّ يُحۡيِيكُمۡۖ هَلۡ مِن\nT;0;30:40:0:شُرَكَآئِكُم مَّن يَفۡعَلُ مِن ذَٰلِكُم مِّن شَيۡءࣲۚ سُبۡحَٰنَهُۥ وَتَعَٰلَىٰ\nT;0;30:40:2:عَمَّا يُشۡرِكُونَ¦30:41:1:ظَهَرَ ٱلۡفَسَادُ فِي ٱلۡبَرِّ وَٱلۡبَحۡرِ بِمَا كَسَبَتۡ\nT;0;30:41:2:أَيۡدِي ٱلنَّاسِ لِيُذِيقَهُم بَعۡضَ ٱلَّذِي عَمِلُواْ لَعَلَّهُمۡ يَرۡجِعُونَ',
  '21;41;2;\nT;0;30:42:1:قُلۡ سِيرُواْ فِي ٱلۡأَرۡضِ فَٱنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبۡلُۚ\nT;0;30:42:2:كَانَ أَكۡثَرُهُم مُّشۡرِكِينَ¦30:43:1:فَأَقِمۡ وَجۡهَكَ لِلدِّينِ ٱلۡقَيِّمِ مِن\nT;0;30:43:2:قَبۡلِ أَن يَأۡتِيَ يَوۡمࣱ لَّا مَرَدَّ لَهُۥ مِنَ ٱللَّهِۖ يَوۡمَئِذࣲ يَصَّدَّعُونَ¦30:44:1:مَن\nT;0;30:44:2:كَفَرَ فَعَلَيۡهِ كُفۡرُهُۥۖ وَمَنۡ عَمِلَ صَٰلِحࣰا فَلِأَنفُسِهِمۡ يَمۡهَدُونَ\nT;0;30:45:1:لِيَجۡزِيَ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ مِن فَضۡلِهِۦٓۚ إِنَّهُۥ لَا يُحِبُّ\nT;0;30:45:2:ٱلۡكَٰفِرِينَ¦30:46:1:وَمِنۡ ءَايَٰتِهِۦٓ أَن يُرۡسِلَ ٱلرِّيَاحَ مُبَشِّرَٰتࣲ وَلِيُذِيقَكُم\nT;0;30:46:0:مِّن رَّحۡمَتِهِۦ وَلِتَجۡرِيَ ٱلۡفُلۡكُ بِأَمۡرِهِۦ وَلِتَبۡتَغُواْ مِن فَضۡلِهِۦ وَلَعَلَّكُمۡ\nT;0;30:46:2:تَشۡكُرُونَ¦30:47:1:وَلَقَدۡ أَرۡسَلۡنَا مِن قَبۡلِكَ رُسُلًا إِلَىٰ قَوۡمِهِمۡ فَجَآءُوهُم\nT;0;30:47:0:بِٱلۡبَيِّنَٰتِ فَٱنتَقَمۡنَا مِنَ ٱلَّذِينَ أَجۡرَمُواْۖ وَكَانَ حَقًّا عَلَيۡنَا نَصۡرُ\nT;0;30:47:2:ٱلۡمُؤۡمِنِينَ¦30:48:1:ٱللَّهُ ٱلَّذِي يُرۡسِلُ ٱلرِّيَٰحَ فَتُثِيرُ سَحَابࣰا فَيَبۡسُطُهُۥ\nT;0;30:48:0:فِي ٱلسَّمَآءِ كَيۡفَ يَشَآءُ وَيَجۡعَلُهُۥ كِسَفࣰا فَتَرَى ٱلۡوَدۡقَ يَخۡرُجُ مِنۡ\nT;0;30:48:2:خِلَٰلِهِۦۖ فَإِذَآ أَصَابَ بِهِۦ مَن يَشَآءُ مِنۡ عِبَادِهِۦٓ إِذَا هُمۡ يَسۡتَبۡشِرُونَ\nT;0;30:49:3:وَإِن كَانُواْ مِن قَبۡلِ أَن يُنَزَّلَ عَلَيۡهِم مِّن قَبۡلِهِۦ لَمُبۡلِسِينَ\nT;0;30:50:1:فَٱنظُرۡ إِلَىٰٓ ءَاثَٰرِ رَحۡمَتِ ٱللَّهِ كَيۡفَ يُحۡيِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَآۚ\nT;0;30:50:2:إِنَّ ذَٰلِكَ لَمُحۡيِ ٱلۡمَوۡتَىٰۖ وَهُوَ عَلَىٰ كُلِّ شَيۡءࣲ قَدِيرࣱ',
  '21;41;2;164\nT;0;30:51:3:وَلَئِنۡ أَرۡسَلۡنَا رِيحࣰا فَرَأَوۡهُ مُصۡفَرࣰّا لَّظَلُّواْ مِنۢ بَعۡدِهِۦ يَكۡفُرُونَ\nT;0;30:52:1:فَإِنَّكَ لَا تُسۡمِعُ ٱلۡمَوۡتَىٰ وَلَا تُسۡمِعُ ٱلصُّمَّ ٱلدُّعَآءَ إِذَا وَلَّوۡاْ\nT;0;30:52:2:مُدۡبِرِينَ¦30:53:1:وَمَآ أَنتَ بِهَٰدِ ٱلۡعُمۡيِ عَن ضَلَٰلَتِهِمۡۖ إِن تُسۡمِعُ إِلَّا\nT;0;30:53:2:مَن يُؤۡمِنُ بِـَٔايَٰتِنَا فَهُم مُّسۡلِمُونَ¦30:54:1:۞ ٱللَّهُ ٱلَّذِي خَلَقَكُم\nT;0;30:54:0:مِّن ضَعۡفࣲ ثُمَّ جَعَلَ مِنۢ بَعۡدِ ضَعۡفࣲ قُوَّةࣰ ثُمَّ جَعَلَ مِنۢ بَعۡدِ\nT;0;30:54:2:قُوَّةࣲ ضَعۡفࣰا وَشَيۡبَةࣰۚ يَخۡلُقُ مَا يَشَآءُۚ وَهُوَ ٱلۡعَلِيمُ ٱلۡقَدِيرُ\nT;0;30:55:1:وَيَوۡمَ تَقُومُ ٱلسَّاعَةُ يُقۡسِمُ ٱلۡمُجۡرِمُونَ مَا لَبِثُواْ غَيۡرَ\nT;0;30:55:2:سَاعَةࣲۚ كَذَٰلِكَ كَانُواْ يُؤۡفَكُونَ¦30:56:1:وَقَالَ ٱلَّذِينَ أُوتُواْ\nT;0;30:56:0:ٱلۡعِلۡمَ وَٱلۡإِيمَٰنَ لَقَدۡ لَبِثۡتُمۡ فِي كِتَٰبِ ٱللَّهِ إِلَىٰ يَوۡمِ ٱلۡبَعۡثِۖ\nT;0;30:56:2:فَهَٰذَا يَوۡمُ ٱلۡبَعۡثِ وَلَٰكِنَّكُمۡ كُنتُمۡ لَا تَعۡلَمُونَ¦30:57:1:فَيَوۡمَئِذࣲ\nT;0;30:57:2:لَّا يَنفَعُ ٱلَّذِينَ ظَلَمُواْ مَعۡذِرَتُهُمۡ وَلَا هُمۡ يُسۡتَعۡتَبُونَ\nT;0;30:58:1:وَلَقَدۡ ضَرَبۡنَا لِلنَّاسِ فِي هَٰذَا ٱلۡقُرۡءَانِ مِن كُلِّ مَثَلࣲۚ\nT;0;30:58:0:وَلَئِن جِئۡتَهُم بِـَٔايَةࣲ لَّيَقُولَنَّ ٱلَّذِينَ كَفَرُوٓاْ إِنۡ أَنتُمۡ إِلَّا\nT;0;30:58:2:مُبۡطِلُونَ¦30:59:3:كَذَٰلِكَ يَطۡبَعُ ٱللَّهُ عَلَىٰ قُلُوبِ ٱلَّذِينَ لَا يَعۡلَمُونَ\nT;2;30:60:3:فَٱصۡبِرۡ إِنَّ وَعۡدَ ٱللَّهِ حَقࣱّۖ وَلَا يَسۡتَخِفَّنَّكَ ٱلَّذِينَ لَا يُوقِنُونَ',
  '21;41;3;\nH;31\nB;31\nT;0;31:1:3:الٓمٓ¦31:2:3:تِلۡكَ ءَايَٰتُ ٱلۡكِتَٰبِ ٱلۡحَكِيمِ¦31:3:1:هُدࣰى وَرَحۡمَةࣰ\nT;0;31:3:2:لِّلۡمُحۡسِنِينَ¦31:4:1:ٱلَّذِينَ يُقِيمُونَ ٱلصَّلَوٰةَ وَيُؤۡتُونَ ٱلزَّكَوٰةَ وَهُم\nT;0;31:4:2:بِٱلۡأٓخِرَةِ هُمۡ يُوقِنُونَ¦31:5:1:أُوْلَٰٓئِكَ عَلَىٰ هُدࣰى مِّن رَّبِّهِمۡۖ وَأُوْلَٰٓئِكَ\nT;0;31:5:2:هُمُ ٱلۡمُفۡلِحُونَ¦31:6:1:وَمِنَ ٱلنَّاسِ مَن يَشۡتَرِي لَهۡوَ ٱلۡحَدِيثِ\nT;0;31:6:0:لِيُضِلَّ عَن سَبِيلِ ٱللَّهِ بِغَيۡرِ عِلۡمࣲ وَيَتَّخِذَهَا هُزُوًاۚ أُوْلَٰٓئِكَ لَهُمۡ\nT;0;31:6:2:عَذَابࣱ مُّهِينࣱ¦31:7:1:وَإِذَا تُتۡلَىٰ عَلَيۡهِ ءَايَٰتُنَا وَلَّىٰ مُسۡتَكۡبِرࣰا\nT;0;31:7:2:كَأَن لَّمۡ يَسۡمَعۡهَا كَأَنَّ فِيٓ أُذُنَيۡهِ وَقۡرࣰاۖ فَبَشِّرۡهُ بِعَذَابٍ أَلِيمٍ\nT;0;31:8:3:إِنَّ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ لَهُمۡ جَنَّٰتُ ٱلنَّعِيمِ\nT;0;31:9:3:خَٰلِدِينَ فِيهَاۖ وَعۡدَ ٱللَّهِ حَقࣰّاۚ وَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ¦31:10:1:خَلَقَ\nT;0;31:10:0:ٱلسَّمَٰوَٰتِ بِغَيۡرِ عَمَدࣲ تَرَوۡنَهَاۖ وَأَلۡقَىٰ فِي ٱلۡأَرۡضِ رَوَٰسِيَ أَن تَمِيدَ\nT;0;31:10:0:بِكُمۡ وَبَثَّ فِيهَا مِن كُلِّ دَآبَّةࣲۚ وَأَنزَلۡنَا مِنَ ٱلسَّمَآءِ مَآءࣰ فَأَنۢبَتۡنَا\nT;0;31:10:2:فِيهَا مِن كُلِّ زَوۡجࣲ كَرِيمٍ¦31:11:1:هَٰذَا خَلۡقُ ٱللَّهِ فَأَرُونِي مَاذَا\nT;0;31:11:2:خَلَقَ ٱلَّذِينَ مِن دُونِهِۦۚ بَلِ ٱلظَّٰلِمُونَ فِي ضَلَٰلࣲ مُّبِينࣲ',
  '21;41;3;\nT;0;31:12:1:وَلَقَدۡ ءَاتَيۡنَا لُقۡمَٰنَ ٱلۡحِكۡمَةَ أَنِ ٱشۡكُرۡ لِلَّهِۚ وَمَن يَشۡكُرۡ فَإِنَّمَا\nT;0;31:12:2:يَشۡكُرُ لِنَفۡسِهِۦۖ وَمَن كَفَرَ فَإِنَّ ٱللَّهَ غَنِيٌّ حَمِيدࣱ¦31:13:1:وَإِذۡ قَالَ\nT;0;31:13:0:لُقۡمَٰنُ لِٱبۡنِهِۦ وَهُوَ يَعِظُهُۥ يَٰبُنَيَّ لَا تُشۡرِكۡ بِٱللَّهِۖ إِنَّ ٱلشِّرۡكَ\nT;0;31:13:2:لَظُلۡمٌ عَظِيمࣱ¦31:14:1:وَوَصَّيۡنَا ٱلۡإِنسَٰنَ بِوَٰلِدَيۡهِ حَمَلَتۡهُ أُمُّهُۥ\nT;0;31:14:0:وَهۡنًا عَلَىٰ وَهۡنࣲ وَفِصَٰلُهُۥ فِي عَامَيۡنِ أَنِ ٱشۡكُرۡ لِي وَلِوَٰلِدَيۡكَ\nT;0;31:14:2:إِلَيَّ ٱلۡمَصِيرُ¦31:15:1:وَإِن جَٰهَدَاكَ عَلَىٰٓ أَن تُشۡرِكَ بِي مَا لَيۡسَ\nT;0;31:15:0:لَكَ بِهِۦ عِلۡمࣱ فَلَا تُطِعۡهُمَاۖ وَصَاحِبۡهُمَا فِي ٱلدُّنۡيَا مَعۡرُوفࣰاۖ\nT;0;31:15:0:وَٱتَّبِعۡ سَبِيلَ مَنۡ أَنَابَ إِلَيَّۚ ثُمَّ إِلَيَّ مَرۡجِعُكُمۡ فَأُنَبِّئُكُم\nT;0;31:15:2:بِمَا كُنتُمۡ تَعۡمَلُونَ¦31:16:1:يَٰبُنَيَّ إِنَّهَآ إِن تَكُ مِثۡقَالَ حَبَّةࣲ مِّنۡ\nT;0;31:16:0:خَرۡدَلࣲ فَتَكُن فِي صَخۡرَةٍ أَوۡ فِي ٱلسَّمَٰوَٰتِ أَوۡ فِي ٱلۡأَرۡضِ يَأۡتِ\nT;0;31:16:2:بِهَا ٱللَّهُۚ إِنَّ ٱللَّهَ لَطِيفٌ خَبِيرࣱ¦31:17:1:يَٰبُنَيَّ أَقِمِ ٱلصَّلَوٰةَ وَأۡمُرۡ\nT;0;31:17:0:بِٱلۡمَعۡرُوفِ وَٱنۡهَ عَنِ ٱلۡمُنكَرِ وَٱصۡبِرۡ عَلَىٰ مَآ أَصَابَكَۖ إِنَّ ذَٰلِكَ\nT;0;31:17:2:مِنۡ عَزۡمِ ٱلۡأُمُورِ¦31:18:1:وَلَا تُصَعِّرۡ خَدَّكَ لِلنَّاسِ وَلَا تَمۡشِ فِي ٱلۡأَرۡضِ\nT;0;31:18:2:مَرَحًاۖ إِنَّ ٱللَّهَ لَا يُحِبُّ كُلَّ مُخۡتَالࣲ فَخُورࣲ¦31:19:1:وَٱقۡصِدۡ فِي مَشۡيِكَ\nT;0;31:19:2:وَٱغۡضُضۡ مِن صَوۡتِكَۚ إِنَّ أَنكَرَ ٱلۡأَصۡوَٰتِ لَصَوۡتُ ٱلۡحَمِيرِ',
  '21;41;3;165\nT;0;31:20:1:أَلَمۡ تَرَوۡاْ أَنَّ ٱللَّهَ سَخَّرَ لَكُم مَّا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِ وَأَسۡبَغَ\nT;0;31:20:0:عَلَيۡكُمۡ نِعَمَهُۥ ظَٰهِرَةࣰ وَبَاطِنَةࣰۗ وَمِنَ ٱلنَّاسِ مَن يُجَٰدِلُ فِي ٱللَّهِ\nT;0;31:20:2:بِغَيۡرِ عِلۡمࣲ وَلَا هُدࣰى وَلَا كِتَٰبࣲ مُّنِيرࣲ¦31:21:1:وَإِذَا قِيلَ لَهُمُ ٱتَّبِعُواْ\nT;0;31:21:0:مَآ أَنزَلَ ٱللَّهُ قَالُواْ بَلۡ نَتَّبِعُ مَا وَجَدۡنَا عَلَيۡهِ ءَابَآءَنَآۚ أَوَلَوۡ كَانَ\nT;0;31:21:2:ٱلشَّيۡطَٰنُ يَدۡعُوهُمۡ إِلَىٰ عَذَابِ ٱلسَّعِيرِ¦31:22:1:۞ وَمَن يُسۡلِمۡ\nT;0;31:22:0:وَجۡهَهُۥٓ إِلَى ٱللَّهِ وَهُوَ مُحۡسِنࣱ فَقَدِ ٱسۡتَمۡسَكَ بِٱلۡعُرۡوَةِ ٱلۡوُثۡقَىٰۗ\nT;0;31:22:2:وَإِلَى ٱللَّهِ عَٰقِبَةُ ٱلۡأُمُورِ¦31:23:1:وَمَن كَفَرَ فَلَا يَحۡزُنكَ كُفۡرُهُۥٓۚ إِلَيۡنَا\nT;0;31:23:2:مَرۡجِعُهُمۡ فَنُنَبِّئُهُم بِمَا عَمِلُوٓاْۚ إِنَّ ٱللَّهَ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ\nT;0;31:24:3:نُمَتِّعُهُمۡ قَلِيلࣰا ثُمَّ نَضۡطَرُّهُمۡ إِلَىٰ عَذَابٍ غَلِيظࣲ\nT;0;31:25:1:وَلَئِن سَأَلۡتَهُم مَّنۡ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ لَيَقُولُنَّ ٱللَّهُۚ قُلِ\nT;0;31:25:2:ٱلۡحَمۡدُ لِلَّهِۚ بَلۡ أَكۡثَرُهُمۡ لَا يَعۡلَمُونَ¦31:26:1:لِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ\nT;0;31:26:2:وَٱلۡأَرۡضِۚ إِنَّ ٱللَّهَ هُوَ ٱلۡغَنِيُّ ٱلۡحَمِيدُ¦31:27:1:وَلَوۡ أَنَّمَا فِي ٱلۡأَرۡضِ\nT;0;31:27:0:مِن شَجَرَةٍ أَقۡلَٰمࣱ وَٱلۡبَحۡرُ يَمُدُّهُۥ مِنۢ بَعۡدِهِۦ سَبۡعَةُ أَبۡحُرࣲ\nT;0;31:27:2:مَّا نَفِدَتۡ كَلِمَٰتُ ٱللَّهِۚ إِنَّ ٱللَّهَ عَزِيزٌ حَكِيمࣱ¦31:28:1:مَّا خَلۡقُكُمۡ\nT;0;31:28:2:وَلَا بَعۡثُكُمۡ إِلَّا كَنَفۡسࣲ وَٰحِدَةٍۚ إِنَّ ٱللَّهَ سَمِيعُۢ بَصِيرٌ',
  '21;42;0;\nT;0;31:29:1:أَلَمۡ تَرَ أَنَّ ٱللَّهَ يُولِجُ ٱلَّيۡلَ فِي ٱلنَّهَارِ وَيُولِجُ ٱلنَّهَارَ\nT;0;31:29:0:فِي ٱلَّيۡلِ وَسَخَّرَ ٱلشَّمۡسَ وَٱلۡقَمَرَۖ كُلࣱّ يَجۡرِيٓ إِلَىٰٓ\nT;0;31:29:2:أَجَلࣲ مُّسَمࣰّى وَأَنَّ ٱللَّهَ بِمَا تَعۡمَلُونَ خَبِيرࣱ\nT;0;31:30:1:ذَٰلِكَ بِأَنَّ ٱللَّهَ هُوَ ٱلۡحَقُّ وَأَنَّ مَا يَدۡعُونَ مِن دُونِهِ\nT;0;31:30:2:ٱلۡبَٰطِلُ وَأَنَّ ٱللَّهَ هُوَ ٱلۡعَلِيُّ ٱلۡكَبِيرُ¦31:31:1:أَلَمۡ تَرَ أَنَّ ٱلۡفُلۡكَ\nT;0;31:31:0:تَجۡرِي فِي ٱلۡبَحۡرِ بِنِعۡمَتِ ٱللَّهِ لِيُرِيَكُم مِّنۡ ءَايَٰتِهِۦٓۚ إِنَّ\nT;0;31:31:2:فِي ذَٰلِكَ لَأٓيَٰتࣲ لِّكُلِّ صَبَّارࣲ شَكُورࣲ¦31:32:1:وَإِذَا غَشِيَهُم مَّوۡجࣱ\nT;0;31:32:0:كَٱلظُّلَلِ دَعَوُاْ ٱللَّهَ مُخۡلِصِينَ لَهُ ٱلدِّينَ فَلَمَّا نَجَّىٰهُمۡ إِلَى ٱلۡبَرِّ\nT;0;31:32:2:فَمِنۡهُم مُّقۡتَصِدࣱۚ وَمَا يَجۡحَدُ بِـَٔايَٰتِنَآ إِلَّا كُلُّ خَتَّارࣲ كَفُورࣲ\nT;0;31:33:1:يَٰٓأَيُّهَا ٱلنَّاسُ ٱتَّقُواْ رَبَّكُمۡ وَٱخۡشَوۡاْ يَوۡمࣰا لَّا يَجۡزِي وَالِدٌ\nT;0;31:33:0:عَن وَلَدِهِۦ وَلَا مَوۡلُودٌ هُوَ جَازٍ عَن وَالِدِهِۦ شَيۡـًٔاۚ إِنَّ وَعۡدَ ٱللَّهِ\nT;0;31:33:0:حَقࣱّۖ فَلَا تَغُرَّنَّكُمُ ٱلۡحَيَوٰةُ ٱلدُّنۡيَا وَلَا يَغُرَّنَّكُم بِٱللَّهِ\nT;0;31:33:2:ٱلۡغَرُورُ¦31:34:1:إِنَّ ٱللَّهَ عِندَهُۥ عِلۡمُ ٱلسَّاعَةِ وَيُنَزِّلُ ٱلۡغَيۡثَ\nT;0;31:34:0:وَيَعۡلَمُ مَا فِي ٱلۡأَرۡحَامِۖ وَمَا تَدۡرِي نَفۡسࣱ مَّاذَا تَكۡسِبُ غَدࣰاۖ\nT;2;31:34:2:وَمَا تَدۡرِي نَفۡسُۢ بِأَيِّ أَرۡضࣲ تَمُوتُۚ إِنَّ ٱللَّهَ عَلِيمٌ خَبِيرُۢ',
  '21;42;0;166\nH;32\nB;32\nT;0;32:1:3:الٓمٓ¦32:2:3:تَنزِيلُ ٱلۡكِتَٰبِ لَا رَيۡبَ فِيهِ مِن رَّبِّ ٱلۡعَٰلَمِينَ\nT;0;32:3:1:أَمۡ يَقُولُونَ ٱفۡتَرَىٰهُۚ بَلۡ هُوَ ٱلۡحَقُّ مِن رَّبِّكَ لِتُنذِرَ قَوۡمࣰا مَّآ أَتَىٰهُم\nT;0;32:3:2:مِّن نَّذِيرࣲ مِّن قَبۡلِكَ لَعَلَّهُمۡ يَهۡتَدُونَ¦32:4:1:ٱللَّهُ ٱلَّذِي خَلَقَ\nT;0;32:4:0:ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَمَا بَيۡنَهُمَا فِي سِتَّةِ أَيَّامࣲ ثُمَّ ٱسۡتَوَىٰ عَلَى\nT;0;32:4:2:ٱلۡعَرۡشِۖ مَا لَكُم مِّن دُونِهِۦ مِن وَلِيࣲّ وَلَا شَفِيعٍۚ أَفَلَا تَتَذَكَّرُونَ\nT;0;32:5:1:يُدَبِّرُ ٱلۡأَمۡرَ مِنَ ٱلسَّمَآءِ إِلَى ٱلۡأَرۡضِ ثُمَّ يَعۡرُجُ إِلَيۡهِ فِي يَوۡمࣲ كَانَ\nT;0;32:5:2:مِقۡدَارُهُۥٓ أَلۡفَ سَنَةࣲ مِّمَّا تَعُدُّونَ¦32:6:1:ذَٰلِكَ عَٰلِمُ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِ\nT;0;32:6:2:ٱلۡعَزِيزُ ٱلرَّحِيمُ¦32:7:1:ٱلَّذِيٓ أَحۡسَنَ كُلَّ شَيۡءٍ خَلَقَهُۥۖ وَبَدَأَ خَلۡقَ ٱلۡإِنسَٰنِ\nT;0;32:7:2:مِن طِينࣲ¦32:8:3:ثُمَّ جَعَلَ نَسۡلَهُۥ مِن سُلَٰلَةࣲ مِّن مَّآءࣲ مَّهِينࣲ\nT;0;32:9:1:ثُمَّ سَوَّىٰهُ وَنَفَخَ فِيهِ مِن رُّوحِهِۦۖ وَجَعَلَ لَكُمُ ٱلسَّمۡعَ وَٱلۡأَبۡصَٰرَ\nT;0;32:9:2:وَٱلۡأَفۡـِٔدَةَۚ قَلِيلࣰا مَّا تَشۡكُرُونَ¦32:10:1:وَقَالُوٓاْ أَءِذَا ضَلَلۡنَا فِي ٱلۡأَرۡضِ\nT;0;32:10:2:أَءِنَّا لَفِي خَلۡقࣲ جَدِيدِۭۚ بَلۡ هُم بِلِقَآءِ رَبِّهِمۡ كَٰفِرُونَ¦32:11:1:۞ قُلۡ يَتَوَفَّىٰكُم\nT;0;32:11:2:مَّلَكُ ٱلۡمَوۡتِ ٱلَّذِي وُكِّلَ بِكُمۡ ثُمَّ إِلَىٰ رَبِّكُمۡ تُرۡجَعُونَ',
  '21;42;1;\nT;0;32:12:1:وَلَوۡ تَرَىٰٓ إِذِ ٱلۡمُجۡرِمُونَ نَاكِسُواْ رُءُوسِهِمۡ عِندَ رَبِّهِمۡ\nT;0;32:12:2:رَبَّنَآ أَبۡصَرۡنَا وَسَمِعۡنَا فَٱرۡجِعۡنَا نَعۡمَلۡ صَٰلِحًا إِنَّا مُوقِنُونَ\nT;0;32:13:1:وَلَوۡ شِئۡنَا لَأٓتَيۡنَا كُلَّ نَفۡسٍ هُدَىٰهَا وَلَٰكِنۡ حَقَّ\nT;0;32:13:2:ٱلۡقَوۡلُ مِنِّي لَأَمۡلَأَنَّ جَهَنَّمَ مِنَ ٱلۡجِنَّةِ وَٱلنَّاسِ أَجۡمَعِينَ\nT;0;32:14:1:فَذُوقُواْ بِمَا نَسِيتُمۡ لِقَآءَ يَوۡمِكُمۡ هَٰذَآ إِنَّا نَسِينَٰكُمۡۖ\nT;0;32:14:2:وَذُوقُواْ عَذَابَ ٱلۡخُلۡدِ بِمَا كُنتُمۡ تَعۡمَلُونَ¦32:15:1:إِنَّمَا يُؤۡمِنُ\nT;0;32:15:0:بِـَٔايَٰتِنَا ٱلَّذِينَ إِذَا ذُكِّرُواْ بِهَا خَرُّواْۤ سُجَّدࣰاۤ وَسَبَّحُواْ بِحَمۡدِ\nT;0;32:15:2:رَبِّهِمۡ وَهُمۡ لَا يَسۡتَكۡبِرُونَ۩¦32:16:1:تَتَجَافَىٰ جُنُوبُهُمۡ\nT;0;32:16:0:عَنِ ٱلۡمَضَاجِعِ يَدۡعُونَ رَبَّهُمۡ خَوۡفࣰا وَطَمَعࣰا وَمِمَّا رَزَقۡنَٰهُمۡ\nT;0;32:16:2:يُنفِقُونَ¦32:17:1:فَلَا تَعۡلَمُ نَفۡسࣱ مَّآ أُخۡفِيَ لَهُم مِّن قُرَّةِ أَعۡيُنࣲ\nT;0;32:17:2:جَزَآءَۢ بِمَا كَانُواْ يَعۡمَلُونَ¦32:18:1:أَفَمَن كَانَ مُؤۡمِنࣰا كَمَن كَانَ فَاسِقࣰاۚ\nT;0;32:18:2:لَّا يَسۡتَوُۥنَ¦32:19:1:أَمَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ فَلَهُمۡ\nT;0;32:19:2:جَنَّٰتُ ٱلۡمَأۡوَىٰ نُزُلَۢا بِمَا كَانُواْ يَعۡمَلُونَ¦32:20:1:وَأَمَّا ٱلَّذِينَ فَسَقُواْ\nT;0;32:20:0:فَمَأۡوَىٰهُمُ ٱلنَّارُۖ كُلَّمَآ أَرَادُوٓاْ أَن يَخۡرُجُواْ مِنۡهَآ أُعِيدُواْ فِيهَا\nT;0;32:20:2:وَقِيلَ لَهُمۡ ذُوقُواْ عَذَابَ ٱلنَّارِ ٱلَّذِي كُنتُم بِهِۦ تُكَذِّبُونَ',
  '21;42;1;\nT;0;32:21:1:وَلَنُذِيقَنَّهُم مِّنَ ٱلۡعَذَابِ ٱلۡأَدۡنَىٰ دُونَ ٱلۡعَذَابِ ٱلۡأَكۡبَرِ\nT;0;32:21:2:لَعَلَّهُمۡ يَرۡجِعُونَ¦32:22:1:وَمَنۡ أَظۡلَمُ مِمَّن ذُكِّرَ بِـَٔايَٰتِ\nT;0;32:22:2:رَبِّهِۦ ثُمَّ أَعۡرَضَ عَنۡهَآۚ إِنَّا مِنَ ٱلۡمُجۡرِمِينَ مُنتَقِمُونَ\nT;0;32:23:1:وَلَقَدۡ ءَاتَيۡنَا مُوسَى ٱلۡكِتَٰبَ فَلَا تَكُن فِي مِرۡيَةࣲ\nT;0;32:23:2:مِّن لِّقَآئِهِۦۖ وَجَعَلۡنَٰهُ هُدࣰى لِّبَنِيٓ إِسۡرَٰٓءِيلَ\nT;0;32:24:1:وَجَعَلۡنَا مِنۡهُمۡ أَئِمَّةࣰ يَهۡدُونَ بِأَمۡرِنَا لَمَّا صَبَرُواْۖ\nT;0;32:24:2:وَكَانُواْ بِـَٔايَٰتِنَا يُوقِنُونَ¦32:25:1:إِنَّ رَبَّكَ هُوَ يَفۡصِلُ بَيۡنَهُمۡ\nT;0;32:25:2:يَوۡمَ ٱلۡقِيَٰمَةِ فِيمَا كَانُواْ فِيهِ يَخۡتَلِفُونَ¦32:26:1:أَوَلَمۡ يَهۡدِ لَهُمۡ\nT;0;32:26:0:كَمۡ أَهۡلَكۡنَا مِن قَبۡلِهِم مِّنَ ٱلۡقُرُونِ يَمۡشُونَ\nT;0;32:26:2:فِي مَسَٰكِنِهِمۡۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٍۚ أَفَلَا يَسۡمَعُونَ\nT;0;32:27:1:أَوَلَمۡ يَرَوۡاْ أَنَّا نَسُوقُ ٱلۡمَآءَ إِلَى ٱلۡأَرۡضِ ٱلۡجُرُزِ فَنُخۡرِجُ بِهِۦ\nT;0;32:27:2:زَرۡعࣰا تَأۡكُلُ مِنۡهُ أَنۡعَٰمُهُمۡ وَأَنفُسُهُمۡۚ أَفَلَا يُبۡصِرُونَ\nT;0;32:28:3:وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلۡفَتۡحُ إِن كُنتُمۡ صَٰدِقِينَ\nT;0;32:29:1:قُلۡ يَوۡمَ ٱلۡفَتۡحِ لَا يَنفَعُ ٱلَّذِينَ كَفَرُوٓاْ إِيمَٰنُهُمۡ وَلَا هُمۡ\nT;2;32:29:2:يُنظَرُونَ¦32:30:3:فَأَعۡرِضۡ عَنۡهُمۡ وَٱنتَظِرۡ إِنَّهُم مُّنتَظِرُونَ',
  '21;42;2;167\nH;33\nB;33\nT;0;33:1:1:يَٰٓأَيُّهَا ٱلنَّبِيُّ ٱتَّقِ ٱللَّهَ وَلَا تُطِعِ ٱلۡكَٰفِرِينَ وَٱلۡمُنَٰفِقِينَۚ إِنَّ ٱللَّهَ\nT;0;33:1:2:كَانَ عَلِيمًا حَكِيمࣰا¦33:2:1:وَٱتَّبِعۡ مَا يُوحَىٰٓ إِلَيۡكَ مِن رَّبِّكَۚ\nT;0;33:2:2:إِنَّ ٱللَّهَ كَانَ بِمَا تَعۡمَلُونَ خَبِيرࣰا¦33:3:1:وَتَوَكَّلۡ عَلَى ٱللَّهِۚ\nT;0;33:3:2:وَكَفَىٰ بِٱللَّهِ وَكِيلࣰا¦33:4:1:مَّا جَعَلَ ٱللَّهُ لِرَجُلࣲ مِّن قَلۡبَيۡنِ فِي جَوۡفِهِۦۚ\nT;0;33:4:0:وَمَا جَعَلَ أَزۡوَٰجَكُمُ ٱلَّٰٓـِٔي تُظَٰهِرُونَ مِنۡهُنَّ أُمَّهَٰتِكُمۡۚ وَمَا جَعَلَ\nT;0;33:4:0:أَدۡعِيَآءَكُمۡ أَبۡنَآءَكُمۡۚ ذَٰلِكُمۡ قَوۡلُكُم بِأَفۡوَٰهِكُمۡۖ وَٱللَّهُ يَقُولُ ٱلۡحَقَّ\nT;0;33:4:2:وَهُوَ يَهۡدِي ٱلسَّبِيلَ¦33:5:1:ٱدۡعُوهُمۡ لِأٓبَآئِهِمۡ هُوَ أَقۡسَطُ عِندَ ٱللَّهِۚ\nT;0;33:5:0:فَإِن لَّمۡ تَعۡلَمُوٓاْ ءَابَآءَهُمۡ فَإِخۡوَٰنُكُمۡ فِي ٱلدِّينِ وَمَوَٰلِيكُمۡۚ وَلَيۡسَ\nT;0;33:5:0:عَلَيۡكُمۡ جُنَاحࣱ فِيمَآ أَخۡطَأۡتُم بِهِۦ وَلَٰكِن مَّا تَعَمَّدَتۡ قُلُوبُكُمۡۚ\nT;0;33:5:2:وَكَانَ ٱللَّهُ غَفُورࣰا رَّحِيمًا¦33:6:1:ٱلنَّبِيُّ أَوۡلَىٰ بِٱلۡمُؤۡمِنِينَ مِنۡ أَنفُسِهِمۡۖ\nT;0;33:6:0:وَأَزۡوَٰجُهُۥٓ أُمَّهَٰتُهُمۡۗ وَأُوْلُواْ ٱلۡأَرۡحَامِ بَعۡضُهُمۡ أَوۡلَىٰ بِبَعۡضࣲ\nT;0;33:6:0:فِي كِتَٰبِ ٱللَّهِ مِنَ ٱلۡمُؤۡمِنِينَ وَٱلۡمُهَٰجِرِينَ إِلَّآ أَن تَفۡعَلُوٓاْ إِلَىٰٓ\nT;0;33:6:2:أَوۡلِيَآئِكُم مَّعۡرُوفࣰاۚ كَانَ ذَٰلِكَ فِي ٱلۡكِتَٰبِ مَسۡطُورࣰا',
  '21;42;2;\nT;0;33:7:1:وَإِذۡ أَخَذۡنَا مِنَ ٱلنَّبِيِّـۧنَ مِيثَٰقَهُمۡ وَمِنكَ وَمِن نُّوحࣲ وَإِبۡرَٰهِيمَ\nT;0;33:7:2:وَمُوسَىٰ وَعِيسَى ٱبۡنِ مَرۡيَمَۖ وَأَخَذۡنَا مِنۡهُم مِّيثَٰقًا غَلِيظࣰا\nT;0;33:8:3:لِّيَسۡـَٔلَ ٱلصَّٰدِقِينَ عَن صِدۡقِهِمۡۚ وَأَعَدَّ لِلۡكَٰفِرِينَ عَذَابًا أَلِيمࣰا\nT;0;33:9:1:يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱذۡكُرُواْ نِعۡمَةَ ٱللَّهِ عَلَيۡكُمۡ إِذۡ جَآءَتۡكُمۡ\nT;0;33:9:0:جُنُودࣱ فَأَرۡسَلۡنَا عَلَيۡهِمۡ رِيحࣰا وَجُنُودࣰا لَّمۡ تَرَوۡهَاۚ وَكَانَ ٱللَّهُ\nT;0;33:9:2:بِمَا تَعۡمَلُونَ بَصِيرًا¦33:10:1:إِذۡ جَآءُوكُم مِّن فَوۡقِكُمۡ وَمِنۡ أَسۡفَلَ\nT;0;33:10:0:مِنكُمۡ وَإِذۡ زَاغَتِ ٱلۡأَبۡصَٰرُ وَبَلَغَتِ ٱلۡقُلُوبُ ٱلۡحَنَاجِرَ\nT;0;33:10:2:وَتَظُنُّونَ بِٱللَّهِ ٱلظُّنُونَا۠¦33:11:1:هُنَالِكَ ٱبۡتُلِيَ ٱلۡمُؤۡمِنُونَ وَزُلۡزِلُواْ\nT;0;33:11:2:زِلۡزَالࣰا شَدِيدࣰا¦33:12:1:وَإِذۡ يَقُولُ ٱلۡمُنَٰفِقُونَ وَٱلَّذِينَ فِي قُلُوبِهِم\nT;0;33:12:2:مَّرَضࣱ مَّا وَعَدَنَا ٱللَّهُ وَرَسُولُهُۥٓ إِلَّا غُرُورࣰا¦33:13:1:وَإِذۡ قَالَت طَّآئِفَةࣱ\nT;0;33:13:0:مِّنۡهُمۡ يَٰٓأَهۡلَ يَثۡرِبَ لَا مُقَامَ لَكُمۡ فَٱرۡجِعُواْۚ وَيَسۡتَـٔۡذِنُ فَرِيقࣱ\nT;0;33:13:0:مِّنۡهُمُ ٱلنَّبِيَّ يَقُولُونَ إِنَّ بُيُوتَنَا عَوۡرَةࣱ وَمَا هِيَ بِعَوۡرَةٍۖ إِن يُرِيدُونَ\nT;0;33:13:2:إِلَّا فِرَارࣰا¦33:14:1:وَلَوۡ دُخِلَتۡ عَلَيۡهِم مِّنۡ أَقۡطَارِهَا ثُمَّ سُئِلُواْ ٱلۡفِتۡنَةَ\nT;0;33:14:2:لَأٓتَوۡهَا وَمَا تَلَبَّثُواْ بِهَآ إِلَّا يَسِيرࣰا¦33:15:1:وَلَقَدۡ كَانُواْ عَٰهَدُواْ\nT;0;33:15:2:ٱللَّهَ مِن قَبۡلُ لَا يُوَلُّونَ ٱلۡأَدۡبَٰرَۚ وَكَانَ عَهۡدُ ٱللَّهِ مَسۡـُٔولࣰا',
  '21;42;2;168\nT;0;33:16:1:قُل لَّن يَنفَعَكُمُ ٱلۡفِرَارُ إِن فَرَرۡتُم مِّنَ ٱلۡمَوۡتِ أَوِ ٱلۡقَتۡلِ وَإِذࣰا\nT;0;33:16:2:لَّا تُمَتَّعُونَ إِلَّا قَلِيلࣰا¦33:17:1:قُلۡ مَن ذَا ٱلَّذِي يَعۡصِمُكُم مِّنَ ٱللَّهِ\nT;0;33:17:0:إِنۡ أَرَادَ بِكُمۡ سُوٓءًا أَوۡ أَرَادَ بِكُمۡ رَحۡمَةࣰۚ وَلَا يَجِدُونَ لَهُم مِّن دُونِ\nT;0;33:17:2:ٱللَّهِ وَلِيࣰّا وَلَا نَصِيرࣰا¦33:18:1:۞ قَدۡ يَعۡلَمُ ٱللَّهُ ٱلۡمُعَوِّقِينَ مِنكُمۡ وَٱلۡقَآئِلِينَ\nT;0;33:18:2:لِإِخۡوَٰنِهِمۡ هَلُمَّ إِلَيۡنَاۖ وَلَا يَأۡتُونَ ٱلۡبَأۡسَ إِلَّا قَلِيلًا¦33:19:1:أَشِحَّةً\nT;0;33:19:0:عَلَيۡكُمۡۖ فَإِذَا جَآءَ ٱلۡخَوۡفُ رَأَيۡتَهُمۡ يَنظُرُونَ إِلَيۡكَ تَدُورُ أَعۡيُنُهُمۡ\nT;0;33:19:0:كَٱلَّذِي يُغۡشَىٰ عَلَيۡهِ مِنَ ٱلۡمَوۡتِۖ فَإِذَا ذَهَبَ ٱلۡخَوۡفُ سَلَقُوكُم\nT;0;33:19:0:بِأَلۡسِنَةٍ حِدَادٍ أَشِحَّةً عَلَى ٱلۡخَيۡرِۚ أُوْلَٰٓئِكَ لَمۡ يُؤۡمِنُواْ فَأَحۡبَطَ\nT;0;33:19:2:ٱللَّهُ أَعۡمَٰلَهُمۡۚ وَكَانَ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرࣰا¦33:20:1:يَحۡسَبُونَ\nT;0;33:20:0:ٱلۡأَحۡزَابَ لَمۡ يَذۡهَبُواْۖ وَإِن يَأۡتِ ٱلۡأَحۡزَابُ يَوَدُّواْ لَوۡ أَنَّهُم\nT;0;33:20:0:بَادُونَ فِي ٱلۡأَعۡرَابِ يَسۡـَٔلُونَ عَنۡ أَنۢبَآئِكُمۡۖ وَلَوۡ كَانُواْ فِيكُم\nT;0;33:20:2:مَّا قَٰتَلُوٓاْ إِلَّا قَلِيلࣰا¦33:21:1:لَّقَدۡ كَانَ لَكُمۡ فِي رَسُولِ ٱللَّهِ أُسۡوَةٌ حَسَنَةࣱ\nT;0;33:21:2:لِّمَن كَانَ يَرۡجُواْ ٱللَّهَ وَٱلۡيَوۡمَ ٱلۡأٓخِرَ وَذَكَرَ ٱللَّهَ كَثِيرࣰا\nT;0;33:22:1:وَلَمَّا رَءَا ٱلۡمُؤۡمِنُونَ ٱلۡأَحۡزَابَ قَالُواْ هَٰذَا مَا وَعَدَنَا ٱللَّهُ وَرَسُولُهُۥ\nT;0;33:22:2:وَصَدَقَ ٱللَّهُ وَرَسُولُهُۥۚ وَمَا زَادَهُمۡ إِلَّآ إِيمَٰنࣰا وَتَسۡلِيمࣰا',
  '21;42;3;\nT;0;33:23:1:مِّنَ ٱلۡمُؤۡمِنِينَ رِجَالࣱ صَدَقُواْ مَا عَٰهَدُواْ ٱللَّهَ عَلَيۡهِۖ فَمِنۡهُم مَّن\nT;0;33:23:2:قَضَىٰ نَحۡبَهُۥ وَمِنۡهُم مَّن يَنتَظِرُۖ وَمَا بَدَّلُواْ تَبۡدِيلࣰا¦33:24:1:لِّيَجۡزِيَ\nT;0;33:24:0:ٱللَّهُ ٱلصَّٰدِقِينَ بِصِدۡقِهِمۡ وَيُعَذِّبَ ٱلۡمُنَٰفِقِينَ إِن شَآءَ أَوۡ\nT;0;33:24:2:يَتُوبَ عَلَيۡهِمۡۚ إِنَّ ٱللَّهَ كَانَ غَفُورࣰا رَّحِيمࣰا¦33:25:1:وَرَدَّ ٱللَّهُ ٱلَّذِينَ\nT;0;33:25:0:كَفَرُواْ بِغَيۡظِهِمۡ لَمۡ يَنَالُواْ خَيۡرࣰاۚ وَكَفَى ٱللَّهُ ٱلۡمُؤۡمِنِينَ\nT;0;33:25:2:ٱلۡقِتَالَۚ وَكَانَ ٱللَّهُ قَوِيًّا عَزِيزࣰا¦33:26:1:وَأَنزَلَ ٱلَّذِينَ ظَٰهَرُوهُم مِّنۡ\nT;0;33:26:0:أَهۡلِ ٱلۡكِتَٰبِ مِن صَيَاصِيهِمۡ وَقَذَفَ فِي قُلُوبِهِمُ ٱلرُّعۡبَ\nT;0;33:26:2:فَرِيقࣰا تَقۡتُلُونَ وَتَأۡسِرُونَ فَرِيقࣰا¦33:27:1:وَأَوۡرَثَكُمۡ أَرۡضَهُمۡ\nT;0;33:27:0:وَدِيَٰرَهُمۡ وَأَمۡوَٰلَهُمۡ وَأَرۡضࣰا لَّمۡ تَطَـُٔوهَاۚ وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ\nT;0;33:27:2:شَيۡءࣲ قَدِيرࣰا¦33:28:1:يَٰٓأَيُّهَا ٱلنَّبِيُّ قُل لِّأَزۡوَٰجِكَ إِن كُنتُنَّ تُرِدۡنَ\nT;0;33:28:0:ٱلۡحَيَوٰةَ ٱلدُّنۡيَا وَزِينَتَهَا فَتَعَالَيۡنَ أُمَتِّعۡكُنَّ وَأُسَرِّحۡكُنَّ\nT;0;33:28:2:سَرَاحࣰا جَمِيلࣰا¦33:29:1:وَإِن كُنتُنَّ تُرِدۡنَ ٱللَّهَ وَرَسُولَهُۥ وَٱلدَّارَ\nT;0;33:29:2:ٱلۡأٓخِرَةَ فَإِنَّ ٱللَّهَ أَعَدَّ لِلۡمُحۡسِنَٰتِ مِنكُنَّ أَجۡرًا عَظِيمࣰا\nT;0;33:30:1:يَٰنِسَآءَ ٱلنَّبِيِّ مَن يَأۡتِ مِنكُنَّ بِفَٰحِشَةࣲ مُّبَيِّنَةࣲ يُضَٰعَفۡ\nT;0;33:30:2:لَهَا ٱلۡعَذَابُ ضِعۡفَيۡنِۚ وَكَانَ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرࣰا',
  '22;43;0;169\nT;0;33:31:1:۞ وَمَن يَقۡنُتۡ مِنكُنَّ لِلَّهِ وَرَسُولِهِۦ وَتَعۡمَلۡ صَٰلِحࣰا نُّؤۡتِهَآ\nT;0;33:31:2:أَجۡرَهَا مَرَّتَيۡنِ وَأَعۡتَدۡنَا لَهَا رِزۡقࣰا كَرِيمࣰا¦33:32:1:يَٰنِسَآءَ ٱلنَّبِيِّ\nT;0;33:32:0:لَسۡتُنَّ كَأَحَدࣲ مِّنَ ٱلنِّسَآءِ إِنِ ٱتَّقَيۡتُنَّۚ فَلَا تَخۡضَعۡنَ بِٱلۡقَوۡلِ\nT;0;33:32:2:فَيَطۡمَعَ ٱلَّذِي فِي قَلۡبِهِۦ مَرَضࣱ وَقُلۡنَ قَوۡلࣰا مَّعۡرُوفࣰا¦33:33:1:وَقَرۡنَ\nT;0;33:33:0:فِي بُيُوتِكُنَّ وَلَا تَبَرَّجۡنَ تَبَرُّجَ ٱلۡجَٰهِلِيَّةِ ٱلۡأُولَىٰۖ وَأَقِمۡنَ\nT;0;33:33:0:ٱلصَّلَوٰةَ وَءَاتِينَ ٱلزَّكَوٰةَ وَأَطِعۡنَ ٱللَّهَ وَرَسُولَهُۥٓۚ إِنَّمَا\nT;0;33:33:0:يُرِيدُ ٱللَّهُ لِيُذۡهِبَ عَنكُمُ ٱلرِّجۡسَ أَهۡلَ ٱلۡبَيۡتِ وَيُطَهِّرَكُمۡ\nT;0;33:33:2:تَطۡهِيرࣰا¦33:34:1:وَٱذۡكُرۡنَ مَا يُتۡلَىٰ فِي بُيُوتِكُنَّ مِنۡ\nT;0;33:34:2:ءَايَٰتِ ٱللَّهِ وَٱلۡحِكۡمَةِۚ إِنَّ ٱللَّهَ كَانَ لَطِيفًا خَبِيرًا\nT;0;33:35:1:إِنَّ ٱلۡمُسۡلِمِينَ وَٱلۡمُسۡلِمَٰتِ وَٱلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِ\nT;0;33:35:0:وَٱلۡقَٰنِتِينَ وَٱلۡقَٰنِتَٰتِ وَٱلصَّٰدِقِينَ وَٱلصَّٰدِقَٰتِ وَٱلصَّٰبِرِينَ\nT;0;33:35:0:وَٱلصَّٰبِرَٰتِ وَٱلۡخَٰشِعِينَ وَٱلۡخَٰشِعَٰتِ وَٱلۡمُتَصَدِّقِينَ\nT;0;33:35:0:وَٱلۡمُتَصَدِّقَٰتِ وَٱلصَّٰٓئِمِينَ وَٱلصَّٰٓئِمَٰتِ وَٱلۡحَٰفِظِينَ\nT;0;33:35:0:فُرُوجَهُمۡ وَٱلۡحَٰفِظَٰتِ وَٱلذَّٰكِرِينَ ٱللَّهَ كَثِيرࣰا\nT;0;33:35:2:وَٱلذَّٰكِرَٰتِ أَعَدَّ ٱللَّهُ لَهُم مَّغۡفِرَةࣰ وَأَجۡرًا عَظِيمࣰا',
  '22;43;0;\nT;0;33:36:1:وَمَا كَانَ لِمُؤۡمِنࣲ وَلَا مُؤۡمِنَةٍ إِذَا قَضَى ٱللَّهُ وَرَسُولُهُۥٓ أَمۡرًا أَن يَكُونَ\nT;0;33:36:0:لَهُمُ ٱلۡخِيَرَةُ مِنۡ أَمۡرِهِمۡۗ وَمَن يَعۡصِ ٱللَّهَ وَرَسُولَهُۥ فَقَدۡ ضَلَّ ضَلَٰلࣰا\nT;0;33:36:2:مُّبِينࣰا¦33:37:1:وَإِذۡ تَقُولُ لِلَّذِيٓ أَنۡعَمَ ٱللَّهُ عَلَيۡهِ وَأَنۡعَمۡتَ عَلَيۡهِ\nT;0;33:37:0:أَمۡسِكۡ عَلَيۡكَ زَوۡجَكَ وَٱتَّقِ ٱللَّهَ وَتُخۡفِي فِي نَفۡسِكَ مَا ٱللَّهُ\nT;0;33:37:0:مُبۡدِيهِ وَتَخۡشَى ٱلنَّاسَ وَٱللَّهُ أَحَقُّ أَن تَخۡشَىٰهُۖ فَلَمَّا قَضَىٰ زَيۡدࣱ\nT;0;33:37:0:مِّنۡهَا وَطَرࣰا زَوَّجۡنَٰكَهَا لِكَيۡ لَا يَكُونَ عَلَى ٱلۡمُؤۡمِنِينَ حَرَجࣱ فِيٓ\nT;0;33:37:2:أَزۡوَٰجِ أَدۡعِيَآئِهِمۡ إِذَا قَضَوۡاْ مِنۡهُنَّ وَطَرࣰاۚ وَكَانَ أَمۡرُ ٱللَّهِ مَفۡعُولࣰا\nT;0;33:38:1:مَّا كَانَ عَلَى ٱلنَّبِيِّ مِنۡ حَرَجࣲ فِيمَا فَرَضَ ٱللَّهُ لَهُۥۖ سُنَّةَ ٱللَّهِ فِي\nT;0;33:38:2:ٱلَّذِينَ خَلَوۡاْ مِن قَبۡلُۚ وَكَانَ أَمۡرُ ٱللَّهِ قَدَرࣰا مَّقۡدُورًا¦33:39:1:ٱلَّذِينَ\nT;0;33:39:0:يُبَلِّغُونَ رِسَٰلَٰتِ ٱللَّهِ وَيَخۡشَوۡنَهُۥ وَلَا يَخۡشَوۡنَ أَحَدًا إِلَّا ٱللَّهَۗ وَكَفَىٰ\nT;0;33:39:2:بِٱللَّهِ حَسِيبࣰا¦33:40:1:مَّا كَانَ مُحَمَّدٌ أَبَآ أَحَدࣲ مِّن رِّجَالِكُمۡ وَلَٰكِن\nT;0;33:40:2:رَّسُولَ ٱللَّهِ وَخَاتَمَ ٱلنَّبِيِّـۧنَۗ وَكَانَ ٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمࣰا\nT;0;33:41:3:يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱذۡكُرُواْ ٱللَّهَ ذِكۡرࣰا كَثِيرࣰا¦33:42:1:وَسَبِّحُوهُ\nT;0;33:42:2:بُكۡرَةࣰ وَأَصِيلًا¦33:43:1:هُوَ ٱلَّذِي يُصَلِّي عَلَيۡكُمۡ وَمَلَٰٓئِكَتُهُۥ\nT;0;33:43:2:لِيُخۡرِجَكُم مِّنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِۚ وَكَانَ بِٱلۡمُؤۡمِنِينَ رَحِيمࣰا',
  '22;43;0;\nT;0;33:44:3:تَحِيَّتُهُمۡ يَوۡمَ يَلۡقَوۡنَهُۥ سَلَٰمࣱۚ وَأَعَدَّ لَهُمۡ أَجۡرࣰا كَرِيمࣰا¦33:45:1:يَٰٓأَيُّهَا\nT;0;33:45:2:ٱلنَّبِيُّ إِنَّآ أَرۡسَلۡنَٰكَ شَٰهِدࣰا وَمُبَشِّرࣰا وَنَذِيرࣰا¦33:46:1:وَدَاعِيًا\nT;0;33:46:2:إِلَى ٱللَّهِ بِإِذۡنِهِۦ وَسِرَاجࣰا مُّنِيرࣰا¦33:47:1:وَبَشِّرِ ٱلۡمُؤۡمِنِينَ بِأَنَّ لَهُم\nT;0;33:47:2:مِّنَ ٱللَّهِ فَضۡلࣰا كَبِيرࣰا¦33:48:1:وَلَا تُطِعِ ٱلۡكَٰفِرِينَ وَٱلۡمُنَٰفِقِينَ\nT;0;33:48:2:وَدَعۡ أَذَىٰهُمۡ وَتَوَكَّلۡ عَلَى ٱللَّهِۚ وَكَفَىٰ بِٱللَّهِ وَكِيلࣰا\nT;0;33:49:1:يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا نَكَحۡتُمُ ٱلۡمُؤۡمِنَٰتِ ثُمَّ طَلَّقۡتُمُوهُنَّ\nT;0;33:49:0:مِن قَبۡلِ أَن تَمَسُّوهُنَّ فَمَا لَكُمۡ عَلَيۡهِنَّ مِنۡ عِدَّةࣲ تَعۡتَدُّونَهَاۖ\nT;0;33:49:2:فَمَتِّعُوهُنَّ وَسَرِّحُوهُنَّ سَرَاحࣰا جَمِيلࣰا¦33:50:1:يَٰٓأَيُّهَا ٱلنَّبِيُّ\nT;0;33:50:0:إِنَّآ أَحۡلَلۡنَا لَكَ أَزۡوَٰجَكَ ٱلَّٰتِيٓ ءَاتَيۡتَ أُجُورَهُنَّ وَمَا مَلَكَتۡ\nT;0;33:50:0:يَمِينُكَ مِمَّآ أَفَآءَ ٱللَّهُ عَلَيۡكَ وَبَنَاتِ عَمِّكَ وَبَنَاتِ عَمَّٰتِكَ\nT;0;33:50:0:وَبَنَاتِ خَالِكَ وَبَنَاتِ خَٰلَٰتِكَ ٱلَّٰتِي هَاجَرۡنَ مَعَكَ وَٱمۡرَأَةࣰ\nT;0;33:50:0:مُّؤۡمِنَةً إِن وَهَبَتۡ نَفۡسَهَا لِلنَّبِيِّ إِنۡ أَرَادَ ٱلنَّبِيُّ أَن يَسۡتَنكِحَهَا\nT;0;33:50:0:خَالِصَةࣰ لَّكَ مِن دُونِ ٱلۡمُؤۡمِنِينَۗ قَدۡ عَلِمۡنَا مَا فَرَضۡنَا\nT;0;33:50:0:عَلَيۡهِمۡ فِيٓ أَزۡوَٰجِهِمۡ وَمَا مَلَكَتۡ أَيۡمَٰنُهُمۡ لِكَيۡلَا\nT;0;33:50:2:يَكُونَ عَلَيۡكَ حَرَجࣱۗ وَكَانَ ٱللَّهُ غَفُورࣰا رَّحِيمࣰا',
  '22;43;1;170\nT;0;33:51:1:۞ تُرۡجِي مَن تَشَآءُ مِنۡهُنَّ وَتُـٔۡوِيٓ إِلَيۡكَ مَن تَشَآءُۖ وَمَنِ ٱبۡتَغَيۡتَ\nT;0;33:51:0:مِمَّنۡ عَزَلۡتَ فَلَا جُنَاحَ عَلَيۡكَۚ ذَٰلِكَ أَدۡنَىٰٓ أَن تَقَرَّ أَعۡيُنُهُنَّ\nT;0;33:51:0:وَلَا يَحۡزَنَّ وَيَرۡضَيۡنَ بِمَآ ءَاتَيۡتَهُنَّ كُلُّهُنَّۚ وَٱللَّهُ يَعۡلَمُ\nT;0;33:51:2:مَا فِي قُلُوبِكُمۡۚ وَكَانَ ٱللَّهُ عَلِيمًا حَلِيمࣰا¦33:52:1:لَّا يَحِلُّ لَكَ\nT;0;33:52:0:ٱلنِّسَآءُ مِنۢ بَعۡدُ وَلَآ أَن تَبَدَّلَ بِهِنَّ مِنۡ أَزۡوَٰجࣲ وَلَوۡ أَعۡجَبَكَ\nT;0;33:52:0:حُسۡنُهُنَّ إِلَّا مَا مَلَكَتۡ يَمِينُكَۗ وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ\nT;0;33:52:2:شَيۡءࣲ رَّقِيبࣰا¦33:53:1:يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَدۡخُلُواْ بُيُوتَ ٱلنَّبِيِّ\nT;0;33:53:0:إِلَّآ أَن يُؤۡذَنَ لَكُمۡ إِلَىٰ طَعَامٍ غَيۡرَ نَٰظِرِينَ إِنَىٰهُ وَلَٰكِنۡ\nT;0;33:53:0:إِذَا دُعِيتُمۡ فَٱدۡخُلُواْ فَإِذَا طَعِمۡتُمۡ فَٱنتَشِرُواْ وَلَا مُسۡتَـٔۡنِسِينَ\nT;0;33:53:0:لِحَدِيثٍۚ إِنَّ ذَٰلِكُمۡ كَانَ يُؤۡذِي ٱلنَّبِيَّ فَيَسۡتَحۡيِۦ مِنكُمۡۖ\nT;0;33:53:0:وَٱللَّهُ لَا يَسۡتَحۡيِۦ مِنَ ٱلۡحَقِّۚ وَإِذَا سَأَلۡتُمُوهُنَّ مَتَٰعࣰا فَسۡـَٔلُوهُنَّ\nT;0;33:53:0:مِن وَرَآءِ حِجَابࣲۚ ذَٰلِكُمۡ أَطۡهَرُ لِقُلُوبِكُمۡ وَقُلُوبِهِنَّۚ\nT;0;33:53:0:وَمَا كَانَ لَكُمۡ أَن تُؤۡذُواْ رَسُولَ ٱللَّهِ وَلَآ أَن تَنكِحُوٓاْ أَزۡوَٰجَهُۥ\nT;0;33:53:2:مِنۢ بَعۡدِهِۦٓ أَبَدًاۚ إِنَّ ذَٰلِكُمۡ كَانَ عِندَ ٱللَّهِ عَظِيمًا\nT;0;33:54:3:إِن تُبۡدُواْ شَيۡـًٔا أَوۡ تُخۡفُوهُ فَإِنَّ ٱللَّهَ كَانَ بِكُلِّ شَيۡءٍ عَلِيمࣰا',
  '22;43;1;171\nT;0;33:55:1:لَّا جُنَاحَ عَلَيۡهِنَّ فِيٓ ءَابَآئِهِنَّ وَلَآ أَبۡنَآئِهِنَّ وَلَآ إِخۡوَٰنِهِنَّ وَلَآ\nT;0;33:55:0:أَبۡنَآءِ إِخۡوَٰنِهِنَّ وَلَآ أَبۡنَآءِ أَخَوَٰتِهِنَّ وَلَا نِسَآئِهِنَّ وَلَا مَا مَلَكَتۡ\nT;0;33:55:2:أَيۡمَٰنُهُنَّۗ وَٱتَّقِينَ ٱللَّهَۚ إِنَّ ٱللَّهَ كَانَ عَلَىٰ كُلِّ شَيۡءࣲ شَهِيدًا\nT;0;33:56:1:إِنَّ ٱللَّهَ وَمَلَٰٓئِكَتَهُۥ يُصَلُّونَ عَلَى ٱلنَّبِيِّۚ يَٰٓأَيُّهَا ٱلَّذِينَ\nT;0;33:56:2:ءَامَنُواْ صَلُّواْ عَلَيۡهِ وَسَلِّمُواْ تَسۡلِيمًا¦33:57:1:إِنَّ ٱلَّذِينَ يُؤۡذُونَ\nT;0;33:57:0:ٱللَّهَ وَرَسُولَهُۥ لَعَنَهُمُ ٱللَّهُ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِ وَأَعَدَّ لَهُمۡ عَذَابࣰا\nT;0;33:57:2:مُّهِينࣰا¦33:58:1:وَٱلَّذِينَ يُؤۡذُونَ ٱلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِ بِغَيۡرِ\nT;0;33:58:2:مَا ٱكۡتَسَبُواْ فَقَدِ ٱحۡتَمَلُواْ بُهۡتَٰنࣰا وَإِثۡمࣰا مُّبِينࣰا\nT;0;33:59:1:يَٰٓأَيُّهَا ٱلنَّبِيُّ قُل لِّأَزۡوَٰجِكَ وَبَنَاتِكَ وَنِسَآءِ ٱلۡمُؤۡمِنِينَ\nT;0;33:59:0:يُدۡنِينَ عَلَيۡهِنَّ مِن جَلَٰبِيبِهِنَّۚ ذَٰلِكَ أَدۡنَىٰٓ أَن يُعۡرَفۡنَ فَلَا\nT;0;33:59:2:يُؤۡذَيۡنَۗ وَكَانَ ٱللَّهُ غَفُورࣰا رَّحِيمࣰا¦33:60:1:۞ لَّئِن لَّمۡ يَنتَهِ ٱلۡمُنَٰفِقُونَ\nT;0;33:60:0:وَٱلَّذِينَ فِي قُلُوبِهِم مَّرَضࣱ وَٱلۡمُرۡجِفُونَ فِي ٱلۡمَدِينَةِ\nT;0;33:60:2:لَنُغۡرِيَنَّكَ بِهِمۡ ثُمَّ لَا يُجَاوِرُونَكَ فِيهَآ إِلَّا قَلِيلࣰا¦33:61:1:مَّلۡعُونِينَۖ\nT;0;33:61:2:أَيۡنَمَا ثُقِفُوٓاْ أُخِذُواْ وَقُتِّلُواْ تَقۡتِيلࣰا¦33:62:1:سُنَّةَ ٱللَّهِ فِي\nT;0;33:62:2:ٱلَّذِينَ خَلَوۡاْ مِن قَبۡلُۖ وَلَن تَجِدَ لِسُنَّةِ ٱللَّهِ تَبۡدِيلࣰا',
  '22;43;2;\nT;0;33:63:1:يَسۡـَٔلُكَ ٱلنَّاسُ عَنِ ٱلسَّاعَةِۖ قُلۡ إِنَّمَا عِلۡمُهَا عِندَ ٱللَّهِۚ وَمَا يُدۡرِيكَ\nT;0;33:63:2:لَعَلَّ ٱلسَّاعَةَ تَكُونُ قَرِيبًا¦33:64:1:إِنَّ ٱللَّهَ لَعَنَ ٱلۡكَٰفِرِينَ وَأَعَدَّ\nT;0;33:64:2:لَهُمۡ سَعِيرًا¦33:65:3:خَٰلِدِينَ فِيهَآ أَبَدࣰاۖ لَّا يَجِدُونَ وَلِيࣰّا وَلَا نَصِيرࣰا\nT;0;33:66:1:يَوۡمَ تُقَلَّبُ وُجُوهُهُمۡ فِي ٱلنَّارِ يَقُولُونَ يَٰلَيۡتَنَآ أَطَعۡنَا ٱللَّهَ\nT;0;33:66:2:وَأَطَعۡنَا ٱلرَّسُولَا۠¦33:67:1:وَقَالُواْ رَبَّنَآ إِنَّآ أَطَعۡنَا سَادَتَنَا وَكُبَرَآءَنَا\nT;0;33:67:2:فَأَضَلُّونَا ٱلسَّبِيلَا۠¦33:68:1:رَبَّنَآ ءَاتِهِمۡ ضِعۡفَيۡنِ مِنَ ٱلۡعَذَابِ\nT;0;33:68:2:وَٱلۡعَنۡهُمۡ لَعۡنࣰا كَبِيرࣰا¦33:69:1:يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَكُونُواْ كَٱلَّذِينَ\nT;0;33:69:2:ءَاذَوۡاْ مُوسَىٰ فَبَرَّأَهُ ٱللَّهُ مِمَّا قَالُواْۚ وَكَانَ عِندَ ٱللَّهِ وَجِيهࣰا\nT;0;33:70:3:يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ وَقُولُواْ قَوۡلࣰا سَدِيدࣰا¦33:71:1:يُصۡلِحۡ\nT;0;33:71:0:لَكُمۡ أَعۡمَٰلَكُمۡ وَيَغۡفِرۡ لَكُمۡ ذُنُوبَكُمۡۗ وَمَن يُطِعِ ٱللَّهَ وَرَسُولَهُۥ\nT;0;33:71:2:فَقَدۡ فَازَ فَوۡزًا عَظِيمًا¦33:72:1:إِنَّا عَرَضۡنَا ٱلۡأَمَانَةَ عَلَى ٱلسَّمَٰوَٰتِ\nT;0;33:72:0:وَٱلۡأَرۡضِ وَٱلۡجِبَالِ فَأَبَيۡنَ أَن يَحۡمِلۡنَهَا وَأَشۡفَقۡنَ مِنۡهَا وَحَمَلَهَا\nT;0;33:72:2:ٱلۡإِنسَٰنُۖ إِنَّهُۥ كَانَ ظَلُومࣰا جَهُولࣰا¦33:73:1:لِّيُعَذِّبَ ٱللَّهُ ٱلۡمُنَٰفِقِينَ\nT;0;33:73:0:وَٱلۡمُنَٰفِقَٰتِ وَٱلۡمُشۡرِكِينَ وَٱلۡمُشۡرِكَٰتِ وَيَتُوبَ ٱللَّهُ\nT;2;33:73:2:عَلَى ٱلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِۗ وَكَانَ ٱللَّهُ غَفُورࣰا رَّحِيمَۢا',
  '22;43;2;\nH;34\nB;34\nT;0;34:1:1:ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِي لَهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِ وَلَهُ ٱلۡحَمۡدُ\nT;0;34:1:2:فِي ٱلۡأٓخِرَةِۚ وَهُوَ ٱلۡحَكِيمُ ٱلۡخَبِيرُ¦34:2:1:يَعۡلَمُ مَا يَلِجُ فِي ٱلۡأَرۡضِ وَمَا\nT;0;34:2:0:يَخۡرُجُ مِنۡهَا وَمَا يَنزِلُ مِنَ ٱلسَّمَآءِ وَمَا يَعۡرُجُ فِيهَاۚ وَهُوَ\nT;0;34:2:2:ٱلرَّحِيمُ ٱلۡغَفُورُ¦34:3:1:وَقَالَ ٱلَّذِينَ كَفَرُواْ لَا تَأۡتِينَا ٱلسَّاعَةُۖ\nT;0;34:3:0:قُلۡ بَلَىٰ وَرَبِّي لَتَأۡتِيَنَّكُمۡ عَٰلِمِ ٱلۡغَيۡبِۖ لَا يَعۡزُبُ عَنۡهُ مِثۡقَالُ\nT;0;34:3:0:ذَرَّةࣲ فِي ٱلسَّمَٰوَٰتِ وَلَا فِي ٱلۡأَرۡضِ وَلَآ أَصۡغَرُ مِن ذَٰلِكَ\nT;0;34:3:2:وَلَآ أَكۡبَرُ إِلَّا فِي كِتَٰبࣲ مُّبِينࣲ¦34:4:1:لِّيَجۡزِيَ ٱلَّذِينَ\nT;0;34:4:0:ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِۚ أُوْلَٰٓئِكَ لَهُم مَّغۡفِرَةࣱ وَرِزۡقࣱ\nT;0;34:4:2:كَرِيمࣱ¦34:5:1:وَٱلَّذِينَ سَعَوۡ فِيٓ ءَايَٰتِنَا مُعَٰجِزِينَ أُوْلَٰٓئِكَ\nT;0;34:5:2:لَهُمۡ عَذَابࣱ مِّن رِّجۡزٍ أَلِيمࣱ¦34:6:1:وَيَرَى ٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ\nT;0;34:6:0:ٱلَّذِيٓ أُنزِلَ إِلَيۡكَ مِن رَّبِّكَ هُوَ ٱلۡحَقَّ وَيَهۡدِيٓ إِلَىٰ صِرَٰطِ\nT;0;34:6:2:ٱلۡعَزِيزِ ٱلۡحَمِيدِ¦34:7:1:وَقَالَ ٱلَّذِينَ كَفَرُواْ هَلۡ نَدُلُّكُمۡ عَلَىٰ رَجُلࣲ\nT;0;34:7:2:يُنَبِّئُكُمۡ إِذَا مُزِّقۡتُمۡ كُلَّ مُمَزَّقٍ إِنَّكُمۡ لَفِي خَلۡقࣲ جَدِيدٍ',
  '22;43;2;172\nT;0;34:8:1:أَفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَم بِهِۦ جِنَّةُۢۗ بَلِ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ\nT;0;34:8:2:فِي ٱلۡعَذَابِ وَٱلضَّلَٰلِ ٱلۡبَعِيدِ¦34:9:1:أَفَلَمۡ يَرَوۡاْ إِلَىٰ مَا بَيۡنَ أَيۡدِيهِمۡ\nT;0;34:9:0:وَمَا خَلۡفَهُم مِّنَ ٱلسَّمَآءِ وَٱلۡأَرۡضِۚ إِن نَّشَأۡ نَخۡسِفۡ بِهِمُ ٱلۡأَرۡضَ\nT;0;34:9:0:أَوۡ نُسۡقِطۡ عَلَيۡهِمۡ كِسَفࣰا مِّنَ ٱلسَّمَآءِۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةࣰ\nT;0;34:9:2:لِّكُلِّ عَبۡدࣲ مُّنِيبࣲ¦34:10:1:۞ وَلَقَدۡ ءَاتَيۡنَا دَاوُۥدَ مِنَّا فَضۡلࣰاۖ\nT;0;34:10:2:يَٰجِبَالُ أَوِّبِي مَعَهُۥ وَٱلطَّيۡرَۖ وَأَلَنَّا لَهُ ٱلۡحَدِيدَ¦34:11:1:أَنِ ٱعۡمَلۡ\nT;0;34:11:0:سَٰبِغَٰتࣲ وَقَدِّرۡ فِي ٱلسَّرۡدِۖ وَٱعۡمَلُواْ صَٰلِحًاۖ إِنِّي بِمَا تَعۡمَلُونَ\nT;0;34:11:2:بَصِيرࣱ¦34:12:1:وَلِسُلَيۡمَٰنَ ٱلرِّيحَ غُدُوُّهَا شَهۡرࣱ وَرَوَاحُهَا شَهۡرࣱۖ\nT;0;34:12:0:وَأَسَلۡنَا لَهُۥ عَيۡنَ ٱلۡقِطۡرِۖ وَمِنَ ٱلۡجِنِّ مَن يَعۡمَلُ بَيۡنَ يَدَيۡهِ بِإِذۡنِ\nT;0;34:12:2:رَبِّهِۦۖ وَمَن يَزِغۡ مِنۡهُمۡ عَنۡ أَمۡرِنَا نُذِقۡهُ مِنۡ عَذَابِ ٱلسَّعِيرِ\nT;0;34:13:1:يَعۡمَلُونَ لَهُۥ مَا يَشَآءُ مِن مَّحَٰرِيبَ وَتَمَٰثِيلَ وَجِفَانࣲ كَٱلۡجَوَابِ\nT;0;34:13:0:وَقُدُورࣲ رَّاسِيَٰتٍۚ ٱعۡمَلُوٓاْ ءَالَ دَاوُۥدَ شُكۡرࣰاۚ وَقَلِيلࣱ مِّنۡ عِبَادِيَ\nT;0;34:13:2:ٱلشَّكُورُ¦34:14:1:فَلَمَّا قَضَيۡنَا عَلَيۡهِ ٱلۡمَوۡتَ مَا دَلَّهُمۡ عَلَىٰ مَوۡتِهِۦٓ\nT;0;34:14:0:إِلَّا دَآبَّةُ ٱلۡأَرۡضِ تَأۡكُلُ مِنسَأَتَهُۥۖ فَلَمَّا خَرَّ تَبَيَّنَتِ ٱلۡجِنُّ\nT;0;34:14:2:أَن لَّوۡ كَانُواْ يَعۡلَمُونَ ٱلۡغَيۡبَ مَا لَبِثُواْ فِي ٱلۡعَذَابِ ٱلۡمُهِينِ',
  '22;43;3;\nT;0;34:15:1:لَقَدۡ كَانَ لِسَبَإࣲ فِي مَسۡكَنِهِمۡ ءَايَةࣱۖ جَنَّتَانِ عَن يَمِينࣲ وَشِمَالࣲۖ\nT;0;34:15:2:كُلُواْ مِن رِّزۡقِ رَبِّكُمۡ وَٱشۡكُرُواْ لَهُۥۚ بَلۡدَةࣱ طَيِّبَةࣱ وَرَبٌّ غَفُورࣱ\nT;0;34:16:1:فَأَعۡرَضُواْ فَأَرۡسَلۡنَا عَلَيۡهِمۡ سَيۡلَ ٱلۡعَرِمِ وَبَدَّلۡنَٰهُم بِجَنَّتَيۡهِمۡ\nT;0;34:16:2:جَنَّتَيۡنِ ذَوَاتَيۡ أُكُلٍ خَمۡطࣲ وَأَثۡلࣲ وَشَيۡءࣲ مِّن سِدۡرࣲ قَلِيلࣲ\nT;0;34:17:3:ذَٰلِكَ جَزَيۡنَٰهُم بِمَا كَفَرُواْۖ وَهَلۡ نُجَٰزِيٓ إِلَّا ٱلۡكَفُورَ\nT;0;34:18:1:وَجَعَلۡنَا بَيۡنَهُمۡ وَبَيۡنَ ٱلۡقُرَى ٱلَّتِي بَٰرَكۡنَا فِيهَا قُرࣰى ظَٰهِرَةࣰ\nT;0;34:18:2:وَقَدَّرۡنَا فِيهَا ٱلسَّيۡرَۖ سِيرُواْ فِيهَا لَيَالِيَ وَأَيَّامًا ءَامِنِينَ\nT;0;34:19:1:فَقَالُواْ رَبَّنَا بَٰعِدۡ بَيۡنَ أَسۡفَارِنَا وَظَلَمُوٓاْ أَنفُسَهُمۡ فَجَعَلۡنَٰهُمۡ\nT;0;34:19:0:أَحَادِيثَ وَمَزَّقۡنَٰهُمۡ كُلَّ مُمَزَّقٍۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتࣲ لِّكُلِّ صَبَّارࣲ\nT;0;34:19:2:شَكُورࣲ¦34:20:1:وَلَقَدۡ صَدَّقَ عَلَيۡهِمۡ إِبۡلِيسُ ظَنَّهُۥ فَٱتَّبَعُوهُ إِلَّا\nT;0;34:20:2:فَرِيقࣰا مِّنَ ٱلۡمُؤۡمِنِينَ¦34:21:1:وَمَا كَانَ لَهُۥ عَلَيۡهِم مِّن سُلۡطَٰنٍ\nT;0;34:21:0:إِلَّا لِنَعۡلَمَ مَن يُؤۡمِنُ بِٱلۡأٓخِرَةِ مِمَّنۡ هُوَ مِنۡهَا فِي شَكࣲّۗ\nT;0;34:21:2:وَرَبُّكَ عَلَىٰ كُلِّ شَيۡءٍ حَفِيظࣱ¦34:22:1:قُلِ ٱدۡعُواْ ٱلَّذِينَ زَعَمۡتُم مِّن\nT;0;34:22:0:دُونِ ٱللَّهِ لَا يَمۡلِكُونَ مِثۡقَالَ ذَرَّةࣲ فِي ٱلسَّمَٰوَٰتِ وَلَا فِي\nT;0;34:22:2:ٱلۡأَرۡضِ وَمَا لَهُمۡ فِيهِمَا مِن شِرۡكࣲ وَمَا لَهُۥ مِنۡهُم مِّن ظَهِيرࣲ',
  '22;43;3;173\nT;0;34:23:1:وَلَا تَنفَعُ ٱلشَّفَٰعَةُ عِندَهُۥٓ إِلَّا لِمَنۡ أَذِنَ لَهُۥۚ حَتَّىٰٓ إِذَا فُزِّعَ عَن\nT;0;34:23:2:قُلُوبِهِمۡ قَالُواْ مَاذَا قَالَ رَبُّكُمۡۖ قَالُواْ ٱلۡحَقَّۖ وَهُوَ ٱلۡعَلِيُّ ٱلۡكَبِيرُ\nT;0;34:24:1:۞ قُلۡ مَن يَرۡزُقُكُم مِّنَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ قُلِ ٱللَّهُۖ\nT;0;34:24:2:وَإِنَّآ أَوۡ إِيَّاكُمۡ لَعَلَىٰ هُدًى أَوۡ فِي ضَلَٰلࣲ مُّبِينࣲ¦34:25:1:قُل\nT;0;34:25:2:لَّا تُسۡـَٔلُونَ عَمَّآ أَجۡرَمۡنَا وَلَا نُسۡـَٔلُ عَمَّا تَعۡمَلُونَ¦34:26:1:قُلۡ\nT;0;34:26:2:يَجۡمَعُ بَيۡنَنَا رَبُّنَا ثُمَّ يَفۡتَحُ بَيۡنَنَا بِٱلۡحَقِّ وَهُوَ ٱلۡفَتَّاحُ ٱلۡعَلِيمُ\nT;0;34:27:1:قُلۡ أَرُونِيَ ٱلَّذِينَ أَلۡحَقۡتُم بِهِۦ شُرَكَآءَۖ كَلَّاۚ بَلۡ هُوَ ٱللَّهُ\nT;0;34:27:2:ٱلۡعَزِيزُ ٱلۡحَكِيمُ¦34:28:1:وَمَآ أَرۡسَلۡنَٰكَ إِلَّا كَآفَّةࣰ لِّلنَّاسِ\nT;0;34:28:2:بَشِيرࣰا وَنَذِيرࣰا وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَعۡلَمُونَ\nT;0;34:29:3:وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلۡوَعۡدُ إِن كُنتُمۡ صَٰدِقِينَ\nT;0;34:30:3:قُل لَّكُم مِّيعَادُ يَوۡمࣲ لَّا تَسۡتَـٔۡخِرُونَ عَنۡهُ سَاعَةࣰ وَلَا تَسۡتَقۡدِمُونَ\nT;0;34:31:1:وَقَالَ ٱلَّذِينَ كَفَرُواْ لَن نُّؤۡمِنَ بِهَٰذَا ٱلۡقُرۡءَانِ وَلَا\nT;0;34:31:0:بِٱلَّذِي بَيۡنَ يَدَيۡهِۗ وَلَوۡ تَرَىٰٓ إِذِ ٱلظَّٰلِمُونَ مَوۡقُوفُونَ عِندَ\nT;0;34:31:0:رَبِّهِمۡ يَرۡجِعُ بَعۡضُهُمۡ إِلَىٰ بَعۡضٍ ٱلۡقَوۡلَ يَقُولُ ٱلَّذِينَ\nT;0;34:31:2:ٱسۡتُضۡعِفُواْ لِلَّذِينَ ٱسۡتَكۡبَرُواْ لَوۡلَآ أَنتُمۡ لَكُنَّا مُؤۡمِنِينَ',
  '22;44;0;\nT;0;34:32:1:قَالَ ٱلَّذِينَ ٱسۡتَكۡبَرُواْ لِلَّذِينَ ٱسۡتُضۡعِفُوٓاْ أَنَحۡنُ صَدَدۡنَٰكُمۡ\nT;0;34:32:2:عَنِ ٱلۡهُدَىٰ بَعۡدَ إِذۡ جَآءَكُمۖ بَلۡ كُنتُم مُّجۡرِمِينَ¦34:33:1:وَقَالَ ٱلَّذِينَ\nT;0;34:33:0:ٱسۡتُضۡعِفُواْ لِلَّذِينَ ٱسۡتَكۡبَرُواْ بَلۡ مَكۡرُ ٱلَّيۡلِ وَٱلنَّهَارِ إِذۡ\nT;0;34:33:0:تَأۡمُرُونَنَآ أَن نَّكۡفُرَ بِٱللَّهِ وَنَجۡعَلَ لَهُۥٓ أَندَادࣰاۚ وَأَسَرُّواْ ٱلنَّدَامَةَ\nT;0;34:33:0:لَمَّا رَأَوُاْ ٱلۡعَذَابَۚ وَجَعَلۡنَا ٱلۡأَغۡلَٰلَ فِيٓ أَعۡنَاقِ ٱلَّذِينَ كَفَرُواْۖ\nT;0;34:33:2:هَلۡ يُجۡزَوۡنَ إِلَّا مَا كَانُواْ يَعۡمَلُونَ¦34:34:1:وَمَآ أَرۡسَلۡنَا فِي قَرۡيَةࣲ\nT;0;34:34:2:مِّن نَّذِيرٍ إِلَّا قَالَ مُتۡرَفُوهَآ إِنَّا بِمَآ أُرۡسِلۡتُم بِهِۦ كَٰفِرُونَ\nT;0;34:35:3:وَقَالُواْ نَحۡنُ أَكۡثَرُ أَمۡوَٰلࣰا وَأَوۡلَٰدࣰا وَمَا نَحۡنُ بِمُعَذَّبِينَ\nT;0;34:36:1:قُلۡ إِنَّ رَبِّي يَبۡسُطُ ٱلرِّزۡقَ لِمَن يَشَآءُ وَيَقۡدِرُ وَلَٰكِنَّ أَكۡثَرَ\nT;0;34:36:2:ٱلنَّاسِ لَا يَعۡلَمُونَ¦34:37:1:وَمَآ أَمۡوَٰلُكُمۡ وَلَآ أَوۡلَٰدُكُم بِٱلَّتِي تُقَرِّبُكُمۡ\nT;0;34:37:0:عِندَنَا زُلۡفَىٰٓ إِلَّا مَنۡ ءَامَنَ وَعَمِلَ صَٰلِحࣰا فَأُوْلَٰٓئِكَ لَهُمۡ جَزَآءُ\nT;0;34:37:2:ٱلضِّعۡفِ بِمَا عَمِلُواْ وَهُمۡ فِي ٱلۡغُرُفَٰتِ ءَامِنُونَ¦34:38:1:وَٱلَّذِينَ\nT;0;34:38:2:يَسۡعَوۡنَ فِيٓ ءَايَٰتِنَا مُعَٰجِزِينَ أُوْلَٰٓئِكَ فِي ٱلۡعَذَابِ مُحۡضَرُونَ\nT;0;34:39:1:قُلۡ إِنَّ رَبِّي يَبۡسُطُ ٱلرِّزۡقَ لِمَن يَشَآءُ مِنۡ عِبَادِهِۦ وَيَقۡدِرُ لَهُۥۚ\nT;0;34:39:2:وَمَآ أَنفَقۡتُم مِّن شَيۡءࣲ فَهُوَ يُخۡلِفُهُۥۖ وَهُوَ خَيۡرُ ٱلرَّٰزِقِينَ',
  '22;44;0;174\nT;0;34:40:1:وَيَوۡمَ يَحۡشُرُهُمۡ جَمِيعࣰا ثُمَّ يَقُولُ لِلۡمَلَٰٓئِكَةِ أَهَٰٓؤُلَآءِ إِيَّاكُمۡ كَانُواْ\nT;0;34:40:2:يَعۡبُدُونَ¦34:41:1:قَالُواْ سُبۡحَٰنَكَ أَنتَ وَلِيُّنَا مِن دُونِهِمۖ بَلۡ كَانُواْ\nT;0;34:41:2:يَعۡبُدُونَ ٱلۡجِنَّۖ أَكۡثَرُهُم بِهِم مُّؤۡمِنُونَ¦34:42:1:فَٱلۡيَوۡمَ لَا يَمۡلِكُ\nT;0;34:42:0:بَعۡضُكُمۡ لِبَعۡضࣲ نَّفۡعࣰا وَلَا ضَرࣰّا وَنَقُولُ لِلَّذِينَ ظَلَمُواْ ذُوقُواْ عَذَابَ\nT;0;34:42:2:ٱلنَّارِ ٱلَّتِي كُنتُم بِهَا تُكَذِّبُونَ¦34:43:1:وَإِذَا تُتۡلَىٰ عَلَيۡهِمۡ ءَايَٰتُنَا بَيِّنَٰتࣲ\nT;0;34:43:0:قَالُواْ مَا هَٰذَآ إِلَّا رَجُلࣱ يُرِيدُ أَن يَصُدَّكُمۡ عَمَّا كَانَ يَعۡبُدُ ءَابَآؤُكُمۡ\nT;0;34:43:0:وَقَالُواْ مَا هَٰذَآ إِلَّآ إِفۡكࣱ مُّفۡتَرࣰىۚ وَقَالَ ٱلَّذِينَ كَفَرُواْ لِلۡحَقِّ لَمَّا\nT;0;34:43:2:جَآءَهُمۡ إِنۡ هَٰذَآ إِلَّا سِحۡرࣱ مُّبِينࣱ¦34:44:1:وَمَآ ءَاتَيۡنَٰهُم مِّن كُتُبࣲ\nT;0;34:44:2:يَدۡرُسُونَهَاۖ وَمَآ أَرۡسَلۡنَآ إِلَيۡهِمۡ قَبۡلَكَ مِن نَّذِيرࣲ¦34:45:1:وَكَذَّبَ\nT;0;34:45:0:ٱلَّذِينَ مِن قَبۡلِهِمۡ وَمَا بَلَغُواْ مِعۡشَارَ مَآ ءَاتَيۡنَٰهُمۡ فَكَذَّبُواْ\nT;0;34:45:2:رُسُلِيۖ فَكَيۡفَ كَانَ نَكِيرِ¦34:46:1:۞ قُلۡ إِنَّمَآ أَعِظُكُم بِوَٰحِدَةٍۖ أَن\nT;0;34:46:0:تَقُومُواْ لِلَّهِ مَثۡنَىٰ وَفُرَٰدَىٰ ثُمَّ تَتَفَكَّرُواْۚ مَا بِصَاحِبِكُم مِّن\nT;0;34:46:2:جِنَّةٍۚ إِنۡ هُوَ إِلَّا نَذِيرࣱ لَّكُم بَيۡنَ يَدَيۡ عَذَابࣲ شَدِيدࣲ¦34:47:1:قُلۡ\nT;0;34:47:0:مَا سَأَلۡتُكُم مِّنۡ أَجۡرࣲ فَهُوَ لَكُمۡۖ إِنۡ أَجۡرِيَ إِلَّا عَلَى ٱللَّهِۖ وَهُوَ عَلَىٰ\nT;0;34:47:2:كُلِّ شَيۡءࣲ شَهِيدࣱ¦34:48:3:قُلۡ إِنَّ رَبِّي يَقۡذِفُ بِٱلۡحَقِّ عَلَّٰمُ ٱلۡغُيُوبِ',
  '22;44;1;\nT;0;34:49:3:قُلۡ جَآءَ ٱلۡحَقُّ وَمَا يُبۡدِئُ ٱلۡبَٰطِلُ وَمَا يُعِيدُ¦34:50:1:قُلۡ إِن ضَلَلۡتُ\nT;0;34:50:0:فَإِنَّمَآ أَضِلُّ عَلَىٰ نَفۡسِيۖ وَإِنِ ٱهۡتَدَيۡتُ فَبِمَا يُوحِيٓ إِلَيَّ رَبِّيٓۚ إِنَّهُۥ\nT;0;34:50:2:سَمِيعࣱ قَرِيبࣱ¦34:51:1:وَلَوۡ تَرَىٰٓ إِذۡ فَزِعُواْ فَلَا فَوۡتَ وَأُخِذُواْ مِن\nT;0;34:51:2:مَّكَانࣲ قَرِيبࣲ¦34:52:1:وَقَالُوٓاْ ءَامَنَّا بِهِۦ وَأَنَّىٰ لَهُمُ ٱلتَّنَاوُشُ مِن\nT;0;34:52:2:مَّكَانِۭ بَعِيدࣲ¦34:53:1:وَقَدۡ كَفَرُواْ بِهِۦ مِن قَبۡلُۖ وَيَقۡذِفُونَ\nT;0;34:53:2:بِٱلۡغَيۡبِ مِن مَّكَانِۭ بَعِيدࣲ¦34:54:1:وَحِيلَ بَيۡنَهُمۡ وَبَيۡنَ مَا يَشۡتَهُونَ\nT;2;34:54:2:كَمَا فُعِلَ بِأَشۡيَاعِهِم مِّن قَبۡلُۚ إِنَّهُمۡ كَانُواْ فِي شَكࣲّ مُّرِيبِۭ\nH;35\nB;35\nT;0;35:1:1:ٱلۡحَمۡدُ لِلَّهِ فَاطِرِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ جَاعِلِ ٱلۡمَلَٰٓئِكَةِ رُسُلًا أُوْلِيٓ\nT;0;35:1:0:أَجۡنِحَةࣲ مَّثۡنَىٰ وَثُلَٰثَ وَرُبَٰعَۚ يَزِيدُ فِي ٱلۡخَلۡقِ مَا يَشَآءُۚ إِنَّ ٱللَّهَ عَلَىٰ\nT;0;35:1:2:كُلِّ شَيۡءࣲ قَدِيرࣱ¦35:2:1:مَّا يَفۡتَحِ ٱللَّهُ لِلنَّاسِ مِن رَّحۡمَةࣲ فَلَا مُمۡسِكَ لَهَاۖ\nT;0;35:2:2:وَمَا يُمۡسِكۡ فَلَا مُرۡسِلَ لَهُۥ مِنۢ بَعۡدِهِۦۚ وَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ\nT;0;35:3:1:يَٰٓأَيُّهَا ٱلنَّاسُ ٱذۡكُرُواْ نِعۡمَتَ ٱللَّهِ عَلَيۡكُمۡۚ هَلۡ مِنۡ خَٰلِقٍ غَيۡرُ ٱللَّهِ\nT;0;35:3:2:يَرۡزُقُكُم مِّنَ ٱلسَّمَآءِ وَٱلۡأَرۡضِۚ لَآ إِلَٰهَ إِلَّا هُوَۖ فَأَنَّىٰ تُؤۡفَكُونَ',
  '22;44;1;\nT;0;35:4:1:وَإِن يُكَذِّبُوكَ فَقَدۡ كُذِّبَتۡ رُسُلࣱ مِّن قَبۡلِكَۚ وَإِلَى ٱللَّهِ تُرۡجَعُ\nT;0;35:4:2:ٱلۡأُمُورُ¦35:5:1:يَٰٓأَيُّهَا ٱلنَّاسُ إِنَّ وَعۡدَ ٱللَّهِ حَقࣱّۖ فَلَا تَغُرَّنَّكُمُ ٱلۡحَيَوٰةُ\nT;0;35:5:2:ٱلدُّنۡيَا وَلَا يَغُرَّنَّكُم بِٱللَّهِ ٱلۡغَرُورُ¦35:6:1:إِنَّ ٱلشَّيۡطَٰنَ لَكُمۡ عَدُوࣱّ فَٱتَّخِذُوهُ\nT;0;35:6:2:عَدُوًّاۚ إِنَّمَا يَدۡعُواْ حِزۡبَهُۥ لِيَكُونُواْ مِنۡ أَصۡحَٰبِ ٱلسَّعِيرِ¦35:7:1:ٱلَّذِينَ\nT;0;35:7:0:كَفَرُواْ لَهُمۡ عَذَابࣱ شَدِيدࣱۖ وَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ لَهُم\nT;0;35:7:2:مَّغۡفِرَةࣱ وَأَجۡرࣱ كَبِيرٌ¦35:8:1:أَفَمَن زُيِّنَ لَهُۥ سُوٓءُ عَمَلِهِۦ فَرَءَاهُ حَسَنࣰاۖ فَإِنَّ\nT;0;35:8:0:ٱللَّهَ يُضِلُّ مَن يَشَآءُ وَيَهۡدِي مَن يَشَآءُۖ فَلَا تَذۡهَبۡ نَفۡسُكَ عَلَيۡهِمۡ\nT;0;35:8:2:حَسَرَٰتٍۚ إِنَّ ٱللَّهَ عَلِيمُۢ بِمَا يَصۡنَعُونَ¦35:9:1:وَٱللَّهُ ٱلَّذِيٓ أَرۡسَلَ\nT;0;35:9:0:ٱلرِّيَٰحَ فَتُثِيرُ سَحَابࣰا فَسُقۡنَٰهُ إِلَىٰ بَلَدࣲ مَّيِّتࣲ فَأَحۡيَيۡنَا بِهِ ٱلۡأَرۡضَ\nT;0;35:9:2:بَعۡدَ مَوۡتِهَاۚ كَذَٰلِكَ ٱلنُّشُورُ¦35:10:1:مَن كَانَ يُرِيدُ ٱلۡعِزَّةَ فَلِلَّهِ ٱلۡعِزَّةُ جَمِيعًاۚ\nT;0;35:10:0:إِلَيۡهِ يَصۡعَدُ ٱلۡكَلِمُ ٱلطَّيِّبُ وَٱلۡعَمَلُ ٱلصَّٰلِحُ يَرۡفَعُهُۥۚ وَٱلَّذِينَ\nT;0;35:10:2:يَمۡكُرُونَ ٱلسَّيِّـَٔاتِ لَهُمۡ عَذَابࣱ شَدِيدࣱۖ وَمَكۡرُ أُوْلَٰٓئِكَ هُوَ يَبُورُ\nT;0;35:11:1:وَٱللَّهُ خَلَقَكُم مِّن تُرَابࣲ ثُمَّ مِن نُّطۡفَةࣲ ثُمَّ جَعَلَكُمۡ أَزۡوَٰجࣰاۚ\nT;0;35:11:0:وَمَا تَحۡمِلُ مِنۡ أُنثَىٰ وَلَا تَضَعُ إِلَّا بِعِلۡمِهِۦۚ وَمَا يُعَمَّرُ مِن مُّعَمَّرࣲ\nT;0;35:11:2:وَلَا يُنقَصُ مِنۡ عُمُرِهِۦٓ إِلَّا فِي كِتَٰبٍۚ إِنَّ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرࣱ',
  '22;44;1;175\nT;0;35:12:1:وَمَا يَسۡتَوِي ٱلۡبَحۡرَانِ هَٰذَا عَذۡبࣱ فُرَاتࣱ سَآئِغࣱ شَرَابُهُۥ وَهَٰذَا\nT;0;35:12:0:مِلۡحٌ أُجَاجࣱۖ وَمِن كُلࣲّ تَأۡكُلُونَ لَحۡمࣰا طَرِيࣰّا وَتَسۡتَخۡرِجُونَ\nT;0;35:12:0:حِلۡيَةࣰ تَلۡبَسُونَهَاۖ وَتَرَى ٱلۡفُلۡكَ فِيهِ مَوَاخِرَ لِتَبۡتَغُواْ مِن فَضۡلِهِۦ\nT;0;35:12:2:وَلَعَلَّكُمۡ تَشۡكُرُونَ¦35:13:1:يُولِجُ ٱلَّيۡلَ فِي ٱلنَّهَارِ وَيُولِجُ\nT;0;35:13:0:ٱلنَّهَارَ فِي ٱلَّيۡلِ وَسَخَّرَ ٱلشَّمۡسَ وَٱلۡقَمَرَۖ كُلࣱّ يَجۡرِي\nT;0;35:13:0:لِأَجَلࣲ مُّسَمࣰّىۚ ذَٰلِكُمُ ٱللَّهُ رَبُّكُمۡ لَهُ ٱلۡمُلۡكُۚ وَٱلَّذِينَ\nT;0;35:13:2:تَدۡعُونَ مِن دُونِهِۦ مَا يَمۡلِكُونَ مِن قِطۡمِيرٍ¦35:14:1:إِن\nT;0;35:14:0:تَدۡعُوهُمۡ لَا يَسۡمَعُواْ دُعَآءَكُمۡ وَلَوۡ سَمِعُواْ مَا ٱسۡتَجَابُواْ لَكُمۡۖ\nT;0;35:14:2:وَيَوۡمَ ٱلۡقِيَٰمَةِ يَكۡفُرُونَ بِشِرۡكِكُمۡۚ وَلَا يُنَبِّئُكَ مِثۡلُ خَبِيرࣲ\nT;0;35:15:1:۞ يَٰٓأَيُّهَا ٱلنَّاسُ أَنتُمُ ٱلۡفُقَرَآءُ إِلَى ٱللَّهِۖ وَٱللَّهُ هُوَ ٱلۡغَنِيُّ\nT;0;35:15:2:ٱلۡحَمِيدُ¦35:16:3:إِن يَشَأۡ يُذۡهِبۡكُمۡ وَيَأۡتِ بِخَلۡقࣲ جَدِيدࣲ\nT;0;35:17:3:وَمَا ذَٰلِكَ عَلَى ٱللَّهِ بِعَزِيزࣲ¦35:18:1:وَلَا تَزِرُ وَازِرَةࣱ وِزۡرَ أُخۡرَىٰۚ وَإِن\nT;0;35:18:0:تَدۡعُ مُثۡقَلَةٌ إِلَىٰ حِمۡلِهَا لَا يُحۡمَلۡ مِنۡهُ شَيۡءࣱ وَلَوۡ كَانَ ذَا قُرۡبَىٰٓۗ\nT;0;35:18:0:إِنَّمَا تُنذِرُ ٱلَّذِينَ يَخۡشَوۡنَ رَبَّهُم بِٱلۡغَيۡبِ وَأَقَامُواْ ٱلصَّلَوٰةَۚ\nT;0;35:18:2:وَمَن تَزَكَّىٰ فَإِنَّمَا يَتَزَكَّىٰ لِنَفۡسِهِۦۚ وَإِلَى ٱللَّهِ ٱلۡمَصِيرُ',
  '22;44;2;\nT;0;35:19:3:وَمَا يَسۡتَوِي ٱلۡأَعۡمَىٰ وَٱلۡبَصِيرُ¦35:20:3:وَلَا ٱلظُّلُمَٰتُ وَلَا ٱلنُّورُ\nT;0;35:21:3:وَلَا ٱلظِّلُّ وَلَا ٱلۡحَرُورُ¦35:22:1:وَمَا يَسۡتَوِي ٱلۡأَحۡيَآءُ وَلَا\nT;0;35:22:0:ٱلۡأَمۡوَٰتُۚ إِنَّ ٱللَّهَ يُسۡمِعُ مَن يَشَآءُۖ وَمَآ أَنتَ بِمُسۡمِعࣲ مَّن فِي\nT;0;35:22:2:ٱلۡقُبُورِ¦35:23:3:إِنۡ أَنتَ إِلَّا نَذِيرٌ¦35:24:1:إِنَّآ أَرۡسَلۡنَٰكَ بِٱلۡحَقِّ بَشِيرࣰا\nT;0;35:24:2:وَنَذِيرࣰاۚ وَإِن مِّنۡ أُمَّةٍ إِلَّا خَلَا فِيهَا نَذِيرࣱ¦35:25:1:وَإِن يُكَذِّبُوكَ\nT;0;35:25:0:فَقَدۡ كَذَّبَ ٱلَّذِينَ مِن قَبۡلِهِمۡ جَآءَتۡهُمۡ رُسُلُهُم بِٱلۡبَيِّنَٰتِ\nT;0;35:25:2:وَبِٱلزُّبُرِ وَبِٱلۡكِتَٰبِ ٱلۡمُنِيرِ¦35:26:1:ثُمَّ أَخَذۡتُ ٱلَّذِينَ كَفَرُواْۖ\nT;0;35:26:2:فَكَيۡفَ كَانَ نَكِيرِ¦35:27:1:أَلَمۡ تَرَ أَنَّ ٱللَّهَ أَنزَلَ مِنَ ٱلسَّمَآءِ\nT;0;35:27:0:مَآءࣰ فَأَخۡرَجۡنَا بِهِۦ ثَمَرَٰتࣲ مُّخۡتَلِفًا أَلۡوَٰنُهَاۚ وَمِنَ ٱلۡجِبَالِ\nT;0;35:27:2:جُدَدُۢ بِيضࣱ وَحُمۡرࣱ مُّخۡتَلِفٌ أَلۡوَٰنُهَا وَغَرَابِيبُ سُودࣱ\nT;0;35:28:1:وَمِنَ ٱلنَّاسِ وَٱلدَّوَآبِّ وَٱلۡأَنۡعَٰمِ مُخۡتَلِفٌ أَلۡوَٰنُهُۥ كَذَٰلِكَۗ\nT;0;35:28:2:إِنَّمَا يَخۡشَى ٱللَّهَ مِنۡ عِبَادِهِ ٱلۡعُلَمَٰٓؤُاْۗ إِنَّ ٱللَّهَ عَزِيزٌ غَفُورٌ\nT;0;35:29:1:إِنَّ ٱلَّذِينَ يَتۡلُونَ كِتَٰبَ ٱللَّهِ وَأَقَامُواْ ٱلصَّلَوٰةَ وَأَنفَقُواْ مِمَّا\nT;0;35:29:2:رَزَقۡنَٰهُمۡ سِرࣰّا وَعَلَانِيَةࣰ يَرۡجُونَ تِجَٰرَةࣰ لَّن تَبُورَ¦35:30:1:لِيُوَفِّيَهُمۡ\nT;0;35:30:2:أُجُورَهُمۡ وَيَزِيدَهُم مِّن فَضۡلِهِۦٓۚ إِنَّهُۥ غَفُورࣱ شَكُورࣱ',
  '22;44;2;\nT;0;35:31:1:وَٱلَّذِيٓ أَوۡحَيۡنَآ إِلَيۡكَ مِنَ ٱلۡكِتَٰبِ هُوَ ٱلۡحَقُّ مُصَدِّقࣰا لِّمَا بَيۡنَ\nT;0;35:31:2:يَدَيۡهِۗ إِنَّ ٱللَّهَ بِعِبَادِهِۦ لَخَبِيرُۢ بَصِيرࣱ¦35:32:1:ثُمَّ أَوۡرَثۡنَا ٱلۡكِتَٰبَ\nT;0;35:32:0:ٱلَّذِينَ ٱصۡطَفَيۡنَا مِنۡ عِبَادِنَاۖ فَمِنۡهُمۡ ظَالِمࣱ لِّنَفۡسِهِۦ وَمِنۡهُم\nT;0;35:32:0:مُّقۡتَصِدࣱ وَمِنۡهُمۡ سَابِقُۢ بِٱلۡخَيۡرَٰتِ بِإِذۡنِ ٱللَّهِۚ ذَٰلِكَ هُوَ\nT;0;35:32:2:ٱلۡفَضۡلُ ٱلۡكَبِيرُ¦35:33:1:جَنَّٰتُ عَدۡنࣲ يَدۡخُلُونَهَا يُحَلَّوۡنَ\nT;0;35:33:2:فِيهَا مِنۡ أَسَاوِرَ مِن ذَهَبࣲ وَلُؤۡلُؤࣰاۖ وَلِبَاسُهُمۡ فِيهَا حَرِيرࣱ\nT;0;35:34:1:وَقَالُواْ ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِيٓ أَذۡهَبَ عَنَّا ٱلۡحَزَنَۖ إِنَّ رَبَّنَا لَغَفُورࣱ\nT;0;35:34:2:شَكُورٌ¦35:35:1:ٱلَّذِيٓ أَحَلَّنَا دَارَ ٱلۡمُقَامَةِ مِن فَضۡلِهِۦ لَا يَمَسُّنَا\nT;0;35:35:2:فِيهَا نَصَبࣱ وَلَا يَمَسُّنَا فِيهَا لُغُوبࣱ¦35:36:1:وَٱلَّذِينَ كَفَرُواْ لَهُمۡ\nT;0;35:36:0:نَارُ جَهَنَّمَ لَا يُقۡضَىٰ عَلَيۡهِمۡ فَيَمُوتُواْ وَلَا يُخَفَّفُ عَنۡهُم مِّنۡ\nT;0;35:36:2:عَذَابِهَاۚ كَذَٰلِكَ نَجۡزِي كُلَّ كَفُورࣲ¦35:37:1:وَهُمۡ يَصۡطَرِخُونَ\nT;0;35:37:0:فِيهَا رَبَّنَآ أَخۡرِجۡنَا نَعۡمَلۡ صَٰلِحًا غَيۡرَ ٱلَّذِي كُنَّا نَعۡمَلُۚ\nT;0;35:37:0:أَوَلَمۡ نُعَمِّرۡكُم مَّا يَتَذَكَّرُ فِيهِ مَن تَذَكَّرَ وَجَآءَكُمُ ٱلنَّذِيرُۖ\nT;0;35:37:2:فَذُوقُواْ فَمَا لِلظَّٰلِمِينَ مِن نَّصِيرٍ¦35:38:1:إِنَّ ٱللَّهَ عَٰلِمُ\nT;0;35:38:2:غَيۡبِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ إِنَّهُۥ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ',
  '22;44;2;176\nT;0;35:39:1:هُوَ ٱلَّذِي جَعَلَكُمۡ خَلَٰٓئِفَ فِي ٱلۡأَرۡضِۚ فَمَن كَفَرَ فَعَلَيۡهِ كُفۡرُهُۥۖ وَلَا\nT;0;35:39:0:يَزِيدُ ٱلۡكَٰفِرِينَ كُفۡرُهُمۡ عِندَ رَبِّهِمۡ إِلَّا مَقۡتࣰاۖ وَلَا يَزِيدُ ٱلۡكَٰفِرِينَ\nT;0;35:39:2:كُفۡرُهُمۡ إِلَّا خَسَارࣰا¦35:40:1:قُلۡ أَرَءَيۡتُمۡ شُرَكَآءَكُمُ ٱلَّذِينَ تَدۡعُونَ مِن\nT;0;35:40:0:دُونِ ٱللَّهِ أَرُونِي مَاذَا خَلَقُواْ مِنَ ٱلۡأَرۡضِ أَمۡ لَهُمۡ شِرۡكࣱ فِي ٱلسَّمَٰوَٰتِ\nT;0;35:40:0:أَمۡ ءَاتَيۡنَٰهُمۡ كِتَٰبࣰا فَهُمۡ عَلَىٰ بَيِّنَتࣲ مِّنۡهُۚ بَلۡ إِن يَعِدُ ٱلظَّٰلِمُونَ\nT;0;35:40:2:بَعۡضُهُم بَعۡضًا إِلَّا غُرُورًا¦35:41:1:۞ إِنَّ ٱللَّهَ يُمۡسِكُ ٱلسَّمَٰوَٰتِ\nT;0;35:41:0:وَٱلۡأَرۡضَ أَن تَزُولَاۚ وَلَئِن زَالَتَآ إِنۡ أَمۡسَكَهُمَا مِنۡ أَحَدࣲ مِّنۢ بَعۡدِهِۦٓۚ\nT;0;35:41:2:إِنَّهُۥ كَانَ حَلِيمًا غَفُورࣰا¦35:42:1:وَأَقۡسَمُواْ بِٱللَّهِ جَهۡدَ أَيۡمَٰنِهِمۡ لَئِن جَآءَهُمۡ\nT;0;35:42:0:نَذِيرࣱ لَّيَكُونُنَّ أَهۡدَىٰ مِنۡ إِحۡدَى ٱلۡأُمَمِۖ فَلَمَّا جَآءَهُمۡ نَذِيرࣱ\nT;0;35:42:2:مَّا زَادَهُمۡ إِلَّا نُفُورًا¦35:43:1:ٱسۡتِكۡبَارࣰا فِي ٱلۡأَرۡضِ وَمَكۡرَ ٱلسَّيِّيِٕۚ\nT;0;35:43:0:وَلَا يَحِيقُ ٱلۡمَكۡرُ ٱلسَّيِّئُ إِلَّا بِأَهۡلِهِۦۚ فَهَلۡ يَنظُرُونَ إِلَّا سُنَّتَ\nT;0;35:43:2:ٱلۡأَوَّلِينَۚ فَلَن تَجِدَ لِسُنَّتِ ٱللَّهِ تَبۡدِيلࣰاۖ وَلَن تَجِدَ لِسُنَّتِ ٱللَّهِ تَحۡوِيلًا\nT;0;35:44:1:أَوَلَمۡ يَسِيرُواْ فِي ٱلۡأَرۡضِ فَيَنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن\nT;0;35:44:0:قَبۡلِهِمۡ وَكَانُوٓاْ أَشَدَّ مِنۡهُمۡ قُوَّةࣰۚ وَمَا كَانَ ٱللَّهُ لِيُعۡجِزَهُۥ مِن شَيۡءࣲ\nT;0;35:44:2:فِي ٱلسَّمَٰوَٰتِ وَلَا فِي ٱلۡأَرۡضِۚ إِنَّهُۥ كَانَ عَلِيمࣰا قَدِيرࣰا',
  '22;44;3;\nT;0;35:45:1:وَلَوۡ يُؤَاخِذُ ٱللَّهُ ٱلنَّاسَ بِمَا كَسَبُواْ مَا تَرَكَ عَلَىٰ ظَهۡرِهَا\nT;0;35:45:0:مِن دَآبَّةࣲ وَلَٰكِن يُؤَخِّرُهُمۡ إِلَىٰٓ أَجَلࣲ مُّسَمࣰّىۖ فَإِذَا\nT;2;35:45:2:جَآءَ أَجَلُهُمۡ فَإِنَّ ٱللَّهَ كَانَ بِعِبَادِهِۦ بَصِيرَۢا\nH;36\nB;36\nT;0;36:1:3:يسٓ¦36:2:3:وَٱلۡقُرۡءَانِ ٱلۡحَكِيمِ¦36:3:3:إِنَّكَ لَمِنَ ٱلۡمُرۡسَلِينَ¦36:4:1:عَلَىٰ\nT;0;36:4:2:صِرَٰطࣲ مُّسۡتَقِيمࣲ¦36:5:3:تَنزِيلَ ٱلۡعَزِيزِ ٱلرَّحِيمِ¦36:6:1:لِتُنذِرَ قَوۡمࣰا\nT;0;36:6:2:مَّآ أُنذِرَ ءَابَآؤُهُمۡ فَهُمۡ غَٰفِلُونَ¦36:7:1:لَقَدۡ حَقَّ ٱلۡقَوۡلُ عَلَىٰٓ أَكۡثَرِهِمۡ\nT;0;36:7:2:فَهُمۡ لَا يُؤۡمِنُونَ¦36:8:1:إِنَّا جَعَلۡنَا فِيٓ أَعۡنَٰقِهِمۡ أَغۡلَٰلࣰا فَهِيَ إِلَى\nT;0;36:8:2:ٱلۡأَذۡقَانِ فَهُم مُّقۡمَحُونَ¦36:9:1:وَجَعَلۡنَا مِنۢ بَيۡنِ أَيۡدِيهِمۡ سَدࣰّا\nT;0;36:9:2:وَمِنۡ خَلۡفِهِمۡ سَدࣰّا فَأَغۡشَيۡنَٰهُمۡ فَهُمۡ لَا يُبۡصِرُونَ¦36:10:1:وَسَوَآءٌ\nT;0;36:10:2:عَلَيۡهِمۡ ءَأَنذَرۡتَهُمۡ أَمۡ لَمۡ تُنذِرۡهُمۡ لَا يُؤۡمِنُونَ¦36:11:1:إِنَّمَا تُنذِرُ\nT;0;36:11:0:مَنِ ٱتَّبَعَ ٱلذِّكۡرَ وَخَشِيَ ٱلرَّحۡمَٰنَ بِٱلۡغَيۡبِۖ فَبَشِّرۡهُ بِمَغۡفِرَةࣲ\nT;0;36:11:2:وَأَجۡرࣲ كَرِيمٍ¦36:12:1:إِنَّا نَحۡنُ نُحۡيِ ٱلۡمَوۡتَىٰ وَنَكۡتُبُ مَا قَدَّمُواْ\nT;0;36:12:2:وَءَاثَٰرَهُمۡۚ وَكُلَّ شَيۡءٍ أَحۡصَيۡنَٰهُ فِيٓ إِمَامࣲ مُّبِينࣲ',
  '22;44;3;\nT;0;36:13:3:وَٱضۡرِبۡ لَهُم مَّثَلًا أَصۡحَٰبَ ٱلۡقَرۡيَةِ إِذۡ جَآءَهَا ٱلۡمُرۡسَلُونَ\nT;0;36:14:1:إِذۡ أَرۡسَلۡنَآ إِلَيۡهِمُ ٱثۡنَيۡنِ فَكَذَّبُوهُمَا فَعَزَّزۡنَا بِثَالِثࣲ فَقَالُوٓاْ\nT;0;36:14:2:إِنَّآ إِلَيۡكُم مُّرۡسَلُونَ¦36:15:1:قَالُواْ مَآ أَنتُمۡ إِلَّا بَشَرࣱ مِّثۡلُنَا\nT;0;36:15:2:وَمَآ أَنزَلَ ٱلرَّحۡمَٰنُ مِن شَيۡءٍ إِنۡ أَنتُمۡ إِلَّا تَكۡذِبُونَ¦36:16:1:قَالُواْ\nT;0;36:16:2:رَبُّنَا يَعۡلَمُ إِنَّآ إِلَيۡكُمۡ لَمُرۡسَلُونَ¦36:17:1:وَمَا عَلَيۡنَآ إِلَّا ٱلۡبَلَٰغُ\nT;0;36:17:2:ٱلۡمُبِينُ¦36:18:1:قَالُوٓاْ إِنَّا تَطَيَّرۡنَا بِكُمۡۖ لَئِن لَّمۡ تَنتَهُواْ لَنَرۡجُمَنَّكُمۡ\nT;0;36:18:2:وَلَيَمَسَّنَّكُم مِّنَّا عَذَابٌ أَلِيمࣱ¦36:19:1:قَالُواْ طَٰٓئِرُكُم مَّعَكُمۡ أَئِن\nT;0;36:19:2:ذُكِّرۡتُمۚ بَلۡ أَنتُمۡ قَوۡمࣱ مُّسۡرِفُونَ¦36:20:1:وَجَآءَ مِنۡ أَقۡصَا ٱلۡمَدِينَةِ\nT;0;36:20:2:رَجُلࣱ يَسۡعَىٰ قَالَ يَٰقَوۡمِ ٱتَّبِعُواْ ٱلۡمُرۡسَلِينَ¦36:21:1:ٱتَّبِعُواْ\nT;0;36:21:2:مَن لَّا يَسۡـَٔلُكُمۡ أَجۡرࣰا وَهُم مُّهۡتَدُونَ¦36:22:1:وَمَا لِيَ لَآ أَعۡبُدُ\nT;0;36:22:2:ٱلَّذِي فَطَرَنِي وَإِلَيۡهِ تُرۡجَعُونَ¦36:23:1:ءَأَتَّخِذُ مِن دُونِهِۦٓ ءَالِهَةً\nT;0;36:23:0:إِن يُرِدۡنِ ٱلرَّحۡمَٰنُ بِضُرࣲّ لَّا تُغۡنِ عَنِّي شَفَٰعَتُهُمۡ شَيۡـࣰٔا\nT;0;36:23:2:وَلَا يُنقِذُونِ¦36:24:3:إِنِّيٓ إِذࣰا لَّفِي ضَلَٰلࣲ مُّبِينٍ¦36:25:1:إِنِّيٓ ءَامَنتُ\nT;0;36:25:2:بِرَبِّكُمۡ فَٱسۡمَعُونِ¦36:26:1:قِيلَ ٱدۡخُلِ ٱلۡجَنَّةَۖ قَالَ يَٰلَيۡتَ قَوۡمِي\nT;0;36:26:2:يَعۡلَمُونَ¦36:27:3:بِمَا غَفَرَ لِي رَبِّي وَجَعَلَنِي مِنَ ٱلۡمُكۡرَمِينَ',
  '23;45;0;177\nT;0;36:28:1:۞ وَمَآ أَنزَلۡنَا عَلَىٰ قَوۡمِهِۦ مِنۢ بَعۡدِهِۦ مِن جُندࣲ مِّنَ ٱلسَّمَآءِ وَمَا كُنَّا\nT;0;36:28:2:مُنزِلِينَ¦36:29:3:إِن كَانَتۡ إِلَّا صَيۡحَةࣰ وَٰحِدَةࣰ فَإِذَا هُمۡ خَٰمِدُونَ\nT;0;36:30:1:يَٰحَسۡرَةً عَلَى ٱلۡعِبَادِۚ مَا يَأۡتِيهِم مِّن رَّسُولٍ إِلَّا كَانُواْ بِهِۦ\nT;0;36:30:2:يَسۡتَهۡزِءُونَ¦36:31:1:أَلَمۡ يَرَوۡاْ كَمۡ أَهۡلَكۡنَا قَبۡلَهُم مِّنَ ٱلۡقُرُونِ\nT;0;36:31:2:أَنَّهُمۡ إِلَيۡهِمۡ لَا يَرۡجِعُونَ¦36:32:3:وَإِن كُلࣱّ لَّمَّا جَمِيعࣱ لَّدَيۡنَا مُحۡضَرُونَ\nT;0;36:33:1:وَءَايَةࣱ لَّهُمُ ٱلۡأَرۡضُ ٱلۡمَيۡتَةُ أَحۡيَيۡنَٰهَا وَأَخۡرَجۡنَا مِنۡهَا حَبࣰّا\nT;0;36:33:2:فَمِنۡهُ يَأۡكُلُونَ¦36:34:1:وَجَعَلۡنَا فِيهَا جَنَّٰتࣲ مِّن نَّخِيلࣲ\nT;0;36:34:2:وَأَعۡنَٰبࣲ وَفَجَّرۡنَا فِيهَا مِنَ ٱلۡعُيُونِ¦36:35:1:لِيَأۡكُلُواْ مِن ثَمَرِهِۦ\nT;0;36:35:2:وَمَا عَمِلَتۡهُ أَيۡدِيهِمۡۚ أَفَلَا يَشۡكُرُونَ¦36:36:1:سُبۡحَٰنَ ٱلَّذِي\nT;0;36:36:0:خَلَقَ ٱلۡأَزۡوَٰجَ كُلَّهَا مِمَّا تُنۢبِتُ ٱلۡأَرۡضُ وَمِنۡ أَنفُسِهِمۡ\nT;0;36:36:2:وَمِمَّا لَا يَعۡلَمُونَ¦36:37:1:وَءَايَةࣱ لَّهُمُ ٱلَّيۡلُ نَسۡلَخُ مِنۡهُ ٱلنَّهَارَ\nT;0;36:37:2:فَإِذَا هُم مُّظۡلِمُونَ¦36:38:1:وَٱلشَّمۡسُ تَجۡرِي لِمُسۡتَقَرࣲّ لَّهَاۚ\nT;0;36:38:2:ذَٰلِكَ تَقۡدِيرُ ٱلۡعَزِيزِ ٱلۡعَلِيمِ¦36:39:1:وَٱلۡقَمَرَ قَدَّرۡنَٰهُ مَنَازِلَ حَتَّىٰ\nT;0;36:39:2:عَادَ كَٱلۡعُرۡجُونِ ٱلۡقَدِيمِ¦36:40:1:لَا ٱلشَّمۡسُ يَنۢبَغِي لَهَآ أَن تُدۡرِكَ\nT;0;36:40:2:ٱلۡقَمَرَ وَلَا ٱلَّيۡلُ سَابِقُ ٱلنَّهَارِۚ وَكُلࣱّ فِي فَلَكࣲ يَسۡبَحُونَ',
  '23;45;0;\nT;0;36:41:3:وَءَايَةࣱ لَّهُمۡ أَنَّا حَمَلۡنَا ذُرِّيَّتَهُمۡ فِي ٱلۡفُلۡكِ ٱلۡمَشۡحُونِ¦36:42:1:وَخَلَقۡنَا\nT;0;36:42:2:لَهُم مِّن مِّثۡلِهِۦ مَا يَرۡكَبُونَ¦36:43:1:وَإِن نَّشَأۡ نُغۡرِقۡهُمۡ فَلَا صَرِيخَ لَهُمۡ\nT;0;36:43:2:وَلَا هُمۡ يُنقَذُونَ¦36:44:3:إِلَّا رَحۡمَةࣰ مِّنَّا وَمَتَٰعًا إِلَىٰ حِينࣲ¦36:45:1:وَإِذَا\nT;0;36:45:2:قِيلَ لَهُمُ ٱتَّقُواْ مَا بَيۡنَ أَيۡدِيكُمۡ وَمَا خَلۡفَكُمۡ لَعَلَّكُمۡ تُرۡحَمُونَ\nT;0;36:46:1:وَمَا تَأۡتِيهِم مِّنۡ ءَايَةࣲ مِّنۡ ءَايَٰتِ رَبِّهِمۡ إِلَّا كَانُواْ عَنۡهَا\nT;0;36:46:2:مُعۡرِضِينَ¦36:47:1:وَإِذَا قِيلَ لَهُمۡ أَنفِقُواْ مِمَّا رَزَقَكُمُ ٱللَّهُ قَالَ ٱلَّذِينَ\nT;0;36:47:0:كَفَرُواْ لِلَّذِينَ ءَامَنُوٓاْ أَنُطۡعِمُ مَن لَّوۡ يَشَآءُ ٱللَّهُ أَطۡعَمَهُۥٓ إِنۡ\nT;0;36:47:2:أَنتُمۡ إِلَّا فِي ضَلَٰلࣲ مُّبِينࣲ¦36:48:1:وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلۡوَعۡدُ إِن كُنتُمۡ\nT;0;36:48:2:صَٰدِقِينَ¦36:49:1:مَا يَنظُرُونَ إِلَّا صَيۡحَةࣰ وَٰحِدَةࣰ تَأۡخُذُهُمۡ وَهُمۡ\nT;0;36:49:2:يَخِصِّمُونَ¦36:50:1:فَلَا يَسۡتَطِيعُونَ تَوۡصِيَةࣰ وَلَآ إِلَىٰٓ أَهۡلِهِمۡ\nT;0;36:50:2:يَرۡجِعُونَ¦36:51:1:وَنُفِخَ فِي ٱلصُّورِ فَإِذَا هُم مِّنَ ٱلۡأَجۡدَاثِ إِلَىٰ رَبِّهِمۡ\nT;0;36:51:2:يَنسِلُونَ¦36:52:1:قَالُواْ يَٰوَيۡلَنَا مَنۢ بَعَثَنَا مِن مَّرۡقَدِنَاۜۗ هَٰذَا مَا وَعَدَ\nT;0;36:52:2:ٱلرَّحۡمَٰنُ وَصَدَقَ ٱلۡمُرۡسَلُونَ¦36:53:1:إِن كَانَتۡ إِلَّا صَيۡحَةࣰ\nT;0;36:53:2:وَٰحِدَةࣰ فَإِذَا هُمۡ جَمِيعࣱ لَّدَيۡنَا مُحۡضَرُونَ¦36:54:1:فَٱلۡيَوۡمَ لَا تُظۡلَمُ\nT;0;36:54:2:نَفۡسࣱ شَيۡـࣰٔا وَلَا تُجۡزَوۡنَ إِلَّا مَا كُنتُمۡ تَعۡمَلُونَ',
  '23;45;0;178\nT;0;36:55:3:إِنَّ أَصۡحَٰبَ ٱلۡجَنَّةِ ٱلۡيَوۡمَ فِي شُغُلࣲ فَٰكِهُونَ¦36:56:1:هُمۡ وَأَزۡوَٰجُهُمۡ\nT;0;36:56:2:فِي ظِلَٰلٍ عَلَى ٱلۡأَرَآئِكِ مُتَّكِـُٔونَ¦36:57:1:لَهُمۡ فِيهَا فَٰكِهَةࣱ\nT;0;36:57:2:وَلَهُم مَّا يَدَّعُونَ¦36:58:3:سَلَٰمࣱ قَوۡلࣰا مِّن رَّبࣲّ رَّحِيمࣲ¦36:59:1:وَٱمۡتَٰزُواْ\nT;0;36:59:2:ٱلۡيَوۡمَ أَيُّهَا ٱلۡمُجۡرِمُونَ¦36:60:1:۞ أَلَمۡ أَعۡهَدۡ إِلَيۡكُمۡ يَٰبَنِيٓ ءَادَمَ\nT;0;36:60:2:أَن لَّا تَعۡبُدُواْ ٱلشَّيۡطَٰنَۖ إِنَّهُۥ لَكُمۡ عَدُوࣱّ مُّبِينࣱ¦36:61:1:وَأَنِ\nT;0;36:61:2:ٱعۡبُدُونِيۚ هَٰذَا صِرَٰطࣱ مُّسۡتَقِيمࣱ¦36:62:1:وَلَقَدۡ أَضَلَّ مِنكُمۡ\nT;0;36:62:2:جِبِلࣰّا كَثِيرًاۖ أَفَلَمۡ تَكُونُواْ تَعۡقِلُونَ¦36:63:1:هَٰذِهِۦ جَهَنَّمُ ٱلَّتِي\nT;0;36:63:2:كُنتُمۡ تُوعَدُونَ¦36:64:3:ٱصۡلَوۡهَا ٱلۡيَوۡمَ بِمَا كُنتُمۡ تَكۡفُرُونَ\nT;0;36:65:1:ٱلۡيَوۡمَ نَخۡتِمُ عَلَىٰٓ أَفۡوَٰهِهِمۡ وَتُكَلِّمُنَآ أَيۡدِيهِمۡ وَتَشۡهَدُ أَرۡجُلُهُم\nT;0;36:65:2:بِمَا كَانُواْ يَكۡسِبُونَ¦36:66:1:وَلَوۡ نَشَآءُ لَطَمَسۡنَا عَلَىٰٓ أَعۡيُنِهِمۡ\nT;0;36:66:2:فَٱسۡتَبَقُواْ ٱلصِّرَٰطَ فَأَنَّىٰ يُبۡصِرُونَ¦36:67:1:وَلَوۡ نَشَآءُ لَمَسَخۡنَٰهُمۡ\nT;0;36:67:2:عَلَىٰ مَكَانَتِهِمۡ فَمَا ٱسۡتَطَٰعُواْ مُضِيࣰّا وَلَا يَرۡجِعُونَ\nT;0;36:68:3:وَمَن نُّعَمِّرۡهُ نُنَكِّسۡهُ فِي ٱلۡخَلۡقِۚ أَفَلَا يَعۡقِلُونَ¦36:69:1:وَمَا\nT;0;36:69:2:عَلَّمۡنَٰهُ ٱلشِّعۡرَ وَمَا يَنۢبَغِي لَهُۥٓۚ إِنۡ هُوَ إِلَّا ذِكۡرࣱ وَقُرۡءَانࣱ مُّبِينࣱ\nT;0;36:70:3:لِّيُنذِرَ مَن كَانَ حَيࣰّا وَيَحِقَّ ٱلۡقَوۡلُ عَلَى ٱلۡكَٰفِرِينَ',
  '23;45;1;\nT;0;36:71:1:أَوَلَمۡ يَرَوۡاْ أَنَّا خَلَقۡنَا لَهُم مِّمَّا عَمِلَتۡ أَيۡدِينَآ أَنۡعَٰمࣰا\nT;0;36:71:2:فَهُمۡ لَهَا مَٰلِكُونَ¦36:72:1:وَذَلَّلۡنَٰهَا لَهُمۡ فَمِنۡهَا رَكُوبُهُمۡ\nT;0;36:72:2:وَمِنۡهَا يَأۡكُلُونَ¦36:73:1:وَلَهُمۡ فِيهَا مَنَٰفِعُ وَمَشَارِبُۚ\nT;0;36:73:2:أَفَلَا يَشۡكُرُونَ¦36:74:1:وَٱتَّخَذُواْ مِن دُونِ ٱللَّهِ ءَالِهَةࣰ\nT;0;36:74:2:لَّعَلَّهُمۡ يُنصَرُونَ¦36:75:1:لَا يَسۡتَطِيعُونَ نَصۡرَهُمۡ وَهُمۡ\nT;0;36:75:2:لَهُمۡ جُندࣱ مُّحۡضَرُونَ¦36:76:1:فَلَا يَحۡزُنكَ قَوۡلُهُمۡۘ إِنَّا نَعۡلَمُ\nT;0;36:76:2:مَا يُسِرُّونَ وَمَا يُعۡلِنُونَ¦36:77:1:أَوَلَمۡ يَرَ ٱلۡإِنسَٰنُ أَنَّا خَلَقۡنَٰهُ\nT;0;36:77:2:مِن نُّطۡفَةࣲ فَإِذَا هُوَ خَصِيمࣱ مُّبِينࣱ¦36:78:1:وَضَرَبَ لَنَا\nT;0;36:78:2:مَثَلࣰا وَنَسِيَ خَلۡقَهُۥۖ قَالَ مَن يُحۡيِ ٱلۡعِظَٰمَ وَهِيَ رَمِيمࣱ\nT;0;36:79:3:قُلۡ يُحۡيِيهَا ٱلَّذِيٓ أَنشَأَهَآ أَوَّلَ مَرَّةࣲۖ وَهُوَ بِكُلِّ خَلۡقٍ عَلِيمٌ\nT;0;36:80:1:ٱلَّذِي جَعَلَ لَكُم مِّنَ ٱلشَّجَرِ ٱلۡأَخۡضَرِ نَارࣰا فَإِذَآ أَنتُم\nT;0;36:80:2:مِّنۡهُ تُوقِدُونَ¦36:81:1:أَوَلَيۡسَ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ\nT;0;36:81:2:بِقَٰدِرٍ عَلَىٰٓ أَن يَخۡلُقَ مِثۡلَهُمۚ بَلَىٰ وَهُوَ ٱلۡخَلَّٰقُ ٱلۡعَلِيمُ\nT;0;36:82:3:إِنَّمَآ أَمۡرُهُۥٓ إِذَآ أَرَادَ شَيۡـًٔا أَن يَقُولَ لَهُۥ كُن فَيَكُونُ\nT;2;36:83:3:فَسُبۡحَٰنَ ٱلَّذِي بِيَدِهِۦ مَلَكُوتُ كُلِّ شَيۡءࣲ وَإِلَيۡهِ تُرۡجَعُونَ',
  '23;45;1;179\nH;37\nB;37\nT;0;37:1:3:وَٱلصَّٰٓفَّٰتِ صَفࣰّا¦37:2:3:فَٱلزَّٰجِرَٰتِ زَجۡرࣰا¦37:3:3:فَٱلتَّٰلِيَٰتِ ذِكۡرًا¦37:4:1:إِنَّ إِلَٰهَكُمۡ\nT;0;37:4:2:لَوَٰحِدࣱ¦37:5:3:رَّبُّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا بَيۡنَهُمَا وَرَبُّ ٱلۡمَشَٰرِقِ¦37:6:1:إِنَّا زَيَّنَّا\nT;0;37:6:2:ٱلسَّمَآءَ ٱلدُّنۡيَا بِزِينَةٍ ٱلۡكَوَاكِبِ¦37:7:3:وَحِفۡظࣰا مِّن كُلِّ شَيۡطَٰنࣲ مَّارِدࣲ\nT;0;37:8:3:لَّا يَسَّمَّعُونَ إِلَى ٱلۡمَلَإِ ٱلۡأَعۡلَىٰ وَيُقۡذَفُونَ مِن كُلِّ جَانِبࣲ¦37:9:1:دُحُورࣰاۖ وَلَهُمۡ\nT;0;37:9:2:عَذَابࣱ وَاصِبٌ¦37:10:3:إِلَّا مَنۡ خَطِفَ ٱلۡخَطۡفَةَ فَأَتۡبَعَهُۥ شِهَابࣱ ثَاقِبࣱ\nT;0;37:11:3:فَٱسۡتَفۡتِهِمۡ أَهُمۡ أَشَدُّ خَلۡقًا أَم مَّنۡ خَلَقۡنَآۚ إِنَّا خَلَقۡنَٰهُم مِّن طِينࣲ لَّازِبِۭ\nT;0;37:12:3:بَلۡ عَجِبۡتَ وَيَسۡخَرُونَ¦37:13:3:وَإِذَا ذُكِّرُواْ لَا يَذۡكُرُونَ¦37:14:1:وَإِذَا رَأَوۡاْ ءَايَةࣰ\nT;0;37:14:2:يَسۡتَسۡخِرُونَ¦37:15:3:وَقَالُوٓاْ إِنۡ هَٰذَآ إِلَّا سِحۡرࣱ مُّبِينٌ¦37:16:1:أَءِذَا مِتۡنَا\nT;0;37:16:2:وَكُنَّا تُرَابࣰا وَعِظَٰمًا أَءِنَّا لَمَبۡعُوثُونَ¦37:17:3:أَوَءَابَآؤُنَا ٱلۡأَوَّلُونَ¦37:18:1:قُلۡ نَعَمۡ\nT;0;37:18:2:وَأَنتُمۡ دَٰخِرُونَ¦37:19:3:فَإِنَّمَا هِيَ زَجۡرَةࣱ وَٰحِدَةࣱ فَإِذَا هُمۡ يَنظُرُونَ¦37:20:1:وَقَالُواْ\nT;0;37:20:2:يَٰوَيۡلَنَا هَٰذَا يَوۡمُ ٱلدِّينِ¦37:21:3:هَٰذَا يَوۡمُ ٱلۡفَصۡلِ ٱلَّذِي كُنتُم بِهِۦ تُكَذِّبُونَ\nT;0;37:22:3:۞ ٱحۡشُرُواْ ٱلَّذِينَ ظَلَمُواْ وَأَزۡوَٰجَهُمۡ وَمَا كَانُواْ يَعۡبُدُونَ¦37:23:1:مِن دُونِ\nT;0;37:23:2:ٱللَّهِ فَٱهۡدُوهُمۡ إِلَىٰ صِرَٰطِ ٱلۡجَحِيمِ¦37:24:3:وَقِفُوهُمۡۖ إِنَّهُم مَّسۡـُٔولُونَ',
  '23;45;2;\nT;0;37:25:3:مَا لَكُمۡ لَا تَنَاصَرُونَ¦37:26:3:بَلۡ هُمُ ٱلۡيَوۡمَ مُسۡتَسۡلِمُونَ¦37:27:1:وَأَقۡبَلَ بَعۡضُهُمۡ\nT;0;37:27:2:عَلَىٰ بَعۡضࣲ يَتَسَآءَلُونَ¦37:28:3:قَالُوٓاْ إِنَّكُمۡ كُنتُمۡ تَأۡتُونَنَا عَنِ ٱلۡيَمِينِ\nT;0;37:29:3:قَالُواْ بَل لَّمۡ تَكُونُواْ مُؤۡمِنِينَ¦37:30:1:وَمَا كَانَ لَنَا عَلَيۡكُم مِّن سُلۡطَٰنِۭۖ\nT;0;37:30:2:بَلۡ كُنتُمۡ قَوۡمࣰا طَٰغِينَ¦37:31:3:فَحَقَّ عَلَيۡنَا قَوۡلُ رَبِّنَآۖ إِنَّا لَذَآئِقُونَ\nT;0;37:32:3:فَأَغۡوَيۡنَٰكُمۡ إِنَّا كُنَّا غَٰوِينَ¦37:33:1:فَإِنَّهُمۡ يَوۡمَئِذࣲ فِي ٱلۡعَذَابِ\nT;0;37:33:2:مُشۡتَرِكُونَ¦37:34:3:إِنَّا كَذَٰلِكَ نَفۡعَلُ بِٱلۡمُجۡرِمِينَ¦37:35:1:إِنَّهُمۡ كَانُوٓاْ إِذَا قِيلَ\nT;0;37:35:2:لَهُمۡ لَآ إِلَٰهَ إِلَّا ٱللَّهُ يَسۡتَكۡبِرُونَ¦37:36:1:وَيَقُولُونَ أَئِنَّا لَتَارِكُوٓاْ ءَالِهَتِنَا\nT;0;37:36:2:لِشَاعِرࣲ مَّجۡنُونِۭ¦37:37:3:بَلۡ جَآءَ بِٱلۡحَقِّ وَصَدَّقَ ٱلۡمُرۡسَلِينَ¦37:38:1:إِنَّكُمۡ\nT;0;37:38:2:لَذَآئِقُواْ ٱلۡعَذَابِ ٱلۡأَلِيمِ¦37:39:3:وَمَا تُجۡزَوۡنَ إِلَّا مَا كُنتُمۡ تَعۡمَلُونَ\nT;0;37:40:3:إِلَّا عِبَادَ ٱللَّهِ ٱلۡمُخۡلَصِينَ¦37:41:3:أُوْلَٰٓئِكَ لَهُمۡ رِزۡقࣱ مَّعۡلُومࣱ¦37:42:1:فَوَٰكِهُ\nT;0;37:42:2:وَهُم مُّكۡرَمُونَ¦37:43:3:فِي جَنَّٰتِ ٱلنَّعِيمِ¦37:44:3:عَلَىٰ سُرُرࣲ مُّتَقَٰبِلِينَ\nT;0;37:45:3:يُطَافُ عَلَيۡهِم بِكَأۡسࣲ مِّن مَّعِينِۭ¦37:46:3:بَيۡضَآءَ لَذَّةࣲ لِّلشَّٰرِبِينَ\nT;0;37:47:3:لَا فِيهَا غَوۡلࣱ وَلَا هُمۡ عَنۡهَا يُنزَفُونَ¦37:48:1:وَعِندَهُمۡ قَٰصِرَٰتُ\nT;0;37:48:2:ٱلطَّرۡفِ عِينࣱ¦37:49:3:كَأَنَّهُنَّ بَيۡضࣱ مَّكۡنُونࣱ¦37:50:1:فَأَقۡبَلَ بَعۡضُهُمۡ عَلَىٰ\nT;0;37:50:2:بَعۡضࣲ يَتَسَآءَلُونَ¦37:51:3:قَالَ قَآئِلࣱ مِّنۡهُمۡ إِنِّي كَانَ لِي قَرِينࣱ',
  '23;45;2;\nT;0;37:52:3:يَقُولُ أَءِنَّكَ لَمِنَ ٱلۡمُصَدِّقِينَ¦37:53:1:أَءِذَا مِتۡنَا وَكُنَّا تُرَابࣰا وَعِظَٰمًا أَءِنَّا\nT;0;37:53:2:لَمَدِينُونَ¦37:54:3:قَالَ هَلۡ أَنتُم مُّطَّلِعُونَ¦37:55:1:فَٱطَّلَعَ فَرَءَاهُ فِي سَوَآءِ\nT;0;37:55:2:ٱلۡجَحِيمِ¦37:56:3:قَالَ تَٱللَّهِ إِن كِدتَّ لَتُرۡدِينِ¦37:57:1:وَلَوۡلَا نِعۡمَةُ رَبِّي\nT;0;37:57:2:لَكُنتُ مِنَ ٱلۡمُحۡضَرِينَ¦37:58:3:أَفَمَا نَحۡنُ بِمَيِّتِينَ¦37:59:1:إِلَّا مَوۡتَتَنَا\nT;0;37:59:2:ٱلۡأُولَىٰ وَمَا نَحۡنُ بِمُعَذَّبِينَ¦37:60:3:إِنَّ هَٰذَا لَهُوَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ\nT;0;37:61:3:لِمِثۡلِ هَٰذَا فَلۡيَعۡمَلِ ٱلۡعَٰمِلُونَ¦37:62:1:أَذَٰلِكَ خَيۡرࣱ نُّزُلًا أَمۡ شَجَرَةُ\nT;0;37:62:2:ٱلزَّقُّومِ¦37:63:3:إِنَّا جَعَلۡنَٰهَا فِتۡنَةࣰ لِّلظَّٰلِمِينَ¦37:64:1:إِنَّهَا شَجَرَةࣱ تَخۡرُجُ\nT;0;37:64:2:فِيٓ أَصۡلِ ٱلۡجَحِيمِ¦37:65:3:طَلۡعُهَا كَأَنَّهُۥ رُءُوسُ ٱلشَّيَٰطِينِ\nT;0;37:66:3:فَإِنَّهُمۡ لَأٓكِلُونَ مِنۡهَا فَمَالِـُٔونَ مِنۡهَا ٱلۡبُطُونَ¦37:67:1:ثُمَّ إِنَّ لَهُمۡ\nT;0;37:67:2:عَلَيۡهَا لَشَوۡبࣰا مِّنۡ حَمِيمࣲ¦37:68:3:ثُمَّ إِنَّ مَرۡجِعَهُمۡ لَإِلَى ٱلۡجَحِيمِ\nT;0;37:69:3:إِنَّهُمۡ أَلۡفَوۡاْ ءَابَآءَهُمۡ ضَآلِّينَ¦37:70:3:فَهُمۡ عَلَىٰٓ ءَاثَٰرِهِمۡ يُهۡرَعُونَ\nT;0;37:71:3:وَلَقَدۡ ضَلَّ قَبۡلَهُمۡ أَكۡثَرُ ٱلۡأَوَّلِينَ¦37:72:1:وَلَقَدۡ أَرۡسَلۡنَا فِيهِم\nT;0;37:72:2:مُّنذِرِينَ¦37:73:3:فَٱنظُرۡ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُنذَرِينَ\nT;0;37:74:3:إِلَّا عِبَادَ ٱللَّهِ ٱلۡمُخۡلَصِينَ¦37:75:1:وَلَقَدۡ نَادَىٰنَا نُوحࣱ فَلَنِعۡمَ\nT;0;37:75:2:ٱلۡمُجِيبُونَ¦37:76:3:وَنَجَّيۡنَٰهُ وَأَهۡلَهُۥ مِنَ ٱلۡكَرۡبِ ٱلۡعَظِيمِ',
  '23;45;2;180\nT;0;37:77:3:وَجَعَلۡنَا ذُرِّيَّتَهُۥ هُمُ ٱلۡبَاقِينَ¦37:78:3:وَتَرَكۡنَا عَلَيۡهِ فِي ٱلۡأٓخِرِينَ¦37:79:1:سَلَٰمٌ\nT;0;37:79:2:عَلَىٰ نُوحࣲ فِي ٱلۡعَٰلَمِينَ¦37:80:3:إِنَّا كَذَٰلِكَ نَجۡزِي ٱلۡمُحۡسِنِينَ¦37:81:1:إِنَّهُۥ\nT;0;37:81:2:مِنۡ عِبَادِنَا ٱلۡمُؤۡمِنِينَ¦37:82:3:ثُمَّ أَغۡرَقۡنَا ٱلۡأٓخَرِينَ¦37:83:1:۞ وَإِنَّ مِن\nT;0;37:83:2:شِيعَتِهِۦ لَإِبۡرَٰهِيمَ¦37:84:3:إِذۡ جَآءَ رَبَّهُۥ بِقَلۡبࣲ سَلِيمٍ¦37:85:1:إِذۡ قَالَ لِأَبِيهِ\nT;0;37:85:2:وَقَوۡمِهِۦ مَاذَا تَعۡبُدُونَ¦37:86:3:أَئِفۡكًا ءَالِهَةࣰ دُونَ ٱللَّهِ تُرِيدُونَ\nT;0;37:87:3:فَمَا ظَنُّكُم بِرَبِّ ٱلۡعَٰلَمِينَ¦37:88:3:فَنَظَرَ نَظۡرَةࣰ فِي ٱلنُّجُومِ\nT;0;37:89:3:فَقَالَ إِنِّي سَقِيمࣱ¦37:90:3:فَتَوَلَّوۡاْ عَنۡهُ مُدۡبِرِينَ¦37:91:1:فَرَاغَ إِلَىٰٓ ءَالِهَتِهِمۡ\nT;0;37:91:2:فَقَالَ أَلَا تَأۡكُلُونَ¦37:92:3:مَا لَكُمۡ لَا تَنطِقُونَ¦37:93:1:فَرَاغَ عَلَيۡهِمۡ ضَرۡبَۢا\nT;0;37:93:2:بِٱلۡيَمِينِ¦37:94:3:فَأَقۡبَلُوٓاْ إِلَيۡهِ يَزِفُّونَ¦37:95:3:قَالَ أَتَعۡبُدُونَ مَا تَنۡحِتُونَ\nT;0;37:96:3:وَٱللَّهُ خَلَقَكُمۡ وَمَا تَعۡمَلُونَ¦37:97:1:قَالُواْ ٱبۡنُواْ لَهُۥ بُنۡيَٰنࣰا فَأَلۡقُوهُ\nT;0;37:97:2:فِي ٱلۡجَحِيمِ¦37:98:3:فَأَرَادُواْ بِهِۦ كَيۡدࣰا فَجَعَلۡنَٰهُمُ ٱلۡأَسۡفَلِينَ\nT;0;37:99:3:وَقَالَ إِنِّي ذَاهِبٌ إِلَىٰ رَبِّي سَيَهۡدِينِ¦37:100:3:رَبِّ هَبۡ لِي مِنَ ٱلصَّٰلِحِينَ\nT;0;37:101:3:فَبَشَّرۡنَٰهُ بِغُلَٰمٍ حَلِيمࣲ¦37:102:1:فَلَمَّا بَلَغَ مَعَهُ ٱلسَّعۡيَ قَالَ يَٰبُنَيَّ\nT;0;37:102:0:إِنِّيٓ أَرَىٰ فِي ٱلۡمَنَامِ أَنِّيٓ أَذۡبَحُكَ فَٱنظُرۡ مَاذَا تَرَىٰۚ قَالَ يَٰٓأَبَتِ\nT;0;37:102:2:ٱفۡعَلۡ مَا تُؤۡمَرُۖ سَتَجِدُنِيٓ إِن شَآءَ ٱللَّهُ مِنَ ٱلصَّٰبِرِينَ',
  '23;45;3;\nT;0;37:103:3:فَلَمَّآ أَسۡلَمَا وَتَلَّهُۥ لِلۡجَبِينِ¦37:104:3:وَنَٰدَيۡنَٰهُ أَن يَٰٓإِبۡرَٰهِيمُ\nT;0;37:105:3:قَدۡ صَدَّقۡتَ ٱلرُّءۡيَآۚ إِنَّا كَذَٰلِكَ نَجۡزِي ٱلۡمُحۡسِنِينَ¦37:106:1:إِنَّ\nT;0;37:106:2:هَٰذَا لَهُوَ ٱلۡبَلَٰٓؤُاْ ٱلۡمُبِينُ¦37:107:3:وَفَدَيۡنَٰهُ بِذِبۡحٍ عَظِيمࣲ¦37:108:1:وَتَرَكۡنَا\nT;0;37:108:2:عَلَيۡهِ فِي ٱلۡأٓخِرِينَ¦37:109:3:سَلَٰمٌ عَلَىٰٓ إِبۡرَٰهِيمَ¦37:110:1:كَذَٰلِكَ نَجۡزِي\nT;0;37:110:2:ٱلۡمُحۡسِنِينَ¦37:111:3:إِنَّهُۥ مِنۡ عِبَادِنَا ٱلۡمُؤۡمِنِينَ¦37:112:1:وَبَشَّرۡنَٰهُ\nT;0;37:112:2:بِإِسۡحَٰقَ نَبِيࣰّا مِّنَ ٱلصَّٰلِحِينَ¦37:113:1:وَبَٰرَكۡنَا عَلَيۡهِ وَعَلَىٰٓ إِسۡحَٰقَۚ\nT;0;37:113:2:وَمِن ذُرِّيَّتِهِمَا مُحۡسِنࣱ وَظَالِمࣱ لِّنَفۡسِهِۦ مُبِينࣱ¦37:114:1:وَلَقَدۡ مَنَنَّا\nT;0;37:114:2:عَلَىٰ مُوسَىٰ وَهَٰرُونَ¦37:115:1:وَنَجَّيۡنَٰهُمَا وَقَوۡمَهُمَا مِنَ ٱلۡكَرۡبِ\nT;0;37:115:2:ٱلۡعَظِيمِ¦37:116:3:وَنَصَرۡنَٰهُمۡ فَكَانُواْ هُمُ ٱلۡغَٰلِبِينَ¦37:117:1:وَءَاتَيۡنَٰهُمَا\nT;0;37:117:2:ٱلۡكِتَٰبَ ٱلۡمُسۡتَبِينَ¦37:118:3:وَهَدَيۡنَٰهُمَا ٱلصِّرَٰطَ ٱلۡمُسۡتَقِيمَ\nT;0;37:119:3:وَتَرَكۡنَا عَلَيۡهِمَا فِي ٱلۡأٓخِرِينَ¦37:120:1:سَلَٰمٌ عَلَىٰ مُوسَىٰ\nT;0;37:120:2:وَهَٰرُونَ¦37:121:3:إِنَّا كَذَٰلِكَ نَجۡزِي ٱلۡمُحۡسِنِينَ¦37:122:1:إِنَّهُمَا\nT;0;37:122:2:مِنۡ عِبَادِنَا ٱلۡمُؤۡمِنِينَ¦37:123:3:وَإِنَّ إِلۡيَاسَ لَمِنَ ٱلۡمُرۡسَلِينَ\nT;0;37:124:3:إِذۡ قَالَ لِقَوۡمِهِۦٓ أَلَا تَتَّقُونَ¦37:125:1:أَتَدۡعُونَ بَعۡلࣰا وَتَذَرُونَ أَحۡسَنَ\nT;0;37:125:2:ٱلۡخَٰلِقِينَ¦37:126:3:ٱللَّهَ رَبَّكُمۡ وَرَبَّ ءَابَآئِكُمُ ٱلۡأَوَّلِينَ',
  '23;45;3;181\nT;0;37:127:3:فَكَذَّبُوهُ فَإِنَّهُمۡ لَمُحۡضَرُونَ¦37:128:3:إِلَّا عِبَادَ ٱللَّهِ ٱلۡمُخۡلَصِينَ\nT;0;37:129:3:وَتَرَكۡنَا عَلَيۡهِ فِي ٱلۡأٓخِرِينَ¦37:130:3:سَلَٰمٌ عَلَىٰٓ إِلۡ يَاسِينَ¦37:131:1:إِنَّا\nT;0;37:131:2:كَذَٰلِكَ نَجۡزِي ٱلۡمُحۡسِنِينَ¦37:132:3:إِنَّهُۥ مِنۡ عِبَادِنَا ٱلۡمُؤۡمِنِينَ\nT;0;37:133:3:وَإِنَّ لُوطࣰا لَّمِنَ ٱلۡمُرۡسَلِينَ¦37:134:3:إِذۡ نَجَّيۡنَٰهُ وَأَهۡلَهُۥٓ أَجۡمَعِينَ\nT;0;37:135:3:إِلَّا عَجُوزࣰا فِي ٱلۡغَٰبِرِينَ¦37:136:3:ثُمَّ دَمَّرۡنَا ٱلۡأٓخَرِينَ¦37:137:1:وَإِنَّكُمۡ\nT;0;37:137:2:لَتَمُرُّونَ عَلَيۡهِم مُّصۡبِحِينَ¦37:138:3:وَبِٱلَّيۡلِۚ أَفَلَا تَعۡقِلُونَ¦37:139:1:وَإِنَّ\nT;0;37:139:2:يُونُسَ لَمِنَ ٱلۡمُرۡسَلِينَ¦37:140:3:إِذۡ أَبَقَ إِلَى ٱلۡفُلۡكِ ٱلۡمَشۡحُونِ\nT;0;37:141:3:فَسَاهَمَ فَكَانَ مِنَ ٱلۡمُدۡحَضِينَ¦37:142:3:فَٱلۡتَقَمَهُ ٱلۡحُوتُ وَهُوَ مُلِيمࣱ\nT;0;37:143:3:فَلَوۡلَآ أَنَّهُۥ كَانَ مِنَ ٱلۡمُسَبِّحِينَ¦37:144:1:لَلَبِثَ فِي بَطۡنِهِۦٓ إِلَىٰ يَوۡمِ\nT;0;37:144:2:يُبۡعَثُونَ¦37:145:3:۞ فَنَبَذۡنَٰهُ بِٱلۡعَرَآءِ وَهُوَ سَقِيمࣱ¦37:146:1:وَأَنۢبَتۡنَا\nT;0;37:146:2:عَلَيۡهِ شَجَرَةࣰ مِّن يَقۡطِينࣲ¦37:147:1:وَأَرۡسَلۡنَٰهُ إِلَىٰ مِاْئَةِ أَلۡفٍ أَوۡ\nT;0;37:147:2:يَزِيدُونَ¦37:148:3:فَـَٔامَنُواْ فَمَتَّعۡنَٰهُمۡ إِلَىٰ حِينࣲ¦37:149:1:فَٱسۡتَفۡتِهِمۡ\nT;0;37:149:2:أَلِرَبِّكَ ٱلۡبَنَاتُ وَلَهُمُ ٱلۡبَنُونَ¦37:150:1:أَمۡ خَلَقۡنَا ٱلۡمَلَٰٓئِكَةَ إِنَٰثࣰا\nT;0;37:150:2:وَهُمۡ شَٰهِدُونَ¦37:151:3:أَلَآ إِنَّهُم مِّنۡ إِفۡكِهِمۡ لَيَقُولُونَ¦37:152:1:وَلَدَ\nT;0;37:152:2:ٱللَّهُ وَإِنَّهُمۡ لَكَٰذِبُونَ¦37:153:3:أَصۡطَفَى ٱلۡبَنَاتِ عَلَى ٱلۡبَنِينَ',
  '23;46;0;\nT;0;37:154:3:مَا لَكُمۡ كَيۡفَ تَحۡكُمُونَ¦37:155:3:أَفَلَا تَذَكَّرُونَ¦37:156:1:أَمۡ لَكُمۡ سُلۡطَٰنࣱ\nT;0;37:156:2:مُّبِينࣱ¦37:157:3:فَأۡتُواْ بِكِتَٰبِكُمۡ إِن كُنتُمۡ صَٰدِقِينَ¦37:158:1:وَجَعَلُواْ بَيۡنَهُۥ\nT;0;37:158:2:وَبَيۡنَ ٱلۡجِنَّةِ نَسَبࣰاۚ وَلَقَدۡ عَلِمَتِ ٱلۡجِنَّةُ إِنَّهُمۡ لَمُحۡضَرُونَ\nT;0;37:159:3:سُبۡحَٰنَ ٱللَّهِ عَمَّا يَصِفُونَ¦37:160:3:إِلَّا عِبَادَ ٱللَّهِ ٱلۡمُخۡلَصِينَ\nT;0;37:161:3:فَإِنَّكُمۡ وَمَا تَعۡبُدُونَ¦37:162:3:مَآ أَنتُمۡ عَلَيۡهِ بِفَٰتِنِينَ\nT;0;37:163:3:إِلَّا مَنۡ هُوَ صَالِ ٱلۡجَحِيمِ¦37:164:3:وَمَا مِنَّآ إِلَّا لَهُۥ مَقَامࣱ مَّعۡلُومࣱ\nT;0;37:165:3:وَإِنَّا لَنَحۡنُ ٱلصَّآفُّونَ¦37:166:3:وَإِنَّا لَنَحۡنُ ٱلۡمُسَبِّحُونَ\nT;0;37:167:3:وَإِن كَانُواْ لَيَقُولُونَ¦37:168:3:لَوۡ أَنَّ عِندَنَا ذِكۡرࣰا مِّنَ ٱلۡأَوَّلِينَ\nT;0;37:169:3:لَكُنَّا عِبَادَ ٱللَّهِ ٱلۡمُخۡلَصِينَ¦37:170:3:فَكَفَرُواْ بِهِۦۖ فَسَوۡفَ يَعۡلَمُونَ¦37:171:1:وَلَقَدۡ\nT;0;37:171:2:سَبَقَتۡ كَلِمَتُنَا لِعِبَادِنَا ٱلۡمُرۡسَلِينَ¦37:172:3:إِنَّهُمۡ لَهُمُ ٱلۡمَنصُورُونَ\nT;0;37:173:3:وَإِنَّ جُندَنَا لَهُمُ ٱلۡغَٰلِبُونَ¦37:174:3:فَتَوَلَّ عَنۡهُمۡ حَتَّىٰ حِينࣲ¦37:175:1:وَأَبۡصِرۡهُمۡ\nT;0;37:175:2:فَسَوۡفَ يُبۡصِرُونَ¦37:176:3:أَفَبِعَذَابِنَا يَسۡتَعۡجِلُونَ¦37:177:1:فَإِذَا نَزَلَ بِسَاحَتِهِمۡ\nT;0;37:177:2:فَسَآءَ صَبَاحُ ٱلۡمُنذَرِينَ¦37:178:3:وَتَوَلَّ عَنۡهُمۡ حَتَّىٰ حِينࣲ¦37:179:1:وَأَبۡصِرۡ\nT;0;37:179:2:فَسَوۡفَ يُبۡصِرُونَ¦37:180:3:سُبۡحَٰنَ رَبِّكَ رَبِّ ٱلۡعِزَّةِ عَمَّا يَصِفُونَ\nT;2;37:181:3:وَسَلَٰمٌ عَلَى ٱلۡمُرۡسَلِينَ¦37:182:3:وَٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ',
  '23;46;0;\nH;38\nB;38\nT;0;38:1:3:صٓۚ وَٱلۡقُرۡءَانِ ذِي ٱلذِّكۡرِ¦38:2:3:بَلِ ٱلَّذِينَ كَفَرُواْ فِي عِزَّةࣲ وَشِقَاقࣲ\nT;0;38:3:3:كَمۡ أَهۡلَكۡنَا مِن قَبۡلِهِم مِّن قَرۡنࣲ فَنَادَواْ وَّلَاتَ حِينَ مَنَاصࣲ¦38:4:1:وَعَجِبُوٓاْ\nT;0;38:4:2:أَن جَآءَهُم مُّنذِرࣱ مِّنۡهُمۡۖ وَقَالَ ٱلۡكَٰفِرُونَ هَٰذَا سَٰحِرࣱ كَذَّابٌ¦38:5:1:أَجَعَلَ\nT;0;38:5:2:ٱلۡأٓلِهَةَ إِلَٰهࣰا وَٰحِدًاۖ إِنَّ هَٰذَا لَشَيۡءٌ عُجَابࣱ¦38:6:1:وَٱنطَلَقَ ٱلۡمَلَأُ مِنۡهُمۡ أَنِ\nT;0;38:6:2:ٱمۡشُواْ وَٱصۡبِرُواْ عَلَىٰٓ ءَالِهَتِكُمۡۖ إِنَّ هَٰذَا لَشَيۡءࣱ يُرَادُ¦38:7:1:مَا سَمِعۡنَا\nT;0;38:7:2:بِهَٰذَا فِي ٱلۡمِلَّةِ ٱلۡأٓخِرَةِ إِنۡ هَٰذَآ إِلَّا ٱخۡتِلَٰقٌ¦38:8:1:أَءُنزِلَ عَلَيۡهِ ٱلذِّكۡرُ\nT;0;38:8:2:مِنۢ بَيۡنِنَاۚ بَلۡ هُمۡ فِي شَكࣲّ مِّن ذِكۡرِيۚ بَل لَّمَّا يَذُوقُواْ عَذَابِ¦38:9:1:أَمۡ عِندَهُمۡ\nT;0;38:9:2:خَزَآئِنُ رَحۡمَةِ رَبِّكَ ٱلۡعَزِيزِ ٱلۡوَهَّابِ¦38:10:1:أَمۡ لَهُم مُّلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ\nT;0;38:10:2:وَمَا بَيۡنَهُمَاۖ فَلۡيَرۡتَقُواْ فِي ٱلۡأَسۡبَٰبِ¦38:11:1:جُندࣱ مَّا هُنَالِكَ مَهۡزُومࣱ مِّنَ\nT;0;38:11:2:ٱلۡأَحۡزَابِ¦38:12:3:كَذَّبَتۡ قَبۡلَهُمۡ قَوۡمُ نُوحࣲ وَعَادࣱ وَفِرۡعَوۡنُ ذُو ٱلۡأَوۡتَادِ\nT;0;38:13:3:وَثَمُودُ وَقَوۡمُ لُوطࣲ وَأَصۡحَٰبُ لۡـَٔيۡكَةِۚ أُوْلَٰٓئِكَ ٱلۡأَحۡزَابُ¦38:14:1:إِن كُلٌّ إِلَّا\nT;0;38:14:2:كَذَّبَ ٱلرُّسُلَ فَحَقَّ عِقَابِ¦38:15:1:وَمَا يَنظُرُ هَٰٓؤُلَآءِ إِلَّا صَيۡحَةࣰ وَٰحِدَةࣰ\nT;0;38:15:2:مَّا لَهَا مِن فَوَاقࣲ¦38:16:3:وَقَالُواْ رَبَّنَا عَجِّل لَّنَا قِطَّنَا قَبۡلَ يَوۡمِ ٱلۡحِسَابِ',
  '23;46;0;182\nT;0;38:17:3:ٱصۡبِرۡ عَلَىٰ مَا يَقُولُونَ وَٱذۡكُرۡ عَبۡدَنَا دَاوُۥدَ ذَا ٱلۡأَيۡدِۖ إِنَّهُۥٓ أَوَّابٌ¦38:18:1:إِنَّا\nT;0;38:18:2:سَخَّرۡنَا ٱلۡجِبَالَ مَعَهُۥ يُسَبِّحۡنَ بِٱلۡعَشِيِّ وَٱلۡإِشۡرَاقِ¦38:19:1:وَٱلطَّيۡرَ\nT;0;38:19:2:مَحۡشُورَةࣰۖ كُلࣱّ لَّهُۥٓ أَوَّابࣱ¦38:20:1:وَشَدَدۡنَا مُلۡكَهُۥ وَءَاتَيۡنَٰهُ ٱلۡحِكۡمَةَ\nT;0;38:20:2:وَفَصۡلَ ٱلۡخِطَابِ¦38:21:1:۞ وَهَلۡ أَتَىٰكَ نَبَؤُاْ ٱلۡخَصۡمِ إِذۡ تَسَوَّرُواْ\nT;0;38:21:2:ٱلۡمِحۡرَابَ¦38:22:1:إِذۡ دَخَلُواْ عَلَىٰ دَاوُۥدَ فَفَزِعَ مِنۡهُمۡۖ قَالُواْ لَا تَخَفۡۖ\nT;0;38:22:0:خَصۡمَانِ بَغَىٰ بَعۡضُنَا عَلَىٰ بَعۡضࣲ فَٱحۡكُم بَيۡنَنَا بِٱلۡحَقِّ وَلَا تُشۡطِطۡ\nT;0;38:22:2:وَٱهۡدِنَآ إِلَىٰ سَوَآءِ ٱلصِّرَٰطِ¦38:23:1:إِنَّ هَٰذَآ أَخِي لَهُۥ تِسۡعࣱ وَتِسۡعُونَ نَعۡجَةࣰ\nT;0;38:23:2:وَلِيَ نَعۡجَةࣱ وَٰحِدَةࣱ فَقَالَ أَكۡفِلۡنِيهَا وَعَزَّنِي فِي ٱلۡخِطَابِ¦38:24:1:قَالَ\nT;0;38:24:0:لَقَدۡ ظَلَمَكَ بِسُؤَالِ نَعۡجَتِكَ إِلَىٰ نِعَاجِهِۦۖ وَإِنَّ كَثِيرࣰا مِّنَ ٱلۡخُلَطَآءِ لَيَبۡغِي\nT;0;38:24:0:بَعۡضُهُمۡ عَلَىٰ بَعۡضٍ إِلَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ وَقَلِيلࣱ مَّا هُمۡۗ\nT;0;38:24:2:وَظَنَّ دَاوُۥدُ أَنَّمَا فَتَنَّٰهُ فَٱسۡتَغۡفَرَ رَبَّهُۥ وَخَرَّۤ رَاكِعࣰاۤ وَأَنَابَ۩\nT;0;38:25:3:فَغَفَرۡنَا لَهُۥ ذَٰلِكَۖ وَإِنَّ لَهُۥ عِندَنَا لَزُلۡفَىٰ وَحُسۡنَ مَـَٔابࣲ\nT;0;38:26:1:يَٰدَاوُۥدُ إِنَّا جَعَلۡنَٰكَ خَلِيفَةࣰ فِي ٱلۡأَرۡضِ فَٱحۡكُم بَيۡنَ ٱلنَّاسِ بِٱلۡحَقِّ\nT;0;38:26:0:وَلَا تَتَّبِعِ ٱلۡهَوَىٰ فَيُضِلَّكَ عَن سَبِيلِ ٱللَّهِۚ إِنَّ ٱلَّذِينَ يَضِلُّونَ\nT;0;38:26:2:عَن سَبِيلِ ٱللَّهِ لَهُمۡ عَذَابࣱ شَدِيدُۢ بِمَا نَسُواْ يَوۡمَ ٱلۡحِسَابِ',
  '23;46;1;\nT;0;38:27:1:وَمَا خَلَقۡنَا ٱلسَّمَآءَ وَٱلۡأَرۡضَ وَمَا بَيۡنَهُمَا بَٰطِلࣰاۚ ذَٰلِكَ ظَنُّ ٱلَّذِينَ\nT;0;38:27:2:كَفَرُواْۚ فَوَيۡلࣱ لِّلَّذِينَ كَفَرُواْ مِنَ ٱلنَّارِ¦38:28:1:أَمۡ نَجۡعَلُ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ\nT;0;38:28:2:ٱلصَّٰلِحَٰتِ كَٱلۡمُفۡسِدِينَ فِي ٱلۡأَرۡضِ أَمۡ نَجۡعَلُ ٱلۡمُتَّقِينَ كَٱلۡفُجَّارِ\nT;0;38:29:1:كِتَٰبٌ أَنزَلۡنَٰهُ إِلَيۡكَ مُبَٰرَكࣱ لِّيَدَّبَّرُوٓاْ ءَايَٰتِهِۦ وَلِيَتَذَكَّرَ أُوْلُواْ\nT;0;38:29:2:ٱلۡأَلۡبَٰبِ¦38:30:3:وَوَهَبۡنَا لِدَاوُۥدَ سُلَيۡمَٰنَۚ نِعۡمَ ٱلۡعَبۡدُ إِنَّهُۥٓ أَوَّابٌ\nT;0;38:31:3:إِذۡ عُرِضَ عَلَيۡهِ بِٱلۡعَشِيِّ ٱلصَّٰفِنَٰتُ ٱلۡجِيَادُ¦38:32:1:فَقَالَ إِنِّيٓ أَحۡبَبۡتُ\nT;0;38:32:2:حُبَّ ٱلۡخَيۡرِ عَن ذِكۡرِ رَبِّي حَتَّىٰ تَوَارَتۡ بِٱلۡحِجَابِ¦38:33:1:رُدُّوهَا عَلَيَّۖ\nT;0;38:33:2:فَطَفِقَ مَسۡحَۢا بِٱلسُّوقِ وَٱلۡأَعۡنَاقِ¦38:34:1:وَلَقَدۡ فَتَنَّا سُلَيۡمَٰنَ\nT;0;38:34:2:وَأَلۡقَيۡنَا عَلَىٰ كُرۡسِيِّهِۦ جَسَدࣰا ثُمَّ أَنَابَ¦38:35:1:قَالَ رَبِّ ٱغۡفِرۡ لِي وَهَبۡ\nT;0;38:35:2:لِي مُلۡكࣰا لَّا يَنۢبَغِي لِأَحَدࣲ مِّنۢ بَعۡدِيٓۖ إِنَّكَ أَنتَ ٱلۡوَهَّابُ\nT;0;38:36:3:فَسَخَّرۡنَا لَهُ ٱلرِّيحَ تَجۡرِي بِأَمۡرِهِۦ رُخَآءً حَيۡثُ أَصَابَ¦38:37:1:وَٱلشَّيَٰطِينَ\nT;0;38:37:2:كُلَّ بَنَّآءࣲ وَغَوَّاصࣲ¦38:38:3:وَءَاخَرِينَ مُقَرَّنِينَ فِي ٱلۡأَصۡفَادِ¦38:39:1:هَٰذَا\nT;0;38:39:2:عَطَآؤُنَا فَٱمۡنُنۡ أَوۡ أَمۡسِكۡ بِغَيۡرِ حِسَابࣲ¦38:40:1:وَإِنَّ لَهُۥ عِندَنَا لَزُلۡفَىٰ وَحُسۡنَ\nT;0;38:40:2:مَـَٔابࣲ¦38:41:1:وَٱذۡكُرۡ عَبۡدَنَآ أَيُّوبَ إِذۡ نَادَىٰ رَبَّهُۥٓ أَنِّي مَسَّنِيَ ٱلشَّيۡطَٰنُ\nT;0;38:41:2:بِنُصۡبࣲ وَعَذَابٍ¦38:42:3:ٱرۡكُضۡ بِرِجۡلِكَۖ هَٰذَا مُغۡتَسَلُۢ بَارِدࣱ وَشَرَابࣱ',
  '23;46;1;183\nT;0;38:43:3:وَوَهَبۡنَا لَهُۥٓ أَهۡلَهُۥ وَمِثۡلَهُم مَّعَهُمۡ رَحۡمَةࣰ مِّنَّا وَذِكۡرَىٰ لِأُوْلِي ٱلۡأَلۡبَٰبِ\nT;0;38:44:1:وَخُذۡ بِيَدِكَ ضِغۡثࣰا فَٱضۡرِب بِّهِۦ وَلَا تَحۡنَثۡۗ إِنَّا وَجَدۡنَٰهُ صَابِرࣰاۚ نِّعۡمَ\nT;0;38:44:2:ٱلۡعَبۡدُ إِنَّهُۥٓ أَوَّابࣱ¦38:45:1:وَٱذۡكُرۡ عِبَٰدَنَآ إِبۡرَٰهِيمَ وَإِسۡحَٰقَ وَيَعۡقُوبَ أُوْلِي\nT;0;38:45:2:ٱلۡأَيۡدِي وَٱلۡأَبۡصَٰرِ¦38:46:3:إِنَّآ أَخۡلَصۡنَٰهُم بِخَالِصَةࣲ ذِكۡرَى ٱلدَّارِ\nT;0;38:47:3:وَإِنَّهُمۡ عِندَنَا لَمِنَ ٱلۡمُصۡطَفَيۡنَ ٱلۡأَخۡيَارِ¦38:48:1:وَٱذۡكُرۡ إِسۡمَٰعِيلَ\nT;0;38:48:2:وَٱلۡيَسَعَ وَذَا ٱلۡكِفۡلِۖ وَكُلࣱّ مِّنَ ٱلۡأَخۡيَارِ¦38:49:1:هَٰذَا ذِكۡرࣱۚ وَإِنَّ لِلۡمُتَّقِينَ\nT;0;38:49:2:لَحُسۡنَ مَـَٔابࣲ¦38:50:3:جَنَّٰتِ عَدۡنࣲ مُّفَتَّحَةࣰ لَّهُمُ ٱلۡأَبۡوَٰبُ¦38:51:1:مُتَّكِـِٔينَ\nT;0;38:51:2:فِيهَا يَدۡعُونَ فِيهَا بِفَٰكِهَةࣲ كَثِيرَةࣲ وَشَرَابࣲ¦38:52:1:۞ وَعِندَهُمۡ قَٰصِرَٰتُ\nT;0;38:52:2:ٱلطَّرۡفِ أَتۡرَابٌ¦38:53:3:هَٰذَا مَا تُوعَدُونَ لِيَوۡمِ ٱلۡحِسَابِ¦38:54:1:إِنَّ هَٰذَا\nT;0;38:54:2:لَرِزۡقُنَا مَا لَهُۥ مِن نَّفَادٍ¦38:55:3:هَٰذَاۚ وَإِنَّ لِلطَّٰغِينَ لَشَرَّ مَـَٔابࣲ\nT;0;38:56:3:جَهَنَّمَ يَصۡلَوۡنَهَا فَبِئۡسَ ٱلۡمِهَادُ¦38:57:1:هَٰذَا فَلۡيَذُوقُوهُ حَمِيمࣱ\nT;0;38:57:2:وَغَسَّاقࣱ¦38:58:3:وَءَاخَرُ مِن شَكۡلِهِۦٓ أَزۡوَٰجٌ¦38:59:1:هَٰذَا فَوۡجࣱ\nT;0;38:59:2:مُّقۡتَحِمࣱ مَّعَكُمۡ لَا مَرۡحَبَۢا بِهِمۡۚ إِنَّهُمۡ صَالُواْ ٱلنَّارِ¦38:60:1:قَالُواْ\nT;0;38:60:2:بَلۡ أَنتُمۡ لَا مَرۡحَبَۢا بِكُمۡۖ أَنتُمۡ قَدَّمۡتُمُوهُ لَنَاۖ فَبِئۡسَ ٱلۡقَرَارُ\nT;0;38:61:3:قَالُواْ رَبَّنَا مَن قَدَّمَ لَنَا هَٰذَا فَزِدۡهُ عَذَابࣰا ضِعۡفࣰا فِي ٱلنَّارِ',
  '23;46;2;\nT;0;38:62:3:وَقَالُواْ مَا لَنَا لَا نَرَىٰ رِجَالࣰا كُنَّا نَعُدُّهُم مِّنَ ٱلۡأَشۡرَارِ¦38:63:1:أَتَّخَذۡنَٰهُمۡ\nT;0;38:63:2:سِخۡرِيًّا أَمۡ زَاغَتۡ عَنۡهُمُ ٱلۡأَبۡصَٰرُ¦38:64:1:إِنَّ ذَٰلِكَ لَحَقࣱّ تَخَاصُمُ أَهۡلِ\nT;0;38:64:2:ٱلنَّارِ¦38:65:3:قُلۡ إِنَّمَآ أَنَا۠ مُنذِرࣱۖ وَمَا مِنۡ إِلَٰهٍ إِلَّا ٱللَّهُ ٱلۡوَٰحِدُ ٱلۡقَهَّارُ\nT;0;38:66:3:رَبُّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا بَيۡنَهُمَا ٱلۡعَزِيزُ ٱلۡغَفَّٰرُ¦38:67:1:قُلۡ هُوَ نَبَؤٌاْ\nT;0;38:67:2:عَظِيمٌ¦38:68:3:أَنتُمۡ عَنۡهُ مُعۡرِضُونَ¦38:69:1:مَا كَانَ لِيَ مِنۡ عِلۡمِۭ بِٱلۡمَلَإِ ٱلۡأَعۡلَىٰٓ\nT;0;38:69:2:إِذۡ يَخۡتَصِمُونَ¦38:70:3:إِن يُوحَىٰٓ إِلَيَّ إِلَّآ أَنَّمَآ أَنَا۠ نَذِيرࣱ مُّبِينٌ¦38:71:1:إِذۡ قَالَ\nT;0;38:71:2:رَبُّكَ لِلۡمَلَٰٓئِكَةِ إِنِّي خَٰلِقُۢ بَشَرࣰا مِّن طِينࣲ¦38:72:1:فَإِذَا سَوَّيۡتُهُۥ وَنَفَخۡتُ\nT;0;38:72:2:فِيهِ مِن رُّوحِي فَقَعُواْ لَهُۥ سَٰجِدِينَ¦38:73:1:فَسَجَدَ ٱلۡمَلَٰٓئِكَةُ كُلُّهُمۡ\nT;0;38:73:2:أَجۡمَعُونَ¦38:74:3:إِلَّآ إِبۡلِيسَ ٱسۡتَكۡبَرَ وَكَانَ مِنَ ٱلۡكَٰفِرِينَ¦38:75:1:قَالَ\nT;0;38:75:0:يَٰٓإِبۡلِيسُ مَا مَنَعَكَ أَن تَسۡجُدَ لِمَا خَلَقۡتُ بِيَدَيَّۖ أَسۡتَكۡبَرۡتَ أَمۡ كُنتَ\nT;0;38:75:2:مِنَ ٱلۡعَالِينَ¦38:76:1:قَالَ أَنَا۠ خَيۡرࣱ مِّنۡهُ خَلَقۡتَنِي مِن نَّارࣲ وَخَلَقۡتَهُۥ مِن\nT;0;38:76:2:طِينࣲ¦38:77:3:قَالَ فَٱخۡرُجۡ مِنۡهَا فَإِنَّكَ رَجِيمࣱ¦38:78:1:وَإِنَّ عَلَيۡكَ لَعۡنَتِيٓ إِلَىٰ يَوۡمِ\nT;0;38:78:2:ٱلدِّينِ¦38:79:3:قَالَ رَبِّ فَأَنظِرۡنِيٓ إِلَىٰ يَوۡمِ يُبۡعَثُونَ¦38:80:1:قَالَ فَإِنَّكَ مِنَ\nT;0;38:80:2:ٱلۡمُنظَرِينَ¦38:81:3:إِلَىٰ يَوۡمِ ٱلۡوَقۡتِ ٱلۡمَعۡلُومِ¦38:82:1:قَالَ فَبِعِزَّتِكَ\nT;0;38:82:2:لَأُغۡوِيَنَّهُمۡ أَجۡمَعِينَ¦38:83:3:إِلَّا عِبَادَكَ مِنۡهُمُ ٱلۡمُخۡلَصِينَ',
  '23;46;2;\nT;0;38:84:3:قَالَ فَٱلۡحَقُّ وَٱلۡحَقَّ أَقُولُ¦38:85:1:لَأَمۡلَأَنَّ جَهَنَّمَ مِنكَ وَمِمَّن تَبِعَكَ مِنۡهُمۡ\nT;0;38:85:2:أَجۡمَعِينَ¦38:86:3:قُلۡ مَآ أَسۡـَٔلُكُمۡ عَلَيۡهِ مِنۡ أَجۡرࣲ وَمَآ أَنَا۠ مِنَ ٱلۡمُتَكَلِّفِينَ\nT;2;38:87:3:إِنۡ هُوَ إِلَّا ذِكۡرࣱ لِّلۡعَٰلَمِينَ¦38:88:3:وَلَتَعۡلَمُنَّ نَبَأَهُۥ بَعۡدَ حِينِۭ\nH;39\nB;39\nT;0;39:1:3:تَنزِيلُ ٱلۡكِتَٰبِ مِنَ ٱللَّهِ ٱلۡعَزِيزِ ٱلۡحَكِيمِ¦39:2:1:إِنَّآ أَنزَلۡنَآ إِلَيۡكَ\nT;0;39:2:2:ٱلۡكِتَٰبَ بِٱلۡحَقِّ فَٱعۡبُدِ ٱللَّهَ مُخۡلِصࣰا لَّهُ ٱلدِّينَ¦39:3:1:أَلَا\nT;0;39:3:0:لِلَّهِ ٱلدِّينُ ٱلۡخَالِصُۚ وَٱلَّذِينَ ٱتَّخَذُواْ مِن دُونِهِۦٓ أَوۡلِيَآءَ\nT;0;39:3:0:مَا نَعۡبُدُهُمۡ إِلَّا لِيُقَرِّبُونَآ إِلَى ٱللَّهِ زُلۡفَىٰٓ إِنَّ ٱللَّهَ يَحۡكُمُ\nT;0;39:3:0:بَيۡنَهُمۡ فِي مَا هُمۡ فِيهِ يَخۡتَلِفُونَۗ إِنَّ ٱللَّهَ لَا يَهۡدِي مَنۡ هُوَ\nT;0;39:3:2:كَٰذِبࣱ كَفَّارࣱ¦39:4:1:لَّوۡ أَرَادَ ٱللَّهُ أَن يَتَّخِذَ وَلَدࣰا لَّٱصۡطَفَىٰ\nT;0;39:4:2:مِمَّا يَخۡلُقُ مَا يَشَآءُۚ سُبۡحَٰنَهُۥۖ هُوَ ٱللَّهُ ٱلۡوَٰحِدُ ٱلۡقَهَّارُ\nT;0;39:5:1:خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ بِٱلۡحَقِّۖ يُكَوِّرُ ٱلَّيۡلَ عَلَى\nT;0;39:5:0:ٱلنَّهَارِ وَيُكَوِّرُ ٱلنَّهَارَ عَلَى ٱلَّيۡلِۖ وَسَخَّرَ ٱلشَّمۡسَ وَٱلۡقَمَرَۖ\nT;0;39:5:2:كُلࣱّ يَجۡرِي لِأَجَلࣲ مُّسَمًّىۗ أَلَا هُوَ ٱلۡعَزِيزُ ٱلۡغَفَّٰرُ',
  '23;46;2;184\nT;0;39:6:1:خَلَقَكُم مِّن نَّفۡسࣲ وَٰحِدَةࣲ ثُمَّ جَعَلَ مِنۡهَا زَوۡجَهَا وَأَنزَلَ لَكُم\nT;0;39:6:0:مِّنَ ٱلۡأَنۡعَٰمِ ثَمَٰنِيَةَ أَزۡوَٰجࣲۚ يَخۡلُقُكُمۡ فِي بُطُونِ أُمَّهَٰتِكُمۡ\nT;0;39:6:0:خَلۡقࣰا مِّنۢ بَعۡدِ خَلۡقࣲ فِي ظُلُمَٰتࣲ ثَلَٰثࣲۚ ذَٰلِكُمُ ٱللَّهُ رَبُّكُمۡ لَهُ\nT;0;39:6:2:ٱلۡمُلۡكُۖ لَآ إِلَٰهَ إِلَّا هُوَۖ فَأَنَّىٰ تُصۡرَفُونَ¦39:7:1:إِن تَكۡفُرُواْ فَإِنَّ\nT;0;39:7:0:ٱللَّهَ غَنِيٌّ عَنكُمۡۖ وَلَا يَرۡضَىٰ لِعِبَادِهِ ٱلۡكُفۡرَۖ وَإِن تَشۡكُرُواْ يَرۡضَهُ\nT;0;39:7:0:لَكُمۡۗ وَلَا تَزِرُ وَازِرَةࣱ وِزۡرَ أُخۡرَىٰۚ ثُمَّ إِلَىٰ رَبِّكُم مَّرۡجِعُكُمۡ\nT;0;39:7:2:فَيُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَۚ إِنَّهُۥ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ\nT;0;39:8:1:۞ وَإِذَا مَسَّ ٱلۡإِنسَٰنَ ضُرࣱّ دَعَا رَبَّهُۥ مُنِيبًا إِلَيۡهِ ثُمَّ إِذَا خَوَّلَهُۥ نِعۡمَةࣰ\nT;0;39:8:0:مِّنۡهُ نَسِيَ مَا كَانَ يَدۡعُوٓاْ إِلَيۡهِ مِن قَبۡلُ وَجَعَلَ لِلَّهِ أَندَادࣰا لِّيُضِلَّ\nT;0;39:8:2:عَن سَبِيلِهِۦۚ قُلۡ تَمَتَّعۡ بِكُفۡرِكَ قَلِيلًا إِنَّكَ مِنۡ أَصۡحَٰبِ ٱلنَّارِ\nT;0;39:9:1:أَمَّنۡ هُوَ قَٰنِتٌ ءَانَآءَ ٱلَّيۡلِ سَاجِدࣰا وَقَآئِمࣰا يَحۡذَرُ ٱلۡأٓخِرَةَ\nT;0;39:9:0:وَيَرۡجُواْ رَحۡمَةَ رَبِّهِۦۗ قُلۡ هَلۡ يَسۡتَوِي ٱلَّذِينَ يَعۡلَمُونَ وَٱلَّذِينَ\nT;0;39:9:2:لَا يَعۡلَمُونَۗ إِنَّمَا يَتَذَكَّرُ أُوْلُواْ ٱلۡأَلۡبَٰبِ¦39:10:1:قُلۡ يَٰعِبَادِ ٱلَّذِينَ\nT;0;39:10:0:ءَامَنُواْ ٱتَّقُواْ رَبَّكُمۡۚ لِلَّذِينَ أَحۡسَنُواْ فِي هَٰذِهِ ٱلدُّنۡيَا حَسَنَةࣱۗ\nT;0;39:10:2:وَأَرۡضُ ٱللَّهِ وَٰسِعَةٌۗ إِنَّمَا يُوَفَّى ٱلصَّٰبِرُونَ أَجۡرَهُم بِغَيۡرِ حِسَابࣲ',
  '23;46;3;\nT;0;39:11:3:قُلۡ إِنِّيٓ أُمِرۡتُ أَنۡ أَعۡبُدَ ٱللَّهَ مُخۡلِصࣰا لَّهُ ٱلدِّينَ¦39:12:1:وَأُمِرۡتُ لِأَنۡ أَكُونَ\nT;0;39:12:2:أَوَّلَ ٱلۡمُسۡلِمِينَ¦39:13:1:قُلۡ إِنِّيٓ أَخَافُ إِنۡ عَصَيۡتُ رَبِّي عَذَابَ يَوۡمٍ\nT;0;39:13:2:عَظِيمࣲ¦39:14:3:قُلِ ٱللَّهَ أَعۡبُدُ مُخۡلِصࣰا لَّهُۥ دِينِي¦39:15:1:فَٱعۡبُدُواْ مَا شِئۡتُم مِّن\nT;0;39:15:0:دُونِهِۦۗ قُلۡ إِنَّ ٱلۡخَٰسِرِينَ ٱلَّذِينَ خَسِرُوٓاْ أَنفُسَهُمۡ وَأَهۡلِيهِمۡ يَوۡمَ ٱلۡقِيَٰمَةِۗ\nT;0;39:15:2:أَلَا ذَٰلِكَ هُوَ ٱلۡخُسۡرَانُ ٱلۡمُبِينُ¦39:16:1:لَهُم مِّن فَوۡقِهِمۡ ظُلَلࣱ مِّنَ ٱلنَّارِ\nT;0;39:16:2:وَمِن تَحۡتِهِمۡ ظُلَلࣱۚ ذَٰلِكَ يُخَوِّفُ ٱللَّهُ بِهِۦ عِبَادَهُۥۚ يَٰعِبَادِ فَٱتَّقُونِ\nT;0;39:17:1:وَٱلَّذِينَ ٱجۡتَنَبُواْ ٱلطَّٰغُوتَ أَن يَعۡبُدُوهَا وَأَنَابُوٓاْ إِلَى ٱللَّهِ لَهُمُ ٱلۡبُشۡرَىٰۚ\nT;0;39:17:2:فَبَشِّرۡ عِبَادِ¦39:18:1:ٱلَّذِينَ يَسۡتَمِعُونَ ٱلۡقَوۡلَ فَيَتَّبِعُونَ أَحۡسَنَهُۥٓۚ\nT;0;39:18:2:أُوْلَٰٓئِكَ ٱلَّذِينَ هَدَىٰهُمُ ٱللَّهُۖ وَأُوْلَٰٓئِكَ هُمۡ أُوْلُواْ ٱلۡأَلۡبَٰبِ\nT;0;39:19:3:أَفَمَنۡ حَقَّ عَلَيۡهِ كَلِمَةُ ٱلۡعَذَابِ أَفَأَنتَ تُنقِذُ مَن فِي ٱلنَّارِ\nT;0;39:20:1:لَٰكِنِ ٱلَّذِينَ ٱتَّقَوۡاْ رَبَّهُمۡ لَهُمۡ غُرَفࣱ مِّن فَوۡقِهَا غُرَفࣱ مَّبۡنِيَّةࣱ تَجۡرِي\nT;0;39:20:2:مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُۖ وَعۡدَ ٱللَّهِ لَا يُخۡلِفُ ٱللَّهُ ٱلۡمِيعَادَ¦39:21:1:أَلَمۡ تَرَ\nT;0;39:21:0:أَنَّ ٱللَّهَ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءࣰ فَسَلَكَهُۥ يَنَٰبِيعَ فِي ٱلۡأَرۡضِ ثُمَّ\nT;0;39:21:0:يُخۡرِجُ بِهِۦ زَرۡعࣰا مُّخۡتَلِفًا أَلۡوَٰنُهُۥ ثُمَّ يَهِيجُ فَتَرَىٰهُ مُصۡفَرࣰّا ثُمَّ\nT;0;39:21:2:يَجۡعَلُهُۥ حُطَٰمًاۚ إِنَّ فِي ذَٰلِكَ لَذِكۡرَىٰ لِأُوْلِي ٱلۡأَلۡبَٰبِ',
  '23;46;3;\nT;0;39:22:1:أَفَمَن شَرَحَ ٱللَّهُ صَدۡرَهُۥ لِلۡإِسۡلَٰمِ فَهُوَ عَلَىٰ نُورࣲ مِّن رَّبِّهِۦۚ فَوَيۡلࣱ\nT;0;39:22:2:لِّلۡقَٰسِيَةِ قُلُوبُهُم مِّن ذِكۡرِ ٱللَّهِۚ أُوْلَٰٓئِكَ فِي ضَلَٰلࣲ مُّبِينٍ\nT;0;39:23:1:ٱللَّهُ نَزَّلَ أَحۡسَنَ ٱلۡحَدِيثِ كِتَٰبࣰا مُّتَشَٰبِهࣰا مَّثَانِيَ تَقۡشَعِرُّ مِنۡهُ\nT;0;39:23:0:جُلُودُ ٱلَّذِينَ يَخۡشَوۡنَ رَبَّهُمۡ ثُمَّ تَلِينُ جُلُودُهُمۡ وَقُلُوبُهُمۡ\nT;0;39:23:0:إِلَىٰ ذِكۡرِ ٱللَّهِۚ ذَٰلِكَ هُدَى ٱللَّهِ يَهۡدِي بِهِۦ مَن يَشَآءُۚ وَمَن\nT;0;39:23:2:يُضۡلِلِ ٱللَّهُ فَمَا لَهُۥ مِنۡ هَادٍ¦39:24:1:أَفَمَن يَتَّقِي بِوَجۡهِهِۦ سُوٓءَ\nT;0;39:24:2:ٱلۡعَذَابِ يَوۡمَ ٱلۡقِيَٰمَةِۚ وَقِيلَ لِلظَّٰلِمِينَ ذُوقُواْ مَا كُنتُمۡ تَكۡسِبُونَ\nT;0;39:25:1:كَذَّبَ ٱلَّذِينَ مِن قَبۡلِهِمۡ فَأَتَىٰهُمُ ٱلۡعَذَابُ مِنۡ حَيۡثُ\nT;0;39:25:2:لَا يَشۡعُرُونَ¦39:26:1:فَأَذَاقَهُمُ ٱللَّهُ ٱلۡخِزۡيَ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۖ وَلَعَذَابُ\nT;0;39:26:2:ٱلۡأٓخِرَةِ أَكۡبَرُۚ لَوۡ كَانُواْ يَعۡلَمُونَ¦39:27:1:وَلَقَدۡ ضَرَبۡنَا لِلنَّاسِ فِي\nT;0;39:27:2:هَٰذَا ٱلۡقُرۡءَانِ مِن كُلِّ مَثَلࣲ لَّعَلَّهُمۡ يَتَذَكَّرُونَ¦39:28:1:قُرۡءَانًا عَرَبِيًّا\nT;0;39:28:2:غَيۡرَ ذِي عِوَجࣲ لَّعَلَّهُمۡ يَتَّقُونَ¦39:29:1:ضَرَبَ ٱللَّهُ مَثَلࣰا رَّجُلࣰا فِيهِ\nT;0;39:29:0:شُرَكَآءُ مُتَشَٰكِسُونَ وَرَجُلࣰا سَلَمࣰا لِّرَجُلٍ هَلۡ يَسۡتَوِيَانِ مَثَلًاۚ\nT;0;39:29:2:ٱلۡحَمۡدُ لِلَّهِۚ بَلۡ أَكۡثَرُهُمۡ لَا يَعۡلَمُونَ¦39:30:1:إِنَّكَ مَيِّتࣱ وَإِنَّهُم\nT;0;39:30:2:مَّيِّتُونَ¦39:31:3:ثُمَّ إِنَّكُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ عِندَ رَبِّكُمۡ تَخۡتَصِمُونَ',
  '24;47;0;185\nT;0;39:32:1:۞ فَمَنۡ أَظۡلَمُ مِمَّن كَذَبَ عَلَى ٱللَّهِ وَكَذَّبَ بِٱلصِّدۡقِ\nT;0;39:32:2:إِذۡ جَآءَهُۥٓۚ أَلَيۡسَ فِي جَهَنَّمَ مَثۡوࣰى لِّلۡكَٰفِرِينَ¦39:33:1:وَٱلَّذِي\nT;0;39:33:2:جَآءَ بِٱلصِّدۡقِ وَصَدَّقَ بِهِۦٓ أُوْلَٰٓئِكَ هُمُ ٱلۡمُتَّقُونَ\nT;0;39:34:3:لَهُم مَّا يَشَآءُونَ عِندَ رَبِّهِمۡۚ ذَٰلِكَ جَزَآءُ ٱلۡمُحۡسِنِينَ\nT;0;39:35:1:لِيُكَفِّرَ ٱللَّهُ عَنۡهُمۡ أَسۡوَأَ ٱلَّذِي عَمِلُواْ وَيَجۡزِيَهُمۡ أَجۡرَهُم\nT;0;39:35:2:بِأَحۡسَنِ ٱلَّذِي كَانُواْ يَعۡمَلُونَ¦39:36:1:أَلَيۡسَ ٱللَّهُ بِكَافٍ\nT;0;39:36:0:عَبۡدَهُۥۖ وَيُخَوِّفُونَكَ بِٱلَّذِينَ مِن دُونِهِۦۚ وَمَن يُضۡلِلِ ٱللَّهُ\nT;0;39:36:2:فَمَا لَهُۥ مِنۡ هَادࣲ¦39:37:1:وَمَن يَهۡدِ ٱللَّهُ فَمَا لَهُۥ مِن مُّضِلٍّۗ\nT;0;39:37:2:أَلَيۡسَ ٱللَّهُ بِعَزِيزࣲ ذِي ٱنتِقَامࣲ¦39:38:1:وَلَئِن سَأَلۡتَهُم مَّنۡ خَلَقَ\nT;0;39:38:0:ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ لَيَقُولُنَّ ٱللَّهُۚ قُلۡ أَفَرَءَيۡتُم مَّا تَدۡعُونَ\nT;0;39:38:0:مِن دُونِ ٱللَّهِ إِنۡ أَرَادَنِيَ ٱللَّهُ بِضُرٍّ هَلۡ هُنَّ كَٰشِفَٰتُ\nT;0;39:38:0:ضُرِّهِۦٓ أَوۡ أَرَادَنِي بِرَحۡمَةٍ هَلۡ هُنَّ مُمۡسِكَٰتُ رَحۡمَتِهِۦۚ\nT;0;39:38:2:قُلۡ حَسۡبِيَ ٱللَّهُۖ عَلَيۡهِ يَتَوَكَّلُ ٱلۡمُتَوَكِّلُونَ¦39:39:1:قُلۡ يَٰقَوۡمِ\nT;0;39:39:2:ٱعۡمَلُواْ عَلَىٰ مَكَانَتِكُمۡ إِنِّي عَٰمِلࣱۖ فَسَوۡفَ تَعۡلَمُونَ\nT;0;39:40:3:مَن يَأۡتِيهِ عَذَابࣱ يُخۡزِيهِ وَيَحِلُّ عَلَيۡهِ عَذَابࣱ مُّقِيمٌ',
  '24;47;0;\nT;0;39:41:1:إِنَّآ أَنزَلۡنَا عَلَيۡكَ ٱلۡكِتَٰبَ لِلنَّاسِ بِٱلۡحَقِّۖ فَمَنِ ٱهۡتَدَىٰ\nT;0;39:41:0:فَلِنَفۡسِهِۦۖ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيۡهَاۖ وَمَآ أَنتَ عَلَيۡهِم\nT;0;39:41:2:بِوَكِيلٍ¦39:42:1:ٱللَّهُ يَتَوَفَّى ٱلۡأَنفُسَ حِينَ مَوۡتِهَا وَٱلَّتِي\nT;0;39:42:0:لَمۡ تَمُتۡ فِي مَنَامِهَاۖ فَيُمۡسِكُ ٱلَّتِي قَضَىٰ عَلَيۡهَا ٱلۡمَوۡتَ\nT;0;39:42:0:وَيُرۡسِلُ ٱلۡأُخۡرَىٰٓ إِلَىٰٓ أَجَلࣲ مُّسَمًّىۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتࣲ لِّقَوۡمࣲ\nT;0;39:42:2:يَتَفَكَّرُونَ¦39:43:1:أَمِ ٱتَّخَذُواْ مِن دُونِ ٱللَّهِ شُفَعَآءَۚ قُلۡ\nT;0;39:43:2:أَوَلَوۡ كَانُواْ لَا يَمۡلِكُونَ شَيۡـࣰٔا وَلَا يَعۡقِلُونَ¦39:44:1:قُل\nT;0;39:44:0:لِّلَّهِ ٱلشَّفَٰعَةُ جَمِيعࣰاۖ لَّهُۥ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ ثُمَّ\nT;0;39:44:2:إِلَيۡهِ تُرۡجَعُونَ¦39:45:1:وَإِذَا ذُكِرَ ٱللَّهُ وَحۡدَهُ ٱشۡمَأَزَّتۡ\nT;0;39:45:0:قُلُوبُ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِۖ وَإِذَا ذُكِرَ ٱلَّذِينَ مِن\nT;0;39:45:2:دُونِهِۦٓ إِذَا هُمۡ يَسۡتَبۡشِرُونَ¦39:46:1:قُلِ ٱللَّهُمَّ فَاطِرَ ٱلسَّمَٰوَٰتِ\nT;0;39:46:0:وَٱلۡأَرۡضِ عَٰلِمَ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِ أَنتَ تَحۡكُمُ بَيۡنَ عِبَادِكَ\nT;0;39:46:2:فِي مَا كَانُواْ فِيهِ يَخۡتَلِفُونَ¦39:47:1:وَلَوۡ أَنَّ لِلَّذِينَ ظَلَمُواْ مَا فِي\nT;0;39:47:0:ٱلۡأَرۡضِ جَمِيعࣰا وَمِثۡلَهُۥ مَعَهُۥ لَٱفۡتَدَوۡاْ بِهِۦ مِن سُوٓءِ ٱلۡعَذَابِ\nT;0;39:47:2:يَوۡمَ ٱلۡقِيَٰمَةِۚ وَبَدَا لَهُم مِّنَ ٱللَّهِ مَا لَمۡ يَكُونُواْ يَحۡتَسِبُونَ',
  '24;47;0;186\nT;0;39:48:1:وَبَدَا لَهُمۡ سَيِّـَٔاتُ مَا كَسَبُواْ وَحَاقَ بِهِم مَّا كَانُواْ بِهِۦ\nT;0;39:48:2:يَسۡتَهۡزِءُونَ¦39:49:1:فَإِذَا مَسَّ ٱلۡإِنسَٰنَ ضُرࣱّ دَعَانَا ثُمَّ إِذَا خَوَّلۡنَٰهُ\nT;0;39:49:0:نِعۡمَةࣰ مِّنَّا قَالَ إِنَّمَآ أُوتِيتُهُۥ عَلَىٰ عِلۡمِۭۚ بَلۡ هِيَ فِتۡنَةࣱ وَلَٰكِنَّ\nT;0;39:49:2:أَكۡثَرَهُمۡ لَا يَعۡلَمُونَ¦39:50:1:قَدۡ قَالَهَا ٱلَّذِينَ مِن قَبۡلِهِمۡ فَمَآ\nT;0;39:50:2:أَغۡنَىٰ عَنۡهُم مَّا كَانُواْ يَكۡسِبُونَ¦39:51:1:فَأَصَابَهُمۡ سَيِّـَٔاتُ\nT;0;39:51:0:مَا كَسَبُواْۚ وَٱلَّذِينَ ظَلَمُواْ مِنۡ هَٰٓؤُلَآءِ سَيُصِيبُهُمۡ سَيِّـَٔاتُ\nT;0;39:51:2:مَا كَسَبُواْ وَمَا هُم بِمُعۡجِزِينَ¦39:52:1:أَوَلَمۡ يَعۡلَمُوٓاْ أَنَّ ٱللَّهَ يَبۡسُطُ\nT;0;39:52:2:ٱلرِّزۡقَ لِمَن يَشَآءُ وَيَقۡدِرُۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتࣲ لِّقَوۡمࣲ يُؤۡمِنُونَ\nT;0;39:53:1:۞ قُلۡ يَٰعِبَادِيَ ٱلَّذِينَ أَسۡرَفُواْ عَلَىٰٓ أَنفُسِهِمۡ لَا تَقۡنَطُواْ\nT;0;39:53:0:مِن رَّحۡمَةِ ٱللَّهِۚ إِنَّ ٱللَّهَ يَغۡفِرُ ٱلذُّنُوبَ جَمِيعًاۚ إِنَّهُۥ هُوَ\nT;0;39:53:2:ٱلۡغَفُورُ ٱلرَّحِيمُ¦39:54:1:وَأَنِيبُوٓاْ إِلَىٰ رَبِّكُمۡ وَأَسۡلِمُواْ لَهُۥ مِن\nT;0;39:54:2:قَبۡلِ أَن يَأۡتِيَكُمُ ٱلۡعَذَابُ ثُمَّ لَا تُنصَرُونَ¦39:55:1:وَٱتَّبِعُوٓاْ أَحۡسَنَ\nT;0;39:55:0:مَآ أُنزِلَ إِلَيۡكُم مِّن رَّبِّكُم مِّن قَبۡلِ أَن يَأۡتِيَكُمُ ٱلۡعَذَابُ\nT;0;39:55:2:بَغۡتَةࣰ وَأَنتُمۡ لَا تَشۡعُرُونَ¦39:56:1:أَن تَقُولَ نَفۡسࣱ يَٰحَسۡرَتَىٰ\nT;0;39:56:2:عَلَىٰ مَا فَرَّطتُ فِي جَنۢبِ ٱللَّهِ وَإِن كُنتُ لَمِنَ ٱلسَّٰخِرِينَ',
  '24;47;1;\nT;0;39:57:3:أَوۡ تَقُولَ لَوۡ أَنَّ ٱللَّهَ هَدَىٰنِي لَكُنتُ مِنَ ٱلۡمُتَّقِينَ¦39:58:1:أَوۡ تَقُولَ\nT;0;39:58:2:حِينَ تَرَى ٱلۡعَذَابَ لَوۡ أَنَّ لِي كَرَّةࣰ فَأَكُونَ مِنَ ٱلۡمُحۡسِنِينَ\nT;0;39:59:1:بَلَىٰ قَدۡ جَآءَتۡكَ ءَايَٰتِي فَكَذَّبۡتَ بِهَا وَٱسۡتَكۡبَرۡتَ وَكُنتَ\nT;0;39:59:2:مِنَ ٱلۡكَٰفِرِينَ¦39:60:1:وَيَوۡمَ ٱلۡقِيَٰمَةِ تَرَى ٱلَّذِينَ كَذَبُواْ عَلَى\nT;0;39:60:2:ٱللَّهِ وُجُوهُهُم مُّسۡوَدَّةٌۚ أَلَيۡسَ فِي جَهَنَّمَ مَثۡوࣰى لِّلۡمُتَكَبِّرِينَ\nT;0;39:61:1:وَيُنَجِّي ٱللَّهُ ٱلَّذِينَ ٱتَّقَوۡاْ بِمَفَازَتِهِمۡ لَا يَمَسُّهُمُ ٱلسُّوٓءُ\nT;0;39:61:2:وَلَا هُمۡ يَحۡزَنُونَ¦39:62:1:ٱللَّهُ خَٰلِقُ كُلِّ شَيۡءࣲۖ وَهُوَ عَلَىٰ كُلِّ\nT;0;39:62:2:شَيۡءࣲ وَكِيلࣱ¦39:63:1:لَّهُۥ مَقَالِيدُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۗ وَٱلَّذِينَ\nT;0;39:63:2:كَفَرُواْ بِـَٔايَٰتِ ٱللَّهِ أُوْلَٰٓئِكَ هُمُ ٱلۡخَٰسِرُونَ¦39:64:1:قُلۡ\nT;0;39:64:2:أَفَغَيۡرَ ٱللَّهِ تَأۡمُرُوٓنِّيٓ أَعۡبُدُ أَيُّهَا ٱلۡجَٰهِلُونَ¦39:65:1:وَلَقَدۡ\nT;0;39:65:0:أُوحِيَ إِلَيۡكَ وَإِلَى ٱلَّذِينَ مِن قَبۡلِكَ لَئِنۡ أَشۡرَكۡتَ\nT;0;39:65:2:لَيَحۡبَطَنَّ عَمَلُكَ وَلَتَكُونَنَّ مِنَ ٱلۡخَٰسِرِينَ¦39:66:1:بَلِ\nT;0;39:66:2:ٱللَّهَ فَٱعۡبُدۡ وَكُن مِّنَ ٱلشَّٰكِرِينَ¦39:67:1:وَمَا قَدَرُواْ ٱللَّهَ حَقَّ\nT;0;39:67:0:قَدۡرِهِۦ وَٱلۡأَرۡضُ جَمِيعࣰا قَبۡضَتُهُۥ يَوۡمَ ٱلۡقِيَٰمَةِ وَٱلسَّمَٰوَٰتُ\nT;0;39:67:2:مَطۡوِيَّٰتُۢ بِيَمِينِهِۦۚ سُبۡحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يُشۡرِكُونَ',
  '24;47;1;\nT;0;39:68:1:وَنُفِخَ فِي ٱلصُّورِ فَصَعِقَ مَن فِي ٱلسَّمَٰوَٰتِ وَمَن فِي ٱلۡأَرۡضِ\nT;0;39:68:2:إِلَّا مَن شَآءَ ٱللَّهُۖ ثُمَّ نُفِخَ فِيهِ أُخۡرَىٰ فَإِذَا هُمۡ قِيَامࣱ يَنظُرُونَ\nT;0;39:69:1:وَأَشۡرَقَتِ ٱلۡأَرۡضُ بِنُورِ رَبِّهَا وَوُضِعَ ٱلۡكِتَٰبُ وَجِاْيٓءَ\nT;0;39:69:2:بِٱلنَّبِيِّـۧنَ وَٱلشُّهَدَآءِ وَقُضِيَ بَيۡنَهُم بِٱلۡحَقِّ وَهُمۡ لَا يُظۡلَمُونَ\nT;0;39:70:3:وَوُفِّيَتۡ كُلُّ نَفۡسࣲ مَّا عَمِلَتۡ وَهُوَ أَعۡلَمُ بِمَا يَفۡعَلُونَ\nT;0;39:71:1:وَسِيقَ ٱلَّذِينَ كَفَرُوٓاْ إِلَىٰ جَهَنَّمَ زُمَرًاۖ حَتَّىٰٓ إِذَا جَآءُوهَا\nT;0;39:71:0:فُتِحَتۡ أَبۡوَٰبُهَا وَقَالَ لَهُمۡ خَزَنَتُهَآ أَلَمۡ يَأۡتِكُمۡ رُسُلࣱ مِّنكُمۡ\nT;0;39:71:0:يَتۡلُونَ عَلَيۡكُمۡ ءَايَٰتِ رَبِّكُمۡ وَيُنذِرُونَكُمۡ لِقَآءَ يَوۡمِكُمۡ\nT;0;39:71:2:هَٰذَاۚ قَالُواْ بَلَىٰ وَلَٰكِنۡ حَقَّتۡ كَلِمَةُ ٱلۡعَذَابِ عَلَى ٱلۡكَٰفِرِينَ\nT;0;39:72:1:قِيلَ ٱدۡخُلُوٓاْ أَبۡوَٰبَ جَهَنَّمَ خَٰلِدِينَ فِيهَاۖ فَبِئۡسَ مَثۡوَى\nT;0;39:72:2:ٱلۡمُتَكَبِّرِينَ¦39:73:1:وَسِيقَ ٱلَّذِينَ ٱتَّقَوۡاْ رَبَّهُمۡ إِلَى ٱلۡجَنَّةِ\nT;0;39:73:0:زُمَرًاۖ حَتَّىٰٓ إِذَا جَآءُوهَا وَفُتِحَتۡ أَبۡوَٰبُهَا وَقَالَ لَهُمۡ خَزَنَتُهَا\nT;0;39:73:2:سَلَٰمٌ عَلَيۡكُمۡ طِبۡتُمۡ فَٱدۡخُلُوهَا خَٰلِدِينَ¦39:74:1:وَقَالُواْ\nT;0;39:74:0:ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِي صَدَقَنَا وَعۡدَهُۥ وَأَوۡرَثَنَا ٱلۡأَرۡضَ\nT;0;39:74:2:نَتَبَوَّأُ مِنَ ٱلۡجَنَّةِ حَيۡثُ نَشَآءُۖ فَنِعۡمَ أَجۡرُ ٱلۡعَٰمِلِينَ',
  '24;47;1;187\nT;0;39:75:1:وَتَرَى ٱلۡمَلَٰٓئِكَةَ حَآفِّينَ مِنۡ حَوۡلِ ٱلۡعَرۡشِ يُسَبِّحُونَ بِحَمۡدِ\nT;2;39:75:2:رَبِّهِمۡۚ وَقُضِيَ بَيۡنَهُم بِٱلۡحَقِّۚ وَقِيلَ ٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ\nH;40\nB;40\nT;0;40:1:3:حمٓ¦40:2:3:تَنزِيلُ ٱلۡكِتَٰبِ مِنَ ٱللَّهِ ٱلۡعَزِيزِ ٱلۡعَلِيمِ¦40:3:1:غَافِرِ ٱلذَّنۢبِ\nT;0;40:3:0:وَقَابِلِ ٱلتَّوۡبِ شَدِيدِ ٱلۡعِقَابِ ذِي ٱلطَّوۡلِۖ لَآ إِلَٰهَ إِلَّا هُوَۖ إِلَيۡهِ\nT;0;40:3:2:ٱلۡمَصِيرُ¦40:4:1:مَا يُجَٰدِلُ فِيٓ ءَايَٰتِ ٱللَّهِ إِلَّا ٱلَّذِينَ كَفَرُواْ فَلَا يَغۡرُرۡكَ\nT;0;40:4:2:تَقَلُّبُهُمۡ فِي ٱلۡبِلَٰدِ¦40:5:1:كَذَّبَتۡ قَبۡلَهُمۡ قَوۡمُ نُوحࣲ وَٱلۡأَحۡزَابُ\nT;0;40:5:0:مِنۢ بَعۡدِهِمۡۖ وَهَمَّتۡ كُلُّ أُمَّةِۭ بِرَسُولِهِمۡ لِيَأۡخُذُوهُۖ\nT;0;40:5:0:وَجَٰدَلُواْ بِٱلۡبَٰطِلِ لِيُدۡحِضُواْ بِهِ ٱلۡحَقَّ فَأَخَذۡتُهُمۡۖ فَكَيۡفَ\nT;0;40:5:2:كَانَ عِقَابِ¦40:6:1:وَكَذَٰلِكَ حَقَّتۡ كَلِمَتُ رَبِّكَ عَلَى ٱلَّذِينَ\nT;0;40:6:2:كَفَرُوٓاْ أَنَّهُمۡ أَصۡحَٰبُ ٱلنَّارِ¦40:7:1:ٱلَّذِينَ يَحۡمِلُونَ ٱلۡعَرۡشَ\nT;0;40:7:0:وَمَنۡ حَوۡلَهُۥ يُسَبِّحُونَ بِحَمۡدِ رَبِّهِمۡ وَيُؤۡمِنُونَ بِهِۦ وَيَسۡتَغۡفِرُونَ\nT;0;40:7:0:لِلَّذِينَ ءَامَنُواْۖ رَبَّنَا وَسِعۡتَ كُلَّ شَيۡءࣲ رَّحۡمَةࣰ وَعِلۡمࣰا فَٱغۡفِرۡ\nT;0;40:7:2:لِلَّذِينَ تَابُواْ وَٱتَّبَعُواْ سَبِيلَكَ وَقِهِمۡ عَذَابَ ٱلۡجَحِيمِ',
  '24;47;2;\nT;0;40:8:1:رَبَّنَا وَأَدۡخِلۡهُمۡ جَنَّٰتِ عَدۡنٍ ٱلَّتِي وَعَدتَّهُمۡ وَمَن صَلَحَ\nT;0;40:8:0:مِنۡ ءَابَآئِهِمۡ وَأَزۡوَٰجِهِمۡ وَذُرِّيَّٰتِهِمۡۚ إِنَّكَ أَنتَ ٱلۡعَزِيزُ\nT;0;40:8:2:ٱلۡحَكِيمُ¦40:9:1:وَقِهِمُ ٱلسَّيِّـَٔاتِۚ وَمَن تَقِ ٱلسَّيِّـَٔاتِ\nT;0;40:9:2:يَوۡمَئِذࣲ فَقَدۡ رَحِمۡتَهُۥۚ وَذَٰلِكَ هُوَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ¦40:10:1:إِنَّ\nT;0;40:10:0:ٱلَّذِينَ كَفَرُواْ يُنَادَوۡنَ لَمَقۡتُ ٱللَّهِ أَكۡبَرُ مِن مَّقۡتِكُمۡ\nT;0;40:10:2:أَنفُسَكُمۡ إِذۡ تُدۡعَوۡنَ إِلَى ٱلۡإِيمَٰنِ فَتَكۡفُرُونَ¦40:11:1:قَالُواْ رَبَّنَآ\nT;0;40:11:0:أَمَتَّنَا ٱثۡنَتَيۡنِ وَأَحۡيَيۡتَنَا ٱثۡنَتَيۡنِ فَٱعۡتَرَفۡنَا بِذُنُوبِنَا فَهَلۡ\nT;0;40:11:2:إِلَىٰ خُرُوجࣲ مِّن سَبِيلࣲ¦40:12:1:ذَٰلِكُم بِأَنَّهُۥٓ إِذَا دُعِيَ ٱللَّهُ\nT;0;40:12:0:وَحۡدَهُۥ كَفَرۡتُمۡ وَإِن يُشۡرَكۡ بِهِۦ تُؤۡمِنُواْۚ فَٱلۡحُكۡمُ لِلَّهِ\nT;0;40:12:2:ٱلۡعَلِيِّ ٱلۡكَبِيرِ¦40:13:1:هُوَ ٱلَّذِي يُرِيكُمۡ ءَايَٰتِهِۦ وَيُنَزِّلُ لَكُم مِّنَ\nT;0;40:13:2:ٱلسَّمَآءِ رِزۡقࣰاۚ وَمَا يَتَذَكَّرُ إِلَّا مَن يُنِيبُ¦40:14:1:فَٱدۡعُواْ ٱللَّهَ\nT;0;40:14:2:مُخۡلِصِينَ لَهُ ٱلدِّينَ وَلَوۡ كَرِهَ ٱلۡكَٰفِرُونَ¦40:15:1:رَفِيعُ\nT;0;40:15:0:ٱلدَّرَجَٰتِ ذُو ٱلۡعَرۡشِ يُلۡقِي ٱلرُّوحَ مِنۡ أَمۡرِهِۦ عَلَىٰ مَن يَشَآءُ\nT;0;40:15:2:مِنۡ عِبَادِهِۦ لِيُنذِرَ يَوۡمَ ٱلتَّلَاقِ¦40:16:1:يَوۡمَ هُم بَٰرِزُونَۖ لَا يَخۡفَىٰ\nT;0;40:16:2:عَلَى ٱللَّهِ مِنۡهُمۡ شَيۡءࣱۚ لِّمَنِ ٱلۡمُلۡكُ ٱلۡيَوۡمَۖ لِلَّهِ ٱلۡوَٰحِدِ ٱلۡقَهَّارِ',
  '24;47;2;188\nT;0;40:17:1:ٱلۡيَوۡمَ تُجۡزَىٰ كُلُّ نَفۡسِۭ بِمَا كَسَبَتۡۚ لَا ظُلۡمَ ٱلۡيَوۡمَۚ إِنَّ\nT;0;40:17:2:ٱللَّهَ سَرِيعُ ٱلۡحِسَابِ¦40:18:1:وَأَنذِرۡهُمۡ يَوۡمَ ٱلۡأٓزِفَةِ إِذِ ٱلۡقُلُوبُ\nT;0;40:18:0:لَدَى ٱلۡحَنَاجِرِ كَٰظِمِينَۚ مَا لِلظَّٰلِمِينَ مِنۡ حَمِيمࣲ وَلَا شَفِيعࣲ\nT;0;40:18:2:يُطَاعُ¦40:19:3:يَعۡلَمُ خَآئِنَةَ ٱلۡأَعۡيُنِ وَمَا تُخۡفِي ٱلصُّدُورُ¦40:20:1:وَٱللَّهُ\nT;0;40:20:0:يَقۡضِي بِٱلۡحَقِّۖ وَٱلَّذِينَ يَدۡعُونَ مِن دُونِهِۦ لَا يَقۡضُونَ\nT;0;40:20:2:بِشَيۡءٍۗ إِنَّ ٱللَّهَ هُوَ ٱلسَّمِيعُ ٱلۡبَصِيرُ¦40:21:1:۞ أَوَلَمۡ يَسِيرُواْ فِي\nT;0;40:21:0:ٱلۡأَرۡضِ فَيَنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ كَانُواْ مِن قَبۡلِهِمۡۚ\nT;0;40:21:0:كَانُواْ هُمۡ أَشَدَّ مِنۡهُمۡ قُوَّةࣰ وَءَاثَارࣰا فِي ٱلۡأَرۡضِ فَأَخَذَهُمُ ٱللَّهُ\nT;0;40:21:2:بِذُنُوبِهِمۡ وَمَا كَانَ لَهُم مِّنَ ٱللَّهِ مِن وَاقࣲ¦40:22:1:ذَٰلِكَ بِأَنَّهُمۡ\nT;0;40:22:0:كَانَت تَّأۡتِيهِمۡ رُسُلُهُم بِٱلۡبَيِّنَٰتِ فَكَفَرُواْ فَأَخَذَهُمُ ٱللَّهُۚ\nT;0;40:22:2:إِنَّهُۥ قَوِيࣱّ شَدِيدُ ٱلۡعِقَابِ¦40:23:1:وَلَقَدۡ أَرۡسَلۡنَا مُوسَىٰ بِـَٔايَٰتِنَا\nT;0;40:23:2:وَسُلۡطَٰنࣲ مُّبِينٍ¦40:24:1:إِلَىٰ فِرۡعَوۡنَ وَهَٰمَٰنَ وَقَٰرُونَ\nT;0;40:24:2:فَقَالُواْ سَٰحِرࣱ كَذَّابࣱ¦40:25:1:فَلَمَّا جَآءَهُم بِٱلۡحَقِّ مِنۡ\nT;0;40:25:0:عِندِنَا قَالُواْ ٱقۡتُلُوٓاْ أَبۡنَآءَ ٱلَّذِينَ ءَامَنُواْ مَعَهُۥ وَٱسۡتَحۡيُواْ\nT;0;40:25:2:نِسَآءَهُمۡۚ وَمَا كَيۡدُ ٱلۡكَٰفِرِينَ إِلَّا فِي ضَلَٰلࣲ',
  '24;47;3;\nT;0;40:26:1:وَقَالَ فِرۡعَوۡنُ ذَرُونِيٓ أَقۡتُلۡ مُوسَىٰ وَلۡيَدۡعُ رَبَّهُۥٓۖ إِنِّيٓ أَخَافُ\nT;0;40:26:2:أَن يُبَدِّلَ دِينَكُمۡ أَوۡ أَن يُظۡهِرَ فِي ٱلۡأَرۡضِ ٱلۡفَسَادَ\nT;0;40:27:1:وَقَالَ مُوسَىٰٓ إِنِّي عُذۡتُ بِرَبِّي وَرَبِّكُم مِّن كُلِّ مُتَكَبِّرࣲ لَّا يُؤۡمِنُ\nT;0;40:27:2:بِيَوۡمِ ٱلۡحِسَابِ¦40:28:1:وَقَالَ رَجُلࣱ مُّؤۡمِنࣱ مِّنۡ ءَالِ فِرۡعَوۡنَ\nT;0;40:28:0:يَكۡتُمُ إِيمَٰنَهُۥٓ أَتَقۡتُلُونَ رَجُلًا أَن يَقُولَ رَبِّيَ ٱللَّهُ وَقَدۡ\nT;0;40:28:0:جَآءَكُم بِٱلۡبَيِّنَٰتِ مِن رَّبِّكُمۡۖ وَإِن يَكُ كَٰذِبࣰا فَعَلَيۡهِ\nT;0;40:28:0:كَذِبُهُۥۖ وَإِن يَكُ صَادِقࣰا يُصِبۡكُم بَعۡضُ ٱلَّذِي يَعِدُكُمۡۖ\nT;0;40:28:2:إِنَّ ٱللَّهَ لَا يَهۡدِي مَنۡ هُوَ مُسۡرِفࣱ كَذَّابࣱ¦40:29:1:يَٰقَوۡمِ لَكُمُ\nT;0;40:29:0:ٱلۡمُلۡكُ ٱلۡيَوۡمَ ظَٰهِرِينَ فِي ٱلۡأَرۡضِ فَمَن يَنصُرُنَا مِنۢ بَأۡسِ ٱللَّهِ\nT;0;40:29:0:إِن جَآءَنَاۚ قَالَ فِرۡعَوۡنُ مَآ أُرِيكُمۡ إِلَّا مَآ أَرَىٰ وَمَآ أَهۡدِيكُمۡ\nT;0;40:29:2:إِلَّا سَبِيلَ ٱلرَّشَادِ¦40:30:1:وَقَالَ ٱلَّذِيٓ ءَامَنَ يَٰقَوۡمِ إِنِّيٓ أَخَافُ\nT;0;40:30:2:عَلَيۡكُم مِّثۡلَ يَوۡمِ ٱلۡأَحۡزَابِ¦40:31:1:مِثۡلَ دَأۡبِ قَوۡمِ نُوحࣲ وَعَادࣲ\nT;0;40:31:2:وَثَمُودَ وَٱلَّذِينَ مِنۢ بَعۡدِهِمۡۚ وَمَا ٱللَّهُ يُرِيدُ ظُلۡمࣰا لِّلۡعِبَادِ\nT;0;40:32:3:وَيَٰقَوۡمِ إِنِّيٓ أَخَافُ عَلَيۡكُمۡ يَوۡمَ ٱلتَّنَادِ¦40:33:1:يَوۡمَ تُوَلُّونَ مُدۡبِرِينَ\nT;0;40:33:2:مَا لَكُم مِّنَ ٱللَّهِ مِنۡ عَاصِمࣲۗ وَمَن يُضۡلِلِ ٱللَّهُ فَمَا لَهُۥ مِنۡ هَادࣲ',
  '24;47;3;\nT;0;40:34:1:وَلَقَدۡ جَآءَكُمۡ يُوسُفُ مِن قَبۡلُ بِٱلۡبَيِّنَٰتِ فَمَا زِلۡتُمۡ فِي\nT;0;40:34:0:شَكࣲّ مِّمَّا جَآءَكُم بِهِۦۖ حَتَّىٰٓ إِذَا هَلَكَ قُلۡتُمۡ لَن يَبۡعَثَ ٱللَّهُ\nT;0;40:34:0:مِنۢ بَعۡدِهِۦ رَسُولࣰاۚ كَذَٰلِكَ يُضِلُّ ٱللَّهُ مَنۡ هُوَ مُسۡرِفࣱ\nT;0;40:34:2:مُّرۡتَابٌ¦40:35:1:ٱلَّذِينَ يُجَٰدِلُونَ فِيٓ ءَايَٰتِ ٱللَّهِ بِغَيۡرِ سُلۡطَٰنٍ\nT;0;40:35:0:أَتَىٰهُمۡۖ كَبُرَ مَقۡتًا عِندَ ٱللَّهِ وَعِندَ ٱلَّذِينَ ءَامَنُواْۚ كَذَٰلِكَ\nT;0;40:35:2:يَطۡبَعُ ٱللَّهُ عَلَىٰ كُلِّ قَلۡبِ مُتَكَبِّرࣲ جَبَّارࣲ¦40:36:1:وَقَالَ فِرۡعَوۡنُ\nT;0;40:36:2:يَٰهَٰمَٰنُ ٱبۡنِ لِي صَرۡحࣰا لَّعَلِّيٓ أَبۡلُغُ ٱلۡأَسۡبَٰبَ¦40:37:1:أَسۡبَٰبَ\nT;0;40:37:0:ٱلسَّمَٰوَٰتِ فَأَطَّلِعَ إِلَىٰٓ إِلَٰهِ مُوسَىٰ وَإِنِّي لَأَظُنُّهُۥ كَٰذِبࣰاۚ\nT;0;40:37:0:وَكَذَٰلِكَ زُيِّنَ لِفِرۡعَوۡنَ سُوٓءُ عَمَلِهِۦ وَصُدَّ عَنِ ٱلسَّبِيلِۚ\nT;0;40:37:2:وَمَا كَيۡدُ فِرۡعَوۡنَ إِلَّا فِي تَبَابࣲ¦40:38:1:وَقَالَ ٱلَّذِيٓ ءَامَنَ\nT;0;40:38:2:يَٰقَوۡمِ ٱتَّبِعُونِ أَهۡدِكُمۡ سَبِيلَ ٱلرَّشَادِ¦40:39:1:يَٰقَوۡمِ\nT;0;40:39:0:إِنَّمَا هَٰذِهِ ٱلۡحَيَوٰةُ ٱلدُّنۡيَا مَتَٰعࣱ وَإِنَّ ٱلۡأٓخِرَةَ هِيَ\nT;0;40:39:2:دَارُ ٱلۡقَرَارِ¦40:40:1:مَنۡ عَمِلَ سَيِّئَةࣰ فَلَا يُجۡزَىٰٓ إِلَّا مِثۡلَهَاۖ\nT;0;40:40:0:وَمَنۡ عَمِلَ صَٰلِحࣰا مِّن ذَكَرٍ أَوۡ أُنثَىٰ وَهُوَ مُؤۡمِنࣱ فَأُوْلَٰٓئِكَ\nT;0;40:40:2:يَدۡخُلُونَ ٱلۡجَنَّةَ يُرۡزَقُونَ فِيهَا بِغَيۡرِ حِسَابࣲ',
  '24;48;0;189\nT;0;40:41:3:۞ وَيَٰقَوۡمِ مَا لِيٓ أَدۡعُوكُمۡ إِلَى ٱلنَّجَوٰةِ وَتَدۡعُونَنِيٓ إِلَى ٱلنَّارِ\nT;0;40:42:1:تَدۡعُونَنِي لِأَكۡفُرَ بِٱللَّهِ وَأُشۡرِكَ بِهِۦ مَا لَيۡسَ لِي بِهِۦ\nT;0;40:42:2:عِلۡمࣱ وَأَنَا۠ أَدۡعُوكُمۡ إِلَى ٱلۡعَزِيزِ ٱلۡغَفَّٰرِ¦40:43:1:لَا جَرَمَ أَنَّمَا\nT;0;40:43:0:تَدۡعُونَنِيٓ إِلَيۡهِ لَيۡسَ لَهُۥ دَعۡوَةࣱ فِي ٱلدُّنۡيَا وَلَا فِي ٱلۡأٓخِرَةِ\nT;0;40:43:2:وَأَنَّ مَرَدَّنَآ إِلَى ٱللَّهِ وَأَنَّ ٱلۡمُسۡرِفِينَ هُمۡ أَصۡحَٰبُ ٱلنَّارِ\nT;0;40:44:1:فَسَتَذۡكُرُونَ مَآ أَقُولُ لَكُمۡۚ وَأُفَوِّضُ أَمۡرِيٓ إِلَى ٱللَّهِۚ\nT;0;40:44:2:إِنَّ ٱللَّهَ بَصِيرُۢ بِٱلۡعِبَادِ¦40:45:1:فَوَقَىٰهُ ٱللَّهُ سَيِّـَٔاتِ مَا مَكَرُواْۖ\nT;0;40:45:2:وَحَاقَ بِـَٔالِ فِرۡعَوۡنَ سُوٓءُ ٱلۡعَذَابِ¦40:46:1:ٱلنَّارُ يُعۡرَضُونَ\nT;0;40:46:0:عَلَيۡهَا غُدُوࣰّا وَعَشِيࣰّاۚ وَيَوۡمَ تَقُومُ ٱلسَّاعَةُ أَدۡخِلُوٓاْ ءَالَ\nT;0;40:46:2:فِرۡعَوۡنَ أَشَدَّ ٱلۡعَذَابِ¦40:47:1:وَإِذۡ يَتَحَآجُّونَ فِي ٱلنَّارِ\nT;0;40:47:0:فَيَقُولُ ٱلضُّعَفَٰٓؤُاْ لِلَّذِينَ ٱسۡتَكۡبَرُوٓاْ إِنَّا كُنَّا لَكُمۡ\nT;0;40:47:2:تَبَعࣰا فَهَلۡ أَنتُم مُّغۡنُونَ عَنَّا نَصِيبࣰا مِّنَ ٱلنَّارِ¦40:48:1:قَالَ\nT;0;40:48:0:ٱلَّذِينَ ٱسۡتَكۡبَرُوٓاْ إِنَّا كُلࣱّ فِيهَآ إِنَّ ٱللَّهَ قَدۡ حَكَمَ\nT;0;40:48:2:بَيۡنَ ٱلۡعِبَادِ¦40:49:1:وَقَالَ ٱلَّذِينَ فِي ٱلنَّارِ لِخَزَنَةِ جَهَنَّمَ\nT;0;40:49:2:ٱدۡعُواْ رَبَّكُمۡ يُخَفِّفۡ عَنَّا يَوۡمࣰا مِّنَ ٱلۡعَذَابِ',
  '24;48;0;\nT;0;40:50:1:قَالُوٓاْ أَوَلَمۡ تَكُ تَأۡتِيكُمۡ رُسُلُكُم بِٱلۡبَيِّنَٰتِۖ قَالُواْ بَلَىٰۚ\nT;0;40:50:2:قَالُواْ فَٱدۡعُواْۗ وَمَا دُعَٰٓؤُاْ ٱلۡكَٰفِرِينَ إِلَّا فِي ضَلَٰلٍ\nT;0;40:51:1:إِنَّا لَنَنصُرُ رُسُلَنَا وَٱلَّذِينَ ءَامَنُواْ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا\nT;0;40:51:2:وَيَوۡمَ يَقُومُ ٱلۡأَشۡهَٰدُ¦40:52:1:يَوۡمَ لَا يَنفَعُ ٱلظَّٰلِمِينَ مَعۡذِرَتُهُمۡۖ\nT;0;40:52:2:وَلَهُمُ ٱللَّعۡنَةُ وَلَهُمۡ سُوٓءُ ٱلدَّارِ¦40:53:1:وَلَقَدۡ ءَاتَيۡنَا مُوسَى\nT;0;40:53:2:ٱلۡهُدَىٰ وَأَوۡرَثۡنَا بَنِيٓ إِسۡرَٰٓءِيلَ ٱلۡكِتَٰبَ¦40:54:1:هُدࣰى\nT;0;40:54:2:وَذِكۡرَىٰ لِأُوْلِي ٱلۡأَلۡبَٰبِ¦40:55:1:فَٱصۡبِرۡ إِنَّ وَعۡدَ ٱللَّهِ\nT;0;40:55:0:حَقࣱّ وَٱسۡتَغۡفِرۡ لِذَنۢبِكَ وَسَبِّحۡ بِحَمۡدِ رَبِّكَ بِٱلۡعَشِيِّ\nT;0;40:55:2:وَٱلۡإِبۡكَٰرِ¦40:56:1:إِنَّ ٱلَّذِينَ يُجَٰدِلُونَ فِيٓ ءَايَٰتِ ٱللَّهِ\nT;0;40:56:0:بِغَيۡرِ سُلۡطَٰنٍ أَتَىٰهُمۡ إِن فِي صُدُورِهِمۡ إِلَّا كِبۡرࣱ\nT;0;40:56:0:مَّا هُم بِبَٰلِغِيهِۚ فَٱسۡتَعِذۡ بِٱللَّهِۖ إِنَّهُۥ هُوَ ٱلسَّمِيعُ\nT;0;40:56:2:ٱلۡبَصِيرُ¦40:57:1:لَخَلۡقُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ أَكۡبَرُ مِنۡ\nT;0;40:57:2:خَلۡقِ ٱلنَّاسِ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَعۡلَمُونَ\nT;0;40:58:1:وَمَا يَسۡتَوِي ٱلۡأَعۡمَىٰ وَٱلۡبَصِيرُ وَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ\nT;0;40:58:2:ٱلصَّٰلِحَٰتِ وَلَا ٱلۡمُسِيٓءُۚ قَلِيلࣰا مَّا تَتَذَكَّرُونَ',
  '24;48;0;190\nT;0;40:59:1:إِنَّ ٱلسَّاعَةَ لَأٓتِيَةࣱ لَّا رَيۡبَ فِيهَا وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ\nT;0;40:59:2:لَا يُؤۡمِنُونَ¦40:60:1:وَقَالَ رَبُّكُمُ ٱدۡعُونِيٓ أَسۡتَجِبۡ لَكُمۡۚ\nT;0;40:60:0:إِنَّ ٱلَّذِينَ يَسۡتَكۡبِرُونَ عَنۡ عِبَادَتِي سَيَدۡخُلُونَ جَهَنَّمَ\nT;0;40:60:2:دَاخِرِينَ¦40:61:1:ٱللَّهُ ٱلَّذِي جَعَلَ لَكُمُ ٱلَّيۡلَ لِتَسۡكُنُواْ\nT;0;40:61:0:فِيهِ وَٱلنَّهَارَ مُبۡصِرًاۚ إِنَّ ٱللَّهَ لَذُو فَضۡلٍ عَلَى ٱلنَّاسِ وَلَٰكِنَّ\nT;0;40:61:2:أَكۡثَرَ ٱلنَّاسِ لَا يَشۡكُرُونَ¦40:62:1:ذَٰلِكُمُ ٱللَّهُ رَبُّكُمۡ\nT;0;40:62:2:خَٰلِقُ كُلِّ شَيۡءࣲ لَّآ إِلَٰهَ إِلَّا هُوَۖ فَأَنَّىٰ تُؤۡفَكُونَ\nT;0;40:63:3:كَذَٰلِكَ يُؤۡفَكُ ٱلَّذِينَ كَانُواْ بِـَٔايَٰتِ ٱللَّهِ يَجۡحَدُونَ\nT;0;40:64:1:ٱللَّهُ ٱلَّذِي جَعَلَ لَكُمُ ٱلۡأَرۡضَ قَرَارࣰا وَٱلسَّمَآءَ بِنَآءࣰ\nT;0;40:64:0:وَصَوَّرَكُمۡ فَأَحۡسَنَ صُوَرَكُمۡ وَرَزَقَكُم مِّنَ\nT;0;40:64:0:ٱلطَّيِّبَٰتِۚ ذَٰلِكُمُ ٱللَّهُ رَبُّكُمۡۖ فَتَبَارَكَ ٱللَّهُ رَبُّ\nT;0;40:64:2:ٱلۡعَٰلَمِينَ¦40:65:1:هُوَ ٱلۡحَيُّ لَآ إِلَٰهَ إِلَّا هُوَ فَٱدۡعُوهُ مُخۡلِصِينَ\nT;0;40:65:2:لَهُ ٱلدِّينَۗ ٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ¦40:66:1:۞ قُلۡ إِنِّي\nT;0;40:66:0:نُهِيتُ أَنۡ أَعۡبُدَ ٱلَّذِينَ تَدۡعُونَ مِن دُونِ ٱللَّهِ لَمَّا جَآءَنِيَ\nT;0;40:66:2:ٱلۡبَيِّنَٰتُ مِن رَّبِّي وَأُمِرۡتُ أَنۡ أُسۡلِمَ لِرَبِّ ٱلۡعَٰلَمِينَ',
  '24;48;1;\nT;0;40:67:1:هُوَ ٱلَّذِي خَلَقَكُم مِّن تُرَابࣲ ثُمَّ مِن نُّطۡفَةࣲ ثُمَّ مِنۡ عَلَقَةࣲ ثُمَّ\nT;0;40:67:0:يُخۡرِجُكُمۡ طِفۡلࣰا ثُمَّ لِتَبۡلُغُوٓاْ أَشُدَّكُمۡ ثُمَّ لِتَكُونُواْ شُيُوخࣰاۚ\nT;0;40:67:0:وَمِنكُم مَّن يُتَوَفَّىٰ مِن قَبۡلُۖ وَلِتَبۡلُغُوٓاْ أَجَلࣰا مُّسَمࣰّى وَلَعَلَّكُمۡ\nT;0;40:67:2:تَعۡقِلُونَ¦40:68:1:هُوَ ٱلَّذِي يُحۡيِۦ وَيُمِيتُۖ فَإِذَا قَضَىٰٓ أَمۡرࣰا فَإِنَّمَا\nT;0;40:68:2:يَقُولُ لَهُۥ كُن فَيَكُونُ¦40:69:1:أَلَمۡ تَرَ إِلَى ٱلَّذِينَ يُجَٰدِلُونَ\nT;0;40:69:2:فِيٓ ءَايَٰتِ ٱللَّهِ أَنَّىٰ يُصۡرَفُونَ¦40:70:1:ٱلَّذِينَ كَذَّبُواْ بِٱلۡكِتَٰبِ\nT;0;40:70:2:وَبِمَآ أَرۡسَلۡنَا بِهِۦ رُسُلَنَاۖ فَسَوۡفَ يَعۡلَمُونَ¦40:71:1:إِذِ ٱلۡأَغۡلَٰلُ\nT;0;40:71:2:فِيٓ أَعۡنَٰقِهِمۡ وَٱلسَّلَٰسِلُ يُسۡحَبُونَ¦40:72:1:فِي ٱلۡحَمِيمِ\nT;0;40:72:2:ثُمَّ فِي ٱلنَّارِ يُسۡجَرُونَ¦40:73:1:ثُمَّ قِيلَ لَهُمۡ أَيۡنَ مَا كُنتُمۡ\nT;0;40:73:2:تُشۡرِكُونَ¦40:74:1:مِن دُونِ ٱللَّهِۖ قَالُواْ ضَلُّواْ عَنَّا بَل لَّمۡ نَكُن\nT;0;40:74:2:نَّدۡعُواْ مِن قَبۡلُ شَيۡـࣰٔاۚ كَذَٰلِكَ يُضِلُّ ٱللَّهُ ٱلۡكَٰفِرِينَ\nT;0;40:75:1:ذَٰلِكُم بِمَا كُنتُمۡ تَفۡرَحُونَ فِي ٱلۡأَرۡضِ بِغَيۡرِ ٱلۡحَقِّ وَبِمَا كُنتُمۡ\nT;0;40:75:2:تَمۡرَحُونَ¦40:76:1:ٱدۡخُلُوٓاْ أَبۡوَٰبَ جَهَنَّمَ خَٰلِدِينَ فِيهَاۖ فَبِئۡسَ مَثۡوَى\nT;0;40:76:2:ٱلۡمُتَكَبِّرِينَ¦40:77:1:فَٱصۡبِرۡ إِنَّ وَعۡدَ ٱللَّهِ حَقࣱّۚ فَإِمَّا نُرِيَنَّكَ\nT;0;40:77:2:بَعۡضَ ٱلَّذِي نَعِدُهُمۡ أَوۡ نَتَوَفَّيَنَّكَ فَإِلَيۡنَا يُرۡجَعُونَ',
  '24;48;1;\nT;0;40:78:1:وَلَقَدۡ أَرۡسَلۡنَا رُسُلࣰا مِّن قَبۡلِكَ مِنۡهُم مَّن قَصَصۡنَا عَلَيۡكَ\nT;0;40:78:0:وَمِنۡهُم مَّن لَّمۡ نَقۡصُصۡ عَلَيۡكَۗ وَمَا كَانَ لِرَسُولٍ أَن يَأۡتِيَ\nT;0;40:78:0:بِـَٔايَةٍ إِلَّا بِإِذۡنِ ٱللَّهِۚ فَإِذَا جَآءَ أَمۡرُ ٱللَّهِ قُضِيَ بِٱلۡحَقِّ وَخَسِرَ\nT;0;40:78:2:هُنَالِكَ ٱلۡمُبۡطِلُونَ¦40:79:1:ٱللَّهُ ٱلَّذِي جَعَلَ لَكُمُ ٱلۡأَنۡعَٰمَ\nT;0;40:79:2:لِتَرۡكَبُواْ مِنۡهَا وَمِنۡهَا تَأۡكُلُونَ¦40:80:1:وَلَكُمۡ فِيهَا مَنَٰفِعُ\nT;0;40:80:0:وَلِتَبۡلُغُواْ عَلَيۡهَا حَاجَةࣰ فِي صُدُورِكُمۡ وَعَلَيۡهَا وَعَلَى\nT;0;40:80:2:ٱلۡفُلۡكِ تُحۡمَلُونَ¦40:81:1:وَيُرِيكُمۡ ءَايَٰتِهِۦ فَأَيَّ ءَايَٰتِ ٱللَّهِ\nT;0;40:81:2:تُنكِرُونَ¦40:82:1:أَفَلَمۡ يَسِيرُواْ فِي ٱلۡأَرۡضِ فَيَنظُرُواْ كَيۡفَ\nT;0;40:82:0:كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبۡلِهِمۡۚ كَانُوٓاْ أَكۡثَرَ مِنۡهُمۡ وَأَشَدَّ\nT;0;40:82:2:قُوَّةࣰ وَءَاثَارࣰا فِي ٱلۡأَرۡضِ فَمَآ أَغۡنَىٰ عَنۡهُم مَّا كَانُواْ يَكۡسِبُونَ\nT;0;40:83:1:فَلَمَّا جَآءَتۡهُمۡ رُسُلُهُم بِٱلۡبَيِّنَٰتِ فَرِحُواْ بِمَا عِندَهُم مِّنَ\nT;0;40:83:2:ٱلۡعِلۡمِ وَحَاقَ بِهِم مَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ¦40:84:1:فَلَمَّا رَأَوۡاْ\nT;0;40:84:0:بَأۡسَنَا قَالُوٓاْ ءَامَنَّا بِٱللَّهِ وَحۡدَهُۥ وَكَفَرۡنَا بِمَا كُنَّا بِهِۦ\nT;0;40:84:2:مُشۡرِكِينَ¦40:85:1:فَلَمۡ يَكُ يَنفَعُهُمۡ إِيمَٰنُهُمۡ لَمَّا رَأَوۡاْ بَأۡسَنَاۖ سُنَّتَ\nT;2;40:85:2:ٱللَّهِ ٱلَّتِي قَدۡ خَلَتۡ فِي عِبَادِهِۦۖ وَخَسِرَ هُنَالِكَ ٱلۡكَٰفِرُونَ',
  '24;48;1;191\nH;41\nB;41\nT;0;41:1:3:حمٓ¦41:2:3:تَنزِيلࣱ مِّنَ ٱلرَّحۡمَٰنِ ٱلرَّحِيمِ¦41:3:1:كِتَٰبࣱ فُصِّلَتۡ ءَايَٰتُهُۥ\nT;0;41:3:2:قُرۡءَانًا عَرَبِيࣰّا لِّقَوۡمࣲ يَعۡلَمُونَ¦41:4:1:بَشِيرࣰا وَنَذِيرࣰا فَأَعۡرَضَ أَكۡثَرُهُمۡ\nT;0;41:4:2:فَهُمۡ لَا يَسۡمَعُونَ¦41:5:1:وَقَالُواْ قُلُوبُنَا فِيٓ أَكِنَّةࣲ مِّمَّا تَدۡعُونَآ إِلَيۡهِ وَفِيٓ\nT;0;41:5:2:ءَاذَانِنَا وَقۡرࣱ وَمِنۢ بَيۡنِنَا وَبَيۡنِكَ حِجَابࣱ فَٱعۡمَلۡ إِنَّنَا عَٰمِلُونَ\nT;0;41:6:1:قُلۡ إِنَّمَآ أَنَا۠ بَشَرࣱ مِّثۡلُكُمۡ يُوحَىٰٓ إِلَيَّ أَنَّمَآ إِلَٰهُكُمۡ إِلَٰهࣱ وَٰحِدࣱ\nT;0;41:6:2:فَٱسۡتَقِيمُوٓاْ إِلَيۡهِ وَٱسۡتَغۡفِرُوهُۗ وَوَيۡلࣱ لِّلۡمُشۡرِكِينَ¦41:7:1:ٱلَّذِينَ\nT;0;41:7:2:لَا يُؤۡتُونَ ٱلزَّكَوٰةَ وَهُم بِٱلۡأٓخِرَةِ هُمۡ كَٰفِرُونَ¦41:8:1:إِنَّ ٱلَّذِينَ\nT;0;41:8:2:ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ لَهُمۡ أَجۡرٌ غَيۡرُ مَمۡنُونࣲ¦41:9:1:۞ قُلۡ أَئِنَّكُمۡ\nT;0;41:9:0:لَتَكۡفُرُونَ بِٱلَّذِي خَلَقَ ٱلۡأَرۡضَ فِي يَوۡمَيۡنِ وَتَجۡعَلُونَ لَهُۥٓ أَندَادࣰاۚ\nT;0;41:9:2:ذَٰلِكَ رَبُّ ٱلۡعَٰلَمِينَ¦41:10:1:وَجَعَلَ فِيهَا رَوَٰسِيَ مِن فَوۡقِهَا\nT;0;41:10:0:وَبَٰرَكَ فِيهَا وَقَدَّرَ فِيهَآ أَقۡوَٰتَهَا فِيٓ أَرۡبَعَةِ أَيَّامࣲ سَوَآءࣰ\nT;0;41:10:2:لِّلسَّآئِلِينَ¦41:11:1:ثُمَّ ٱسۡتَوَىٰٓ إِلَى ٱلسَّمَآءِ وَهِيَ دُخَانࣱ فَقَالَ\nT;0;41:11:2:لَهَا وَلِلۡأَرۡضِ ٱئۡتِيَا طَوۡعًا أَوۡ كَرۡهࣰا قَالَتَآ أَتَيۡنَا طَآئِعِينَ',
  '24;48;2;\nT;0;41:12:1:فَقَضَىٰهُنَّ سَبۡعَ سَمَٰوَاتࣲ فِي يَوۡمَيۡنِ وَأَوۡحَىٰ فِي كُلِّ سَمَآءٍ أَمۡرَهَاۚ\nT;0;41:12:0:وَزَيَّنَّا ٱلسَّمَآءَ ٱلدُّنۡيَا بِمَصَٰبِيحَ وَحِفۡظࣰاۚ ذَٰلِكَ تَقۡدِيرُ ٱلۡعَزِيزِ\nT;0;41:12:2:ٱلۡعَلِيمِ¦41:13:1:فَإِنۡ أَعۡرَضُواْ فَقُلۡ أَنذَرۡتُكُمۡ صَٰعِقَةࣰ مِّثۡلَ صَٰعِقَةِ\nT;0;41:13:2:عَادࣲ وَثَمُودَ¦41:14:1:إِذۡ جَآءَتۡهُمُ ٱلرُّسُلُ مِنۢ بَيۡنِ أَيۡدِيهِمۡ وَمِنۡ\nT;0;41:14:0:خَلۡفِهِمۡ أَلَّا تَعۡبُدُوٓاْ إِلَّا ٱللَّهَۖ قَالُواْ لَوۡ شَآءَ رَبُّنَا لَأَنزَلَ مَلَٰٓئِكَةࣰ\nT;0;41:14:2:فَإِنَّا بِمَآ أُرۡسِلۡتُم بِهِۦ كَٰفِرُونَ¦41:15:1:فَأَمَّا عَادࣱ فَٱسۡتَكۡبَرُواْ فِي\nT;0;41:15:0:ٱلۡأَرۡضِ بِغَيۡرِ ٱلۡحَقِّ وَقَالُواْ مَنۡ أَشَدُّ مِنَّا قُوَّةًۖ أَوَلَمۡ يَرَوۡاْ أَنَّ ٱللَّهَ\nT;0;41:15:2:ٱلَّذِي خَلَقَهُمۡ هُوَ أَشَدُّ مِنۡهُمۡ قُوَّةࣰۖ وَكَانُواْ بِـَٔايَٰتِنَا يَجۡحَدُونَ\nT;0;41:16:1:فَأَرۡسَلۡنَا عَلَيۡهِمۡ رِيحࣰا صَرۡصَرࣰا فِيٓ أَيَّامࣲ نَّحِسَاتࣲ لِّنُذِيقَهُمۡ\nT;0;41:16:0:عَذَابَ ٱلۡخِزۡيِ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۖ وَلَعَذَابُ ٱلۡأٓخِرَةِ أَخۡزَىٰۖ وَهُمۡ\nT;0;41:16:2:لَا يُنصَرُونَ¦41:17:1:وَأَمَّا ثَمُودُ فَهَدَيۡنَٰهُمۡ فَٱسۡتَحَبُّواْ ٱلۡعَمَىٰ عَلَى\nT;0;41:17:2:ٱلۡهُدَىٰ فَأَخَذَتۡهُمۡ صَٰعِقَةُ ٱلۡعَذَابِ ٱلۡهُونِ بِمَا كَانُواْ يَكۡسِبُونَ\nT;0;41:18:3:وَنَجَّيۡنَا ٱلَّذِينَ ءَامَنُواْ وَكَانُواْ يَتَّقُونَ¦41:19:1:وَيَوۡمَ يُحۡشَرُ أَعۡدَآءُ ٱللَّهِ\nT;0;41:19:2:إِلَى ٱلنَّارِ فَهُمۡ يُوزَعُونَ¦41:20:1:حَتَّىٰٓ إِذَا مَا جَآءُوهَا شَهِدَ عَلَيۡهِمۡ\nT;0;41:20:2:سَمۡعُهُمۡ وَأَبۡصَٰرُهُمۡ وَجُلُودُهُم بِمَا كَانُواْ يَعۡمَلُونَ',
  '24;48;2;192\nT;0;41:21:1:وَقَالُواْ لِجُلُودِهِمۡ لِمَ شَهِدتُّمۡ عَلَيۡنَاۖ قَالُوٓاْ أَنطَقَنَا ٱللَّهُ ٱلَّذِيٓ\nT;0;41:21:2:أَنطَقَ كُلَّ شَيۡءࣲۚ وَهُوَ خَلَقَكُمۡ أَوَّلَ مَرَّةࣲ وَإِلَيۡهِ تُرۡجَعُونَ\nT;0;41:22:1:وَمَا كُنتُمۡ تَسۡتَتِرُونَ أَن يَشۡهَدَ عَلَيۡكُمۡ سَمۡعُكُمۡ وَلَآ أَبۡصَٰرُكُمۡ\nT;0;41:22:2:وَلَا جُلُودُكُمۡ وَلَٰكِن ظَنَنتُمۡ أَنَّ ٱللَّهَ لَا يَعۡلَمُ كَثِيرࣰا مِّمَّا تَعۡمَلُونَ\nT;0;41:23:1:وَذَٰلِكُمۡ ظَنُّكُمُ ٱلَّذِي ظَنَنتُم بِرَبِّكُمۡ أَرۡدَىٰكُمۡ فَأَصۡبَحۡتُم\nT;0;41:23:2:مِّنَ ٱلۡخَٰسِرِينَ¦41:24:1:فَإِن يَصۡبِرُواْ فَٱلنَّارُ مَثۡوࣰى لَّهُمۡۖ وَإِن يَسۡتَعۡتِبُواْ\nT;0;41:24:2:فَمَا هُم مِّنَ ٱلۡمُعۡتَبِينَ¦41:25:1:۞ وَقَيَّضۡنَا لَهُمۡ قُرَنَآءَ فَزَيَّنُواْ لَهُم\nT;0;41:25:0:مَّا بَيۡنَ أَيۡدِيهِمۡ وَمَا خَلۡفَهُمۡ وَحَقَّ عَلَيۡهِمُ ٱلۡقَوۡلُ فِيٓ أُمَمࣲ قَدۡ\nT;0;41:25:2:خَلَتۡ مِن قَبۡلِهِم مِّنَ ٱلۡجِنِّ وَٱلۡإِنسِۖ إِنَّهُمۡ كَانُواْ خَٰسِرِينَ\nT;0;41:26:1:وَقَالَ ٱلَّذِينَ كَفَرُواْ لَا تَسۡمَعُواْ لِهَٰذَا ٱلۡقُرۡءَانِ وَٱلۡغَوۡاْ فِيهِ\nT;0;41:26:2:لَعَلَّكُمۡ تَغۡلِبُونَ¦41:27:1:فَلَنُذِيقَنَّ ٱلَّذِينَ كَفَرُواْ عَذَابࣰا شَدِيدࣰا\nT;0;41:27:2:وَلَنَجۡزِيَنَّهُمۡ أَسۡوَأَ ٱلَّذِي كَانُواْ يَعۡمَلُونَ¦41:28:1:ذَٰلِكَ جَزَآءُ أَعۡدَآءِ ٱللَّهِ\nT;0;41:28:2:ٱلنَّارُۖ لَهُمۡ فِيهَا دَارُ ٱلۡخُلۡدِ جَزَآءَۢ بِمَا كَانُواْ بِـَٔايَٰتِنَا يَجۡحَدُونَ\nT;0;41:29:1:وَقَالَ ٱلَّذِينَ كَفَرُواْ رَبَّنَآ أَرِنَا ٱلَّذَيۡنِ أَضَلَّانَا مِنَ ٱلۡجِنِّ\nT;0;41:29:2:وَٱلۡإِنسِ نَجۡعَلۡهُمَا تَحۡتَ أَقۡدَامِنَا لِيَكُونَا مِنَ ٱلۡأَسۡفَلِينَ',
  '24;48;3;\nT;0;41:30:1:إِنَّ ٱلَّذِينَ قَالُواْ رَبُّنَا ٱللَّهُ ثُمَّ ٱسۡتَقَٰمُواْ تَتَنَزَّلُ عَلَيۡهِمُ\nT;0;41:30:0:ٱلۡمَلَٰٓئِكَةُ أَلَّا تَخَافُواْ وَلَا تَحۡزَنُواْ وَأَبۡشِرُواْ بِٱلۡجَنَّةِ\nT;0;41:30:2:ٱلَّتِي كُنتُمۡ تُوعَدُونَ¦41:31:1:نَحۡنُ أَوۡلِيَآؤُكُمۡ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا\nT;0;41:31:0:وَفِي ٱلۡأٓخِرَةِۖ وَلَكُمۡ فِيهَا مَا تَشۡتَهِيٓ أَنفُسُكُمۡ وَلَكُمۡ\nT;0;41:31:2:فِيهَا مَا تَدَّعُونَ¦41:32:3:نُزُلࣰا مِّنۡ غَفُورࣲ رَّحِيمࣲ¦41:33:1:وَمَنۡ أَحۡسَنُ\nT;0;41:33:0:قَوۡلࣰا مِّمَّن دَعَآ إِلَى ٱللَّهِ وَعَمِلَ صَٰلِحࣰا وَقَالَ إِنَّنِي مِنَ\nT;0;41:33:2:ٱلۡمُسۡلِمِينَ¦41:34:1:وَلَا تَسۡتَوِي ٱلۡحَسَنَةُ وَلَا ٱلسَّيِّئَةُۚ ٱدۡفَعۡ\nT;0;41:34:0:بِٱلَّتِي هِيَ أَحۡسَنُ فَإِذَا ٱلَّذِي بَيۡنَكَ وَبَيۡنَهُۥ عَدَٰوَةࣱ كَأَنَّهُۥ\nT;0;41:34:2:وَلِيٌّ حَمِيمࣱ¦41:35:1:وَمَا يُلَقَّىٰهَآ إِلَّا ٱلَّذِينَ صَبَرُواْ وَمَا يُلَقَّىٰهَآ\nT;0;41:35:2:إِلَّا ذُو حَظٍّ عَظِيمࣲ¦41:36:1:وَإِمَّا يَنزَغَنَّكَ مِنَ ٱلشَّيۡطَٰنِ نَزۡغࣱ\nT;0;41:36:2:فَٱسۡتَعِذۡ بِٱللَّهِۖ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ¦41:37:1:وَمِنۡ ءَايَٰتِهِ\nT;0;41:37:0:ٱلَّيۡلُ وَٱلنَّهَارُ وَٱلشَّمۡسُ وَٱلۡقَمَرُۚ لَا تَسۡجُدُواْ لِلشَّمۡسِ\nT;0;41:37:0:وَلَا لِلۡقَمَرِ وَٱسۡجُدُواْۤ لِلَّهِۤ ٱلَّذِي خَلَقَهُنَّ إِن كُنتُمۡ\nT;0;41:37:2:إِيَّاهُ تَعۡبُدُونَ¦41:38:1:فَإِنِ ٱسۡتَكۡبَرُواْ فَٱلَّذِينَ عِندَ\nT;0;41:38:2:رَبِّكَ يُسَبِّحُونَ لَهُۥ بِٱلَّيۡلِ وَٱلنَّهَارِ وَهُمۡ لَا يَسۡـَٔمُونَ۩',
  '24;48;3;\nT;0;41:39:1:وَمِنۡ ءَايَٰتِهِۦٓ أَنَّكَ تَرَى ٱلۡأَرۡضَ خَٰشِعَةࣰ فَإِذَآ أَنزَلۡنَا عَلَيۡهَا ٱلۡمَآءَ\nT;0;41:39:0:ٱهۡتَزَّتۡ وَرَبَتۡۚ إِنَّ ٱلَّذِيٓ أَحۡيَاهَا لَمُحۡيِ ٱلۡمَوۡتَىٰٓۚ إِنَّهُۥ عَلَىٰ كُلِّ شَيۡءࣲ\nT;0;41:39:2:قَدِيرٌ¦41:40:1:إِنَّ ٱلَّذِينَ يُلۡحِدُونَ فِيٓ ءَايَٰتِنَا لَا يَخۡفَوۡنَ عَلَيۡنَآۗ أَفَمَن\nT;0;41:40:0:يُلۡقَىٰ فِي ٱلنَّارِ خَيۡرٌ أَم مَّن يَأۡتِيٓ ءَامِنࣰا يَوۡمَ ٱلۡقِيَٰمَةِۚ ٱعۡمَلُواْ مَا شِئۡتُمۡ\nT;0;41:40:2:إِنَّهُۥ بِمَا تَعۡمَلُونَ بَصِيرٌ¦41:41:1:إِنَّ ٱلَّذِينَ كَفَرُواْ بِٱلذِّكۡرِ لَمَّا جَآءَهُمۡۖ\nT;0;41:41:2:وَإِنَّهُۥ لَكِتَٰبٌ عَزِيزࣱ¦41:42:1:لَّا يَأۡتِيهِ ٱلۡبَٰطِلُ مِنۢ بَيۡنِ يَدَيۡهِ وَلَا مِنۡ\nT;0;41:42:2:خَلۡفِهِۦۖ تَنزِيلࣱ مِّنۡ حَكِيمٍ حَمِيدࣲ¦41:43:1:مَّا يُقَالُ لَكَ إِلَّا مَا قَدۡ قِيلَ\nT;0;41:43:2:لِلرُّسُلِ مِن قَبۡلِكَۚ إِنَّ رَبَّكَ لَذُو مَغۡفِرَةࣲ وَذُو عِقَابٍ أَلِيمࣲ\nT;0;41:44:1:وَلَوۡ جَعَلۡنَٰهُ قُرۡءَانًا أَعۡجَمِيࣰّا لَّقَالُواْ لَوۡلَا فُصِّلَتۡ ءَايَٰتُهُۥٓۖ\nT;0;41:44:0:ءَا۬عۡجَمِيࣱّ وَعَرَبِيࣱّۗ قُلۡ هُوَ لِلَّذِينَ ءَامَنُواْ هُدࣰى وَشِفَآءࣱۚ وَٱلَّذِينَ\nT;0;41:44:0:لَا يُؤۡمِنُونَ فِيٓ ءَاذَانِهِمۡ وَقۡرࣱ وَهُوَ عَلَيۡهِمۡ عَمًىۚ أُوْلَٰٓئِكَ\nT;0;41:44:2:يُنَادَوۡنَ مِن مَّكَانِۭ بَعِيدࣲ¦41:45:1:وَلَقَدۡ ءَاتَيۡنَا مُوسَى ٱلۡكِتَٰبَ\nT;0;41:45:0:فَٱخۡتُلِفَ فِيهِۚ وَلَوۡلَا كَلِمَةࣱ سَبَقَتۡ مِن رَّبِّكَ لَقُضِيَ\nT;0;41:45:2:بَيۡنَهُمۡۚ وَإِنَّهُمۡ لَفِي شَكࣲّ مِّنۡهُ مُرِيبࣲ¦41:46:1:مَّنۡ عَمِلَ صَٰلِحࣰا\nT;0;41:46:2:فَلِنَفۡسِهِۦۖ وَمَنۡ أَسَآءَ فَعَلَيۡهَاۗ وَمَا رَبُّكَ بِظَلَّٰمࣲ لِّلۡعَبِيدِ',
  '25;49;0;193\nT;0;41:47:1:۞ إِلَيۡهِ يُرَدُّ عِلۡمُ ٱلسَّاعَةِۚ وَمَا تَخۡرُجُ مِن ثَمَرَٰتࣲ مِّنۡ أَكۡمَامِهَا\nT;0;41:47:0:وَمَا تَحۡمِلُ مِنۡ أُنثَىٰ وَلَا تَضَعُ إِلَّا بِعِلۡمِهِۦۚ وَيَوۡمَ يُنَادِيهِمۡ أَيۡنَ\nT;0;41:47:2:شُرَكَآءِي قَالُوٓاْ ءَاذَنَّٰكَ مَا مِنَّا مِن شَهِيدࣲ¦41:48:1:وَضَلَّ عَنۡهُم\nT;0;41:48:2:مَّا كَانُواْ يَدۡعُونَ مِن قَبۡلُۖ وَظَنُّواْ مَا لَهُم مِّن مَّحِيصࣲ\nT;0;41:49:1:لَّا يَسۡـَٔمُ ٱلۡإِنسَٰنُ مِن دُعَآءِ ٱلۡخَيۡرِ وَإِن مَّسَّهُ ٱلشَّرُّ فَيَـُٔوسࣱ\nT;0;41:49:2:قَنُوطࣱ¦41:50:1:وَلَئِنۡ أَذَقۡنَٰهُ رَحۡمَةࣰ مِّنَّا مِنۢ بَعۡدِ ضَرَّآءَ مَسَّتۡهُ\nT;0;41:50:0:لَيَقُولَنَّ هَٰذَا لِي وَمَآ أَظُنُّ ٱلسَّاعَةَ قَآئِمَةࣰ وَلَئِن رُّجِعۡتُ إِلَىٰ\nT;0;41:50:0:رَبِّيٓ إِنَّ لِي عِندَهُۥ لَلۡحُسۡنَىٰۚ فَلَنُنَبِّئَنَّ ٱلَّذِينَ كَفَرُواْ بِمَا عَمِلُواْ\nT;0;41:50:2:وَلَنُذِيقَنَّهُم مِّنۡ عَذَابٍ غَلِيظࣲ¦41:51:1:وَإِذَآ أَنۡعَمۡنَا عَلَى ٱلۡإِنسَٰنِ\nT;0;41:51:0:أَعۡرَضَ وَنَـَٔا بِجَانِبِهِۦ وَإِذَا مَسَّهُ ٱلشَّرُّ فَذُو دُعَآءٍ\nT;0;41:51:2:عَرِيضࣲ¦41:52:1:قُلۡ أَرَءَيۡتُمۡ إِن كَانَ مِنۡ عِندِ ٱللَّهِ ثُمَّ كَفَرۡتُم بِهِۦ\nT;0;41:52:2:مَنۡ أَضَلُّ مِمَّنۡ هُوَ فِي شِقَاقِۭ بَعِيدࣲ¦41:53:1:سَنُرِيهِمۡ ءَايَٰتِنَا\nT;0;41:53:0:فِي ٱلۡأٓفَاقِ وَفِيٓ أَنفُسِهِمۡ حَتَّىٰ يَتَبَيَّنَ لَهُمۡ أَنَّهُ ٱلۡحَقُّۗ\nT;0;41:53:2:أَوَلَمۡ يَكۡفِ بِرَبِّكَ أَنَّهُۥ عَلَىٰ كُلِّ شَيۡءࣲ شَهِيدٌ¦41:54:1:أَلَآ إِنَّهُمۡ\nT;2;41:54:2:فِي مِرۡيَةࣲ مِّن لِّقَآءِ رَبِّهِمۡۗ أَلَآ إِنَّهُۥ بِكُلِّ شَيۡءࣲ مُّحِيطُۢ',
  '25;49;0;\nH;42\nB;42\nT;0;42:1:3:حمٓ¦42:2:3:عٓسٓقٓ¦42:3:1:كَذَٰلِكَ يُوحِيٓ إِلَيۡكَ وَإِلَى ٱلَّذِينَ مِن قَبۡلِكَ\nT;0;42:3:2:ٱللَّهُ ٱلۡعَزِيزُ ٱلۡحَكِيمُ¦42:4:1:لَهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۖ\nT;0;42:4:2:وَهُوَ ٱلۡعَلِيُّ ٱلۡعَظِيمُ¦42:5:1:تَكَادُ ٱلسَّمَٰوَٰتُ يَتَفَطَّرۡنَ مِن فَوۡقِهِنَّۚ\nT;0;42:5:0:وَٱلۡمَلَٰٓئِكَةُ يُسَبِّحُونَ بِحَمۡدِ رَبِّهِمۡ وَيَسۡتَغۡفِرُونَ لِمَن فِي\nT;0;42:5:2:ٱلۡأَرۡضِۗ أَلَآ إِنَّ ٱللَّهَ هُوَ ٱلۡغَفُورُ ٱلرَّحِيمُ¦42:6:1:وَٱلَّذِينَ ٱتَّخَذُواْ\nT;0;42:6:2:مِن دُونِهِۦٓ أَوۡلِيَآءَ ٱللَّهُ حَفِيظٌ عَلَيۡهِمۡ وَمَآ أَنتَ عَلَيۡهِم بِوَكِيلࣲ\nT;0;42:7:1:وَكَذَٰلِكَ أَوۡحَيۡنَآ إِلَيۡكَ قُرۡءَانًا عَرَبِيࣰّا لِّتُنذِرَ أُمَّ ٱلۡقُرَىٰ وَمَنۡ\nT;0;42:7:0:حَوۡلَهَا وَتُنذِرَ يَوۡمَ ٱلۡجَمۡعِ لَا رَيۡبَ فِيهِۚ فَرِيقࣱ فِي ٱلۡجَنَّةِ وَفَرِيقࣱ فِي\nT;0;42:7:2:ٱلسَّعِيرِ¦42:8:1:وَلَوۡ شَآءَ ٱللَّهُ لَجَعَلَهُمۡ أُمَّةࣰ وَٰحِدَةࣰ وَلَٰكِن يُدۡخِلُ مَن\nT;0;42:8:2:يَشَآءُ فِي رَحۡمَتِهِۦۚ وَٱلظَّٰلِمُونَ مَا لَهُم مِّن وَلِيࣲّ وَلَا نَصِيرٍ¦42:9:1:أَمِ\nT;0;42:9:0:ٱتَّخَذُواْ مِن دُونِهِۦٓ أَوۡلِيَآءَۖ فَٱللَّهُ هُوَ ٱلۡوَلِيُّ وَهُوَ يُحۡيِ ٱلۡمَوۡتَىٰ وَهُوَ\nT;0;42:9:2:عَلَىٰ كُلِّ شَيۡءࣲ قَدِيرࣱ¦42:10:1:وَمَا ٱخۡتَلَفۡتُمۡ فِيهِ مِن شَيۡءࣲ فَحُكۡمُهُۥٓ\nT;0;42:10:2:إِلَى ٱللَّهِۚ ذَٰلِكُمُ ٱللَّهُ رَبِّي عَلَيۡهِ تَوَكَّلۡتُ وَإِلَيۡهِ أُنِيبُ',
  '25;49;0;194\nT;0;42:11:1:فَاطِرُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ جَعَلَ لَكُم مِّنۡ أَنفُسِكُمۡ أَزۡوَٰجࣰا\nT;0;42:11:0:وَمِنَ ٱلۡأَنۡعَٰمِ أَزۡوَٰجࣰا يَذۡرَؤُكُمۡ فِيهِۚ لَيۡسَ كَمِثۡلِهِۦ شَيۡءࣱۖ وَهُوَ\nT;0;42:11:2:ٱلسَّمِيعُ ٱلۡبَصِيرُ¦42:12:1:لَهُۥ مَقَالِيدُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ يَبۡسُطُ\nT;0;42:12:2:ٱلرِّزۡقَ لِمَن يَشَآءُ وَيَقۡدِرُۚ إِنَّهُۥ بِكُلِّ شَيۡءٍ عَلِيمࣱ¦42:13:1:۞ شَرَعَ\nT;0;42:13:0:لَكُم مِّنَ ٱلدِّينِ مَا وَصَّىٰ بِهِۦ نُوحࣰا وَٱلَّذِيٓ أَوۡحَيۡنَآ إِلَيۡكَ وَمَا\nT;0;42:13:0:وَصَّيۡنَا بِهِۦٓ إِبۡرَٰهِيمَ وَمُوسَىٰ وَعِيسَىٰٓۖ أَنۡ أَقِيمُواْ ٱلدِّينَ\nT;0;42:13:0:وَلَا تَتَفَرَّقُواْ فِيهِۚ كَبُرَ عَلَى ٱلۡمُشۡرِكِينَ مَا تَدۡعُوهُمۡ إِلَيۡهِۚ ٱللَّهُ\nT;0;42:13:2:يَجۡتَبِيٓ إِلَيۡهِ مَن يَشَآءُ وَيَهۡدِيٓ إِلَيۡهِ مَن يُنِيبُ¦42:14:1:وَمَا تَفَرَّقُوٓاْ\nT;0;42:14:0:إِلَّا مِنۢ بَعۡدِ مَا جَآءَهُمُ ٱلۡعِلۡمُ بَغۡيَۢا بَيۡنَهُمۡۚ وَلَوۡلَا كَلِمَةࣱ سَبَقَتۡ\nT;0;42:14:0:مِن رَّبِّكَ إِلَىٰٓ أَجَلࣲ مُّسَمࣰّى لَّقُضِيَ بَيۡنَهُمۡۚ وَإِنَّ ٱلَّذِينَ أُورِثُواْ\nT;0;42:14:2:ٱلۡكِتَٰبَ مِنۢ بَعۡدِهِمۡ لَفِي شَكࣲّ مِّنۡهُ مُرِيبࣲ¦42:15:1:فَلِذَٰلِكَ\nT;0;42:15:0:فَٱدۡعُۖ وَٱسۡتَقِمۡ كَمَآ أُمِرۡتَۖ وَلَا تَتَّبِعۡ أَهۡوَآءَهُمۡۖ وَقُلۡ\nT;0;42:15:0:ءَامَنتُ بِمَآ أَنزَلَ ٱللَّهُ مِن كِتَٰبࣲۖ وَأُمِرۡتُ لِأَعۡدِلَ بَيۡنَكُمُۖ\nT;0;42:15:0:ٱللَّهُ رَبُّنَا وَرَبُّكُمۡۖ لَنَآ أَعۡمَٰلُنَا وَلَكُمۡ أَعۡمَٰلُكُمۡۖ لَا حُجَّةَ\nT;0;42:15:2:بَيۡنَنَا وَبَيۡنَكُمُۖ ٱللَّهُ يَجۡمَعُ بَيۡنَنَاۖ وَإِلَيۡهِ ٱلۡمَصِيرُ',
  '25;49;1;\nT;0;42:16:1:وَٱلَّذِينَ يُحَآجُّونَ فِي ٱللَّهِ مِنۢ بَعۡدِ مَا ٱسۡتُجِيبَ لَهُۥ حُجَّتُهُمۡ\nT;0;42:16:2:دَاحِضَةٌ عِندَ رَبِّهِمۡ وَعَلَيۡهِمۡ غَضَبࣱ وَلَهُمۡ عَذَابࣱ شَدِيدٌ\nT;0;42:17:1:ٱللَّهُ ٱلَّذِيٓ أَنزَلَ ٱلۡكِتَٰبَ بِٱلۡحَقِّ وَٱلۡمِيزَانَۗ وَمَا يُدۡرِيكَ\nT;0;42:17:2:لَعَلَّ ٱلسَّاعَةَ قَرِيبࣱ¦42:18:1:يَسۡتَعۡجِلُ بِهَا ٱلَّذِينَ لَا يُؤۡمِنُونَ\nT;0;42:18:0:بِهَاۖ وَٱلَّذِينَ ءَامَنُواْ مُشۡفِقُونَ مِنۡهَا وَيَعۡلَمُونَ أَنَّهَا ٱلۡحَقُّۗ\nT;0;42:18:2:أَلَآ إِنَّ ٱلَّذِينَ يُمَارُونَ فِي ٱلسَّاعَةِ لَفِي ضَلَٰلِۭ بَعِيدٍ\nT;0;42:19:3:ٱللَّهُ لَطِيفُۢ بِعِبَادِهِۦ يَرۡزُقُ مَن يَشَآءُۖ وَهُوَ ٱلۡقَوِيُّ ٱلۡعَزِيزُ\nT;0;42:20:1:مَن كَانَ يُرِيدُ حَرۡثَ ٱلۡأٓخِرَةِ نَزِدۡ لَهُۥ فِي حَرۡثِهِۦۖ وَمَن\nT;0;42:20:0:كَانَ يُرِيدُ حَرۡثَ ٱلدُّنۡيَا نُؤۡتِهِۦ مِنۡهَا وَمَا لَهُۥ فِي ٱلۡأٓخِرَةِ\nT;0;42:20:2:مِن نَّصِيبٍ¦42:21:1:أَمۡ لَهُمۡ شُرَكَٰٓؤُاْ شَرَعُواْ لَهُم مِّنَ ٱلدِّينِ\nT;0;42:21:0:مَا لَمۡ يَأۡذَنۢ بِهِ ٱللَّهُۚ وَلَوۡلَا كَلِمَةُ ٱلۡفَصۡلِ لَقُضِيَ بَيۡنَهُمۡۗ\nT;0;42:21:2:وَإِنَّ ٱلظَّٰلِمِينَ لَهُمۡ عَذَابٌ أَلِيمࣱ¦42:22:1:تَرَى ٱلظَّٰلِمِينَ\nT;0;42:22:0:مُشۡفِقِينَ مِمَّا كَسَبُواْ وَهُوَ وَاقِعُۢ بِهِمۡۗ وَٱلَّذِينَ\nT;0;42:22:0:ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ فِي رَوۡضَاتِ ٱلۡجَنَّاتِۖ لَهُم\nT;0;42:22:2:مَّا يَشَآءُونَ عِندَ رَبِّهِمۡۚ ذَٰلِكَ هُوَ ٱلۡفَضۡلُ ٱلۡكَبِيرُ',
  '25;49;1;195\nT;0;42:23:1:ذَٰلِكَ ٱلَّذِي يُبَشِّرُ ٱللَّهُ عِبَادَهُ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِۗ\nT;0;42:23:0:قُل لَّآ أَسۡـَٔلُكُمۡ عَلَيۡهِ أَجۡرًا إِلَّا ٱلۡمَوَدَّةَ فِي ٱلۡقُرۡبَىٰۗ وَمَن يَقۡتَرِفۡ\nT;0;42:23:2:حَسَنَةࣰ نَّزِدۡ لَهُۥ فِيهَا حُسۡنًاۚ إِنَّ ٱللَّهَ غَفُورࣱ شَكُورٌ¦42:24:1:أَمۡ يَقُولُونَ\nT;0;42:24:0:ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبࣰاۖ فَإِن يَشَإِ ٱللَّهُ يَخۡتِمۡ عَلَىٰ قَلۡبِكَۗ وَيَمۡحُ ٱللَّهُ\nT;0;42:24:2:ٱلۡبَٰطِلَ وَيُحِقُّ ٱلۡحَقَّ بِكَلِمَٰتِهِۦٓۚ إِنَّهُۥ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ\nT;0;42:25:1:وَهُوَ ٱلَّذِي يَقۡبَلُ ٱلتَّوۡبَةَ عَنۡ عِبَادِهِۦ وَيَعۡفُواْ عَنِ ٱلسَّيِّـَٔاتِ\nT;0;42:25:2:وَيَعۡلَمُ مَا تَفۡعَلُونَ¦42:26:1:وَيَسۡتَجِيبُ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ\nT;0;42:26:0:ٱلصَّٰلِحَٰتِ وَيَزِيدُهُم مِّن فَضۡلِهِۦۚ وَٱلۡكَٰفِرُونَ لَهُمۡ عَذَابࣱ\nT;0;42:26:2:شَدِيدࣱ¦42:27:1:۞ وَلَوۡ بَسَطَ ٱللَّهُ ٱلرِّزۡقَ لِعِبَادِهِۦ لَبَغَوۡاْ فِي ٱلۡأَرۡضِ\nT;0;42:27:2:وَلَٰكِن يُنَزِّلُ بِقَدَرࣲ مَّا يَشَآءُۚ إِنَّهُۥ بِعِبَادِهِۦ خَبِيرُۢ بَصِيرࣱ¦42:28:1:وَهُوَ ٱلَّذِي\nT;0;42:28:2:يُنَزِّلُ ٱلۡغَيۡثَ مِنۢ بَعۡدِ مَا قَنَطُواْ وَيَنشُرُ رَحۡمَتَهُۥۚ وَهُوَ ٱلۡوَلِيُّ ٱلۡحَمِيدُ\nT;0;42:29:1:وَمِنۡ ءَايَٰتِهِۦ خَلۡقُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا بَثَّ فِيهِمَا مِن دَآبَّةࣲۚ\nT;0;42:29:2:وَهُوَ عَلَىٰ جَمۡعِهِمۡ إِذَا يَشَآءُ قَدِيرࣱ¦42:30:1:وَمَآ أَصَٰبَكُم مِّن مُّصِيبَةࣲ فَبِمَا\nT;0;42:30:2:كَسَبَتۡ أَيۡدِيكُمۡ وَيَعۡفُواْ عَن كَثِيرࣲ¦42:31:1:وَمَآ أَنتُم بِمُعۡجِزِينَ\nT;0;42:31:2:فِي ٱلۡأَرۡضِۖ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِن وَلِيࣲّ وَلَا نَصِيرࣲ',
  '25;49;2;\nT;0;42:32:3:وَمِنۡ ءَايَٰتِهِ ٱلۡجَوَارِ فِي ٱلۡبَحۡرِ كَٱلۡأَعۡلَٰمِ¦42:33:1:إِن يَشَأۡ يُسۡكِنِ ٱلرِّيحَ\nT;0;42:33:2:فَيَظۡلَلۡنَ رَوَاكِدَ عَلَىٰ ظَهۡرِهِۦٓۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتࣲ لِّكُلِّ صَبَّارࣲ شَكُورٍ\nT;0;42:34:3:أَوۡ يُوبِقۡهُنَّ بِمَا كَسَبُواْ وَيَعۡفُ عَن كَثِيرࣲ¦42:35:1:وَيَعۡلَمَ ٱلَّذِينَ\nT;0;42:35:2:يُجَٰدِلُونَ فِيٓ ءَايَٰتِنَا مَا لَهُم مِّن مَّحِيصࣲ¦42:36:1:فَمَآ أُوتِيتُم مِّن شَيۡءࣲ فَمَتَٰعُ\nT;0;42:36:0:ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۚ وَمَا عِندَ ٱللَّهِ خَيۡرࣱ وَأَبۡقَىٰ لِلَّذِينَ ءَامَنُواْ وَعَلَىٰ رَبِّهِمۡ\nT;0;42:36:2:يَتَوَكَّلُونَ¦42:37:1:وَٱلَّذِينَ يَجۡتَنِبُونَ كَبَٰٓئِرَ ٱلۡإِثۡمِ وَٱلۡفَوَٰحِشَ وَإِذَا مَا\nT;0;42:37:2:غَضِبُواْ هُمۡ يَغۡفِرُونَ¦42:38:1:وَٱلَّذِينَ ٱسۡتَجَابُواْ لِرَبِّهِمۡ وَأَقَامُواْ ٱلصَّلَوٰةَ\nT;0;42:38:2:وَأَمۡرُهُمۡ شُورَىٰ بَيۡنَهُمۡ وَمِمَّا رَزَقۡنَٰهُمۡ يُنفِقُونَ¦42:39:1:وَٱلَّذِينَ إِذَآ أَصَابَهُمُ\nT;0;42:39:2:ٱلۡبَغۡيُ هُمۡ يَنتَصِرُونَ¦42:40:1:وَجَزَٰٓؤُاْ سَيِّئَةࣲ سَيِّئَةࣱ مِّثۡلُهَاۖ فَمَنۡ عَفَا\nT;0;42:40:2:وَأَصۡلَحَ فَأَجۡرُهُۥ عَلَى ٱللَّهِۚ إِنَّهُۥ لَا يُحِبُّ ٱلظَّٰلِمِينَ¦42:41:1:وَلَمَنِ ٱنتَصَرَ\nT;0;42:41:2:بَعۡدَ ظُلۡمِهِۦ فَأُوْلَٰٓئِكَ مَا عَلَيۡهِم مِّن سَبِيلٍ¦42:42:1:إِنَّمَا ٱلسَّبِيلُ عَلَى\nT;0;42:42:0:ٱلَّذِينَ يَظۡلِمُونَ ٱلنَّاسَ وَيَبۡغُونَ فِي ٱلۡأَرۡضِ بِغَيۡرِ ٱلۡحَقِّۚ أُوْلَٰٓئِكَ\nT;0;42:42:2:لَهُمۡ عَذَابٌ أَلِيمࣱ¦42:43:1:وَلَمَن صَبَرَ وَغَفَرَ إِنَّ ذَٰلِكَ لَمِنۡ عَزۡمِ\nT;0;42:43:2:ٱلۡأُمُورِ¦42:44:1:وَمَن يُضۡلِلِ ٱللَّهُ فَمَا لَهُۥ مِن وَلِيࣲّ مِّنۢ بَعۡدِهِۦۗ وَتَرَى\nT;0;42:44:2:ٱلظَّٰلِمِينَ لَمَّا رَأَوُاْ ٱلۡعَذَابَ يَقُولُونَ هَلۡ إِلَىٰ مَرَدࣲّ مِّن سَبِيلࣲ',
  '25;49;2;196\nT;0;42:45:1:وَتَرَىٰهُمۡ يُعۡرَضُونَ عَلَيۡهَا خَٰشِعِينَ مِنَ ٱلذُّلِّ يَنظُرُونَ\nT;0;42:45:0:مِن طَرۡفٍ خَفِيࣲّۗ وَقَالَ ٱلَّذِينَ ءَامَنُوٓاْ إِنَّ ٱلۡخَٰسِرِينَ ٱلَّذِينَ\nT;0;42:45:0:خَسِرُوٓاْ أَنفُسَهُمۡ وَأَهۡلِيهِمۡ يَوۡمَ ٱلۡقِيَٰمَةِۗ أَلَآ إِنَّ ٱلظَّٰلِمِينَ\nT;0;42:45:2:فِي عَذَابࣲ مُّقِيمࣲ¦42:46:1:وَمَا كَانَ لَهُم مِّنۡ أَوۡلِيَآءَ يَنصُرُونَهُم\nT;0;42:46:2:مِّن دُونِ ٱللَّهِۗ وَمَن يُضۡلِلِ ٱللَّهُ فَمَا لَهُۥ مِن سَبِيلٍ¦42:47:1:ٱسۡتَجِيبُواْ\nT;0;42:47:0:لِرَبِّكُم مِّن قَبۡلِ أَن يَأۡتِيَ يَوۡمࣱ لَّا مَرَدَّ لَهُۥ مِنَ ٱللَّهِۚ مَا لَكُم\nT;0;42:47:2:مِّن مَّلۡجَإࣲ يَوۡمَئِذࣲ وَمَا لَكُم مِّن نَّكِيرࣲ¦42:48:1:فَإِنۡ أَعۡرَضُواْ\nT;0;42:48:0:فَمَآ أَرۡسَلۡنَٰكَ عَلَيۡهِمۡ حَفِيظًاۖ إِنۡ عَلَيۡكَ إِلَّا ٱلۡبَلَٰغُۗ وَإِنَّآ إِذَآ\nT;0;42:48:0:أَذَقۡنَا ٱلۡإِنسَٰنَ مِنَّا رَحۡمَةࣰ فَرِحَ بِهَاۖ وَإِن تُصِبۡهُمۡ سَيِّئَةُۢ\nT;0;42:48:2:بِمَا قَدَّمَتۡ أَيۡدِيهِمۡ فَإِنَّ ٱلۡإِنسَٰنَ كَفُورࣱ¦42:49:1:لِّلَّهِ مُلۡكُ\nT;0;42:49:0:ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ يَخۡلُقُ مَا يَشَآءُۚ يَهَبُ لِمَن يَشَآءُ إِنَٰثࣰا\nT;0;42:49:2:وَيَهَبُ لِمَن يَشَآءُ ٱلذُّكُورَ¦42:50:1:أَوۡ يُزَوِّجُهُمۡ ذُكۡرَانࣰا وَإِنَٰثࣰاۖ\nT;0;42:50:2:وَيَجۡعَلُ مَن يَشَآءُ عَقِيمًاۚ إِنَّهُۥ عَلِيمࣱ قَدِيرࣱ¦42:51:1:۞ وَمَا كَانَ\nT;0;42:51:0:لِبَشَرٍ أَن يُكَلِّمَهُ ٱللَّهُ إِلَّا وَحۡيًا أَوۡ مِن وَرَآيِٕ حِجَابٍ أَوۡ يُرۡسِلَ\nT;0;42:51:2:رَسُولࣰا فَيُوحِيَ بِإِذۡنِهِۦ مَا يَشَآءُۚ إِنَّهُۥ عَلِيٌّ حَكِيمࣱ',
  '25;49;3;\nT;0;42:52:1:وَكَذَٰلِكَ أَوۡحَيۡنَآ إِلَيۡكَ رُوحࣰا مِّنۡ أَمۡرِنَاۚ مَا كُنتَ تَدۡرِي مَا ٱلۡكِتَٰبُ\nT;0;42:52:0:وَلَا ٱلۡإِيمَٰنُ وَلَٰكِن جَعَلۡنَٰهُ نُورࣰا نَّهۡدِي بِهِۦ مَن نَّشَآءُ مِنۡ عِبَادِنَاۚ\nT;0;42:52:2:وَإِنَّكَ لَتَهۡدِيٓ إِلَىٰ صِرَٰطࣲ مُّسۡتَقِيمࣲ¦42:53:1:صِرَٰطِ ٱللَّهِ ٱلَّذِي لَهُۥ\nT;2;42:53:2:مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۗ أَلَآ إِلَى ٱللَّهِ تَصِيرُ ٱلۡأُمُورُ\nH;43\nB;43\nT;0;43:1:3:حمٓ¦43:2:3:وَٱلۡكِتَٰبِ ٱلۡمُبِينِ¦43:3:1:إِنَّا جَعَلۡنَٰهُ قُرۡءَٰنًا عَرَبِيࣰّا\nT;0;43:3:2:لَّعَلَّكُمۡ تَعۡقِلُونَ¦43:4:1:وَإِنَّهُۥ فِيٓ أُمِّ ٱلۡكِتَٰبِ لَدَيۡنَا\nT;0;43:4:2:لَعَلِيٌّ حَكِيمٌ¦43:5:1:أَفَنَضۡرِبُ عَنكُمُ ٱلذِّكۡرَ صَفۡحًا\nT;0;43:5:2:أَن كُنتُمۡ قَوۡمࣰا مُّسۡرِفِينَ¦43:6:1:وَكَمۡ أَرۡسَلۡنَا مِن نَّبِيࣲّ فِي\nT;0;43:6:2:ٱلۡأَوَّلِينَ¦43:7:3:وَمَا يَأۡتِيهِم مِّن نَّبِيٍّ إِلَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ\nT;0;43:8:3:فَأَهۡلَكۡنَآ أَشَدَّ مِنۡهُم بَطۡشࣰا وَمَضَىٰ مَثَلُ ٱلۡأَوَّلِينَ\nT;0;43:9:1:وَلَئِن سَأَلۡتَهُم مَّنۡ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ لَيَقُولُنَّ\nT;0;43:9:2:خَلَقَهُنَّ ٱلۡعَزِيزُ ٱلۡعَلِيمُ¦43:10:1:ٱلَّذِي جَعَلَ لَكُمُ ٱلۡأَرۡضَ\nT;0;43:10:2:مَهۡدࣰا وَجَعَلَ لَكُمۡ فِيهَا سُبُلࣰا لَّعَلَّكُمۡ تَهۡتَدُونَ',
  '25;49;3;\nT;0;43:11:1:وَٱلَّذِي نَزَّلَ مِنَ ٱلسَّمَآءِ مَآءَۢ بِقَدَرࣲ فَأَنشَرۡنَا بِهِۦ بَلۡدَةࣰ مَّيۡتࣰاۚ\nT;0;43:11:2:كَذَٰلِكَ تُخۡرَجُونَ¦43:12:1:وَٱلَّذِي خَلَقَ ٱلۡأَزۡوَٰجَ كُلَّهَا وَجَعَلَ\nT;0;43:12:2:لَكُم مِّنَ ٱلۡفُلۡكِ وَٱلۡأَنۡعَٰمِ مَا تَرۡكَبُونَ¦43:13:1:لِتَسۡتَوُۥاْ عَلَىٰ ظُهُورِهِۦ\nT;0;43:13:0:ثُمَّ تَذۡكُرُواْ نِعۡمَةَ رَبِّكُمۡ إِذَا ٱسۡتَوَيۡتُمۡ عَلَيۡهِ وَتَقُولُواْ سُبۡحَٰنَ\nT;0;43:13:2:ٱلَّذِي سَخَّرَ لَنَا هَٰذَا وَمَا كُنَّا لَهُۥ مُقۡرِنِينَ¦43:14:1:وَإِنَّآ إِلَىٰ رَبِّنَا\nT;0;43:14:2:لَمُنقَلِبُونَ¦43:15:1:وَجَعَلُواْ لَهُۥ مِنۡ عِبَادِهِۦ جُزۡءًاۚ إِنَّ ٱلۡإِنسَٰنَ\nT;0;43:15:2:لَكَفُورࣱ مُّبِينٌ¦43:16:1:أَمِ ٱتَّخَذَ مِمَّا يَخۡلُقُ بَنَاتࣲ وَأَصۡفَىٰكُم\nT;0;43:16:2:بِٱلۡبَنِينَ¦43:17:1:وَإِذَا بُشِّرَ أَحَدُهُم بِمَا ضَرَبَ لِلرَّحۡمَٰنِ مَثَلࣰا\nT;0;43:17:2:ظَلَّ وَجۡهُهُۥ مُسۡوَدࣰّا وَهُوَ كَظِيمٌ¦43:18:1:أَوَمَن يُنَشَّؤُاْ فِي\nT;0;43:18:2:ٱلۡحِلۡيَةِ وَهُوَ فِي ٱلۡخِصَامِ غَيۡرُ مُبِينࣲ¦43:19:1:وَجَعَلُواْ ٱلۡمَلَٰٓئِكَةَ\nT;0;43:19:0:ٱلَّذِينَ هُمۡ عِبَٰدُ ٱلرَّحۡمَٰنِ إِنَٰثًاۚ أَشَهِدُواْ خَلۡقَهُمۡۚ سَتُكۡتَبُ\nT;0;43:19:2:شَهَٰدَتُهُمۡ وَيُسۡـَٔلُونَ¦43:20:1:وَقَالُواْ لَوۡ شَآءَ ٱلرَّحۡمَٰنُ مَا عَبَدۡنَٰهُمۗ\nT;0;43:20:2:مَّا لَهُم بِذَٰلِكَ مِنۡ عِلۡمٍۖ إِنۡ هُمۡ إِلَّا يَخۡرُصُونَ¦43:21:1:أَمۡ ءَاتَيۡنَٰهُمۡ\nT;0;43:21:2:كِتَٰبࣰا مِّن قَبۡلِهِۦ فَهُم بِهِۦ مُسۡتَمۡسِكُونَ¦43:22:1:بَلۡ قَالُوٓاْ إِنَّا\nT;0;43:22:2:وَجَدۡنَآ ءَابَآءَنَا عَلَىٰٓ أُمَّةࣲ وَإِنَّا عَلَىٰٓ ءَاثَٰرِهِم مُّهۡتَدُونَ',
  '25;49;3;197\nT;0;43:23:1:وَكَذَٰلِكَ مَآ أَرۡسَلۡنَا مِن قَبۡلِكَ فِي قَرۡيَةࣲ مِّن نَّذِيرٍ إِلَّا قَالَ مُتۡرَفُوهَآ\nT;0;43:23:2:إِنَّا وَجَدۡنَآ ءَابَآءَنَا عَلَىٰٓ أُمَّةࣲ وَإِنَّا عَلَىٰٓ ءَاثَٰرِهِم مُّقۡتَدُونَ\nT;0;43:24:1:۞ قَٰلَ أَوَلَوۡ جِئۡتُكُم بِأَهۡدَىٰ مِمَّا وَجَدتُّمۡ عَلَيۡهِ ءَابَآءَكُمۡۖ قَالُوٓاْ\nT;0;43:24:2:إِنَّا بِمَآ أُرۡسِلۡتُم بِهِۦ كَٰفِرُونَ¦43:25:1:فَٱنتَقَمۡنَا مِنۡهُمۡۖ فَٱنظُرۡ كَيۡفَ\nT;0;43:25:2:كَانَ عَٰقِبَةُ ٱلۡمُكَذِّبِينَ¦43:26:1:وَإِذۡ قَالَ إِبۡرَٰهِيمُ لِأَبِيهِ وَقَوۡمِهِۦٓ إِنَّنِي\nT;0;43:26:2:بَرَآءࣱ مِّمَّا تَعۡبُدُونَ¦43:27:3:إِلَّا ٱلَّذِي فَطَرَنِي فَإِنَّهُۥ سَيَهۡدِينِ\nT;0;43:28:3:وَجَعَلَهَا كَلِمَةَۢ بَاقِيَةࣰ فِي عَقِبِهِۦ لَعَلَّهُمۡ يَرۡجِعُونَ¦43:29:1:بَلۡ\nT;0;43:29:2:مَتَّعۡتُ هَٰٓؤُلَآءِ وَءَابَآءَهُمۡ حَتَّىٰ جَآءَهُمُ ٱلۡحَقُّ وَرَسُولࣱ مُّبِينࣱ\nT;0;43:30:3:وَلَمَّا جَآءَهُمُ ٱلۡحَقُّ قَالُواْ هَٰذَا سِحۡرࣱ وَإِنَّا بِهِۦ كَٰفِرُونَ¦43:31:1:وَقَالُواْ\nT;0;43:31:2:لَوۡلَا نُزِّلَ هَٰذَا ٱلۡقُرۡءَانُ عَلَىٰ رَجُلࣲ مِّنَ ٱلۡقَرۡيَتَيۡنِ عَظِيمٍ¦43:32:1:أَهُمۡ\nT;0;43:32:0:يَقۡسِمُونَ رَحۡمَتَ رَبِّكَۚ نَحۡنُ قَسَمۡنَا بَيۡنَهُم مَّعِيشَتَهُمۡ فِي ٱلۡحَيَوٰةِ\nT;0;43:32:0:ٱلدُّنۡيَاۚ وَرَفَعۡنَا بَعۡضَهُمۡ فَوۡقَ بَعۡضࣲ دَرَجَٰتࣲ لِّيَتَّخِذَ بَعۡضُهُم\nT;0;43:32:2:بَعۡضࣰا سُخۡرِيࣰّاۗ وَرَحۡمَتُ رَبِّكَ خَيۡرࣱ مِّمَّا يَجۡمَعُونَ¦43:33:1:وَلَوۡلَآ\nT;0;43:33:0:أَن يَكُونَ ٱلنَّاسُ أُمَّةࣰ وَٰحِدَةࣰ لَّجَعَلۡنَا لِمَن يَكۡفُرُ بِٱلرَّحۡمَٰنِ\nT;0;43:33:2:لِبُيُوتِهِمۡ سُقُفࣰا مِّن فِضَّةࣲ وَمَعَارِجَ عَلَيۡهَا يَظۡهَرُونَ',
  '25;50;0;\nT;0;43:34:3:وَلِبُيُوتِهِمۡ أَبۡوَٰبࣰا وَسُرُرًا عَلَيۡهَا يَتَّكِـُٔونَ¦43:35:1:وَزُخۡرُفࣰاۚ وَإِن\nT;0;43:35:0:كُلُّ ذَٰلِكَ لَمَّا مَتَٰعُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۚ وَٱلۡأٓخِرَةُ عِندَ رَبِّكَ\nT;0;43:35:2:لِلۡمُتَّقِينَ¦43:36:1:وَمَن يَعۡشُ عَن ذِكۡرِ ٱلرَّحۡمَٰنِ نُقَيِّضۡ لَهُۥ شَيۡطَٰنࣰا\nT;0;43:36:2:فَهُوَ لَهُۥ قَرِينࣱ¦43:37:1:وَإِنَّهُمۡ لَيَصُدُّونَهُمۡ عَنِ ٱلسَّبِيلِ وَيَحۡسَبُونَ\nT;0;43:37:2:أَنَّهُم مُّهۡتَدُونَ¦43:38:1:حَتَّىٰٓ إِذَا جَآءَنَا قَالَ يَٰلَيۡتَ بَيۡنِي وَبَيۡنَكَ\nT;0;43:38:2:بُعۡدَ ٱلۡمَشۡرِقَيۡنِ فَبِئۡسَ ٱلۡقَرِينُ¦43:39:1:وَلَن يَنفَعَكُمُ ٱلۡيَوۡمَ\nT;0;43:39:2:إِذ ظَّلَمۡتُمۡ أَنَّكُمۡ فِي ٱلۡعَذَابِ مُشۡتَرِكُونَ¦43:40:1:أَفَأَنتَ تُسۡمِعُ\nT;0;43:40:2:ٱلصُّمَّ أَوۡ تَهۡدِي ٱلۡعُمۡيَ وَمَن كَانَ فِي ضَلَٰلࣲ مُّبِينࣲ¦43:41:1:فَإِمَّا\nT;0;43:41:2:نَذۡهَبَنَّ بِكَ فَإِنَّا مِنۡهُم مُّنتَقِمُونَ¦43:42:1:أَوۡ نُرِيَنَّكَ ٱلَّذِي\nT;0;43:42:2:وَعَدۡنَٰهُمۡ فَإِنَّا عَلَيۡهِم مُّقۡتَدِرُونَ¦43:43:1:فَٱسۡتَمۡسِكۡ بِٱلَّذِيٓ أُوحِيَ\nT;0;43:43:2:إِلَيۡكَۖ إِنَّكَ عَلَىٰ صِرَٰطࣲ مُّسۡتَقِيمࣲ¦43:44:1:وَإِنَّهُۥ لَذِكۡرࣱ لَّكَ وَلِقَوۡمِكَۖ\nT;0;43:44:2:وَسَوۡفَ تُسۡـَٔلُونَ¦43:45:1:وَسۡـَٔلۡ مَنۡ أَرۡسَلۡنَا مِن قَبۡلِكَ مِن رُّسُلِنَآ\nT;0;43:45:2:أَجَعَلۡنَا مِن دُونِ ٱلرَّحۡمَٰنِ ءَالِهَةࣰ يُعۡبَدُونَ¦43:46:1:وَلَقَدۡ أَرۡسَلۡنَا\nT;0;43:46:0:مُوسَىٰ بِـَٔايَٰتِنَآ إِلَىٰ فِرۡعَوۡنَ وَمَلَإِيْهِۦ فَقَالَ إِنِّي رَسُولُ رَبِّ\nT;0;43:46:2:ٱلۡعَٰلَمِينَ¦43:47:3:فَلَمَّا جَآءَهُم بِـَٔايَٰتِنَآ إِذَا هُم مِّنۡهَا يَضۡحَكُونَ',
  '25;50;0;198\nT;0;43:48:1:وَمَا نُرِيهِم مِّنۡ ءَايَةٍ إِلَّا هِيَ أَكۡبَرُ مِنۡ أُخۡتِهَاۖ وَأَخَذۡنَٰهُم\nT;0;43:48:2:بِٱلۡعَذَابِ لَعَلَّهُمۡ يَرۡجِعُونَ¦43:49:1:وَقَالُواْ يَٰٓأَيُّهَ ٱلسَّاحِرُ ٱدۡعُ لَنَا\nT;0;43:49:2:رَبَّكَ بِمَا عَهِدَ عِندَكَ إِنَّنَا لَمُهۡتَدُونَ¦43:50:1:فَلَمَّا كَشَفۡنَا\nT;0;43:50:2:عَنۡهُمُ ٱلۡعَذَابَ إِذَا هُمۡ يَنكُثُونَ¦43:51:1:وَنَادَىٰ فِرۡعَوۡنُ فِي قَوۡمِهِۦ\nT;0;43:51:0:قَالَ يَٰقَوۡمِ أَلَيۡسَ لِي مُلۡكُ مِصۡرَ وَهَٰذِهِ ٱلۡأَنۡهَٰرُ تَجۡرِي مِن\nT;0;43:51:2:تَحۡتِيٓۚ أَفَلَا تُبۡصِرُونَ¦43:52:1:أَمۡ أَنَا۠ خَيۡرࣱ مِّنۡ هَٰذَا ٱلَّذِي هُوَ مَهِينࣱ\nT;0;43:52:2:وَلَا يَكَادُ يُبِينُ¦43:53:1:فَلَوۡلَآ أُلۡقِيَ عَلَيۡهِ أَسۡوِرَةࣱ مِّن ذَهَبٍ أَوۡ جَآءَ\nT;0;43:53:2:مَعَهُ ٱلۡمَلَٰٓئِكَةُ مُقۡتَرِنِينَ¦43:54:1:فَٱسۡتَخَفَّ قَوۡمَهُۥ\nT;0;43:54:2:فَأَطَاعُوهُۚ إِنَّهُمۡ كَانُواْ قَوۡمࣰا فَٰسِقِينَ¦43:55:1:فَلَمَّآ ءَاسَفُونَا\nT;0;43:55:2:ٱنتَقَمۡنَا مِنۡهُمۡ فَأَغۡرَقۡنَٰهُمۡ أَجۡمَعِينَ¦43:56:1:فَجَعَلۡنَٰهُمۡ\nT;0;43:56:2:سَلَفࣰا وَمَثَلࣰا لِّلۡأٓخِرِينَ¦43:57:1:۞ وَلَمَّا ضُرِبَ ٱبۡنُ مَرۡيَمَ مَثَلًا\nT;0;43:57:2:إِذَا قَوۡمُكَ مِنۡهُ يَصِدُّونَ¦43:58:1:وَقَالُوٓاْ ءَأَٰلِهَتُنَا خَيۡرٌ أَمۡ\nT;0;43:58:2:هُوَۚ مَا ضَرَبُوهُ لَكَ إِلَّا جَدَلَۢاۚ بَلۡ هُمۡ قَوۡمٌ خَصِمُونَ¦43:59:1:إِنۡ هُوَ\nT;0;43:59:2:إِلَّا عَبۡدٌ أَنۡعَمۡنَا عَلَيۡهِ وَجَعَلۡنَٰهُ مَثَلࣰا لِّبَنِيٓ إِسۡرَٰٓءِيلَ\nT;0;43:60:3:وَلَوۡ نَشَآءُ لَجَعَلۡنَا مِنكُم مَّلَٰٓئِكَةࣰ فِي ٱلۡأَرۡضِ يَخۡلُفُونَ',
  '25;50;1;\nT;0;43:61:1:وَإِنَّهُۥ لَعِلۡمࣱ لِّلسَّاعَةِ فَلَا تَمۡتَرُنَّ بِهَا وَٱتَّبِعُونِۚ هَٰذَا صِرَٰطࣱ\nT;0;43:61:2:مُّسۡتَقِيمࣱ¦43:62:3:وَلَا يَصُدَّنَّكُمُ ٱلشَّيۡطَٰنُۖ إِنَّهُۥ لَكُمۡ عَدُوࣱّ مُّبِينࣱ\nT;0;43:63:1:وَلَمَّا جَآءَ عِيسَىٰ بِٱلۡبَيِّنَٰتِ قَالَ قَدۡ جِئۡتُكُم بِٱلۡحِكۡمَةِ\nT;0;43:63:2:وَلِأُبَيِّنَ لَكُم بَعۡضَ ٱلَّذِي تَخۡتَلِفُونَ فِيهِۖ فَٱتَّقُواْ ٱللَّهَ وَأَطِيعُونِ\nT;0;43:64:3:إِنَّ ٱللَّهَ هُوَ رَبِّي وَرَبُّكُمۡ فَٱعۡبُدُوهُۚ هَٰذَا صِرَٰطࣱ مُّسۡتَقِيمࣱ\nT;0;43:65:1:فَٱخۡتَلَفَ ٱلۡأَحۡزَابُ مِنۢ بَيۡنِهِمۡۖ فَوَيۡلࣱ لِّلَّذِينَ ظَلَمُواْ\nT;0;43:65:2:مِنۡ عَذَابِ يَوۡمٍ أَلِيمٍ¦43:66:1:هَلۡ يَنظُرُونَ إِلَّا ٱلسَّاعَةَ أَن\nT;0;43:66:2:تَأۡتِيَهُم بَغۡتَةࣰ وَهُمۡ لَا يَشۡعُرُونَ¦43:67:1:ٱلۡأَخِلَّآءُ يَوۡمَئِذِۭ\nT;0;43:67:2:بَعۡضُهُمۡ لِبَعۡضٍ عَدُوٌّ إِلَّا ٱلۡمُتَّقِينَ¦43:68:1:يَٰعِبَادِ لَا خَوۡفٌ\nT;0;43:68:2:عَلَيۡكُمُ ٱلۡيَوۡمَ وَلَآ أَنتُمۡ تَحۡزَنُونَ¦43:69:1:ٱلَّذِينَ ءَامَنُواْ بِـَٔايَٰتِنَا\nT;0;43:69:2:وَكَانُواْ مُسۡلِمِينَ¦43:70:1:ٱدۡخُلُواْ ٱلۡجَنَّةَ أَنتُمۡ وَأَزۡوَٰجُكُمۡ\nT;0;43:70:2:تُحۡبَرُونَ¦43:71:1:يُطَافُ عَلَيۡهِم بِصِحَافࣲ مِّن ذَهَبࣲ وَأَكۡوَابࣲۖ\nT;0;43:71:0:وَفِيهَا مَا تَشۡتَهِيهِ ٱلۡأَنفُسُ وَتَلَذُّ ٱلۡأَعۡيُنُۖ وَأَنتُمۡ فِيهَا\nT;0;43:71:2:خَٰلِدُونَ¦43:72:1:وَتِلۡكَ ٱلۡجَنَّةُ ٱلَّتِيٓ أُورِثۡتُمُوهَا بِمَا كُنتُمۡ\nT;0;43:72:2:تَعۡمَلُونَ¦43:73:3:لَكُمۡ فِيهَا فَٰكِهَةࣱ كَثِيرَةࣱ مِّنۡهَا تَأۡكُلُونَ',
  '25;50;1;\nT;0;43:74:3:إِنَّ ٱلۡمُجۡرِمِينَ فِي عَذَابِ جَهَنَّمَ خَٰلِدُونَ¦43:75:1:لَا يُفَتَّرُ عَنۡهُمۡ وَهُمۡ\nT;0;43:75:2:فِيهِ مُبۡلِسُونَ¦43:76:3:وَمَا ظَلَمۡنَٰهُمۡ وَلَٰكِن كَانُواْ هُمُ ٱلظَّٰلِمِينَ\nT;0;43:77:3:وَنَادَوۡاْ يَٰمَٰلِكُ لِيَقۡضِ عَلَيۡنَا رَبُّكَۖ قَالَ إِنَّكُم مَّٰكِثُونَ¦43:78:1:لَقَدۡ\nT;0;43:78:2:جِئۡنَٰكُم بِٱلۡحَقِّ وَلَٰكِنَّ أَكۡثَرَكُمۡ لِلۡحَقِّ كَٰرِهُونَ¦43:79:1:أَمۡ أَبۡرَمُوٓاْ أَمۡرࣰا\nT;0;43:79:2:فَإِنَّا مُبۡرِمُونَ¦43:80:1:أَمۡ يَحۡسَبُونَ أَنَّا لَا نَسۡمَعُ سِرَّهُمۡ وَنَجۡوَىٰهُمۚ بَلَىٰ\nT;0;43:80:2:وَرُسُلُنَا لَدَيۡهِمۡ يَكۡتُبُونَ¦43:81:1:قُلۡ إِن كَانَ لِلرَّحۡمَٰنِ وَلَدࣱ فَأَنَا۠ أَوَّلُ\nT;0;43:81:2:ٱلۡعَٰبِدِينَ¦43:82:1:سُبۡحَٰنَ رَبِّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ رَبِّ ٱلۡعَرۡشِ\nT;0;43:82:2:عَمَّا يَصِفُونَ¦43:83:1:فَذَرۡهُمۡ يَخُوضُواْ وَيَلۡعَبُواْ حَتَّىٰ يُلَٰقُواْ يَوۡمَهُمُ\nT;0;43:83:2:ٱلَّذِي يُوعَدُونَ¦43:84:1:وَهُوَ ٱلَّذِي فِي ٱلسَّمَآءِ إِلَٰهࣱ وَفِي ٱلۡأَرۡضِ\nT;0;43:84:2:إِلَٰهࣱۚ وَهُوَ ٱلۡحَكِيمُ ٱلۡعَلِيمُ¦43:85:1:وَتَبَارَكَ ٱلَّذِي لَهُۥ مُلۡكُ ٱلسَّمَٰوَٰتِ\nT;0;43:85:2:وَٱلۡأَرۡضِ وَمَا بَيۡنَهُمَا وَعِندَهُۥ عِلۡمُ ٱلسَّاعَةِ وَإِلَيۡهِ تُرۡجَعُونَ\nT;0;43:86:1:وَلَا يَمۡلِكُ ٱلَّذِينَ يَدۡعُونَ مِن دُونِهِ ٱلشَّفَٰعَةَ إِلَّا مَن\nT;0;43:86:2:شَهِدَ بِٱلۡحَقِّ وَهُمۡ يَعۡلَمُونَ¦43:87:1:وَلَئِن سَأَلۡتَهُم مَّنۡ خَلَقَهُمۡ\nT;0;43:87:2:لَيَقُولُنَّ ٱللَّهُۖ فَأَنَّىٰ يُؤۡفَكُونَ¦43:88:1:وَقِيلِهِۦ يَٰرَبِّ إِنَّ هَٰٓؤُلَآءِ قَوۡمࣱ\nT;2;43:88:2:لَّا يُؤۡمِنُونَ¦43:89:3:فَٱصۡفَحۡ عَنۡهُمۡ وَقُلۡ سَلَٰمࣱۚ فَسَوۡفَ يَعۡلَمُونَ',
  '25;50;1;199\nH;44\nB;44\nT;0;44:1:3:حمٓ¦44:2:3:وَٱلۡكِتَٰبِ ٱلۡمُبِينِ¦44:3:1:إِنَّآ أَنزَلۡنَٰهُ فِي لَيۡلَةࣲ مُّبَٰرَكَةٍۚ\nT;0;44:3:2:إِنَّا كُنَّا مُنذِرِينَ¦44:4:3:فِيهَا يُفۡرَقُ كُلُّ أَمۡرٍ حَكِيمٍ¦44:5:1:أَمۡرࣰا\nT;0;44:5:2:مِّنۡ عِندِنَآۚ إِنَّا كُنَّا مُرۡسِلِينَ¦44:6:1:رَحۡمَةࣰ مِّن رَّبِّكَۚ إِنَّهُۥ هُوَ\nT;0;44:6:2:ٱلسَّمِيعُ ٱلۡعَلِيمُ¦44:7:1:رَبِّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا بَيۡنَهُمَآۖ\nT;0;44:7:2:إِن كُنتُم مُّوقِنِينَ¦44:8:1:لَآ إِلَٰهَ إِلَّا هُوَ يُحۡيِۦ وَيُمِيتُۖ رَبُّكُمۡ\nT;0;44:8:2:وَرَبُّ ءَابَآئِكُمُ ٱلۡأَوَّلِينَ¦44:9:3:بَلۡ هُمۡ فِي شَكࣲّ يَلۡعَبُونَ\nT;0;44:10:3:فَٱرۡتَقِبۡ يَوۡمَ تَأۡتِي ٱلسَّمَآءُ بِدُخَانࣲ مُّبِينࣲ¦44:11:1:يَغۡشَى ٱلنَّاسَۖ\nT;0;44:11:2:هَٰذَا عَذَابٌ أَلِيمࣱ¦44:12:3:رَّبَّنَا ٱكۡشِفۡ عَنَّا ٱلۡعَذَابَ إِنَّا مُؤۡمِنُونَ\nT;0;44:13:3:أَنَّىٰ لَهُمُ ٱلذِّكۡرَىٰ وَقَدۡ جَآءَهُمۡ رَسُولࣱ مُّبِينࣱ¦44:14:1:ثُمَّ تَوَلَّوۡاْ\nT;0;44:14:2:عَنۡهُ وَقَالُواْ مُعَلَّمࣱ مَّجۡنُونٌ¦44:15:1:إِنَّا كَاشِفُواْ ٱلۡعَذَابِ قَلِيلًاۚ إِنَّكُمۡ\nT;0;44:15:2:عَآئِدُونَ¦44:16:3:يَوۡمَ نَبۡطِشُ ٱلۡبَطۡشَةَ ٱلۡكُبۡرَىٰٓ إِنَّا مُنتَقِمُونَ\nT;0;44:17:3:۞ وَلَقَدۡ فَتَنَّا قَبۡلَهُمۡ قَوۡمَ فِرۡعَوۡنَ وَجَآءَهُمۡ رَسُولࣱ كَرِيمٌ\nT;0;44:18:3:أَنۡ أَدُّوٓاْ إِلَيَّ عِبَادَ ٱللَّهِۖ إِنِّي لَكُمۡ رَسُولٌ أَمِينࣱ',
  '25;50;2;\nT;0;44:19:3:وَأَن لَّا تَعۡلُواْ عَلَى ٱللَّهِۖ إِنِّيٓ ءَاتِيكُم بِسُلۡطَٰنࣲ مُّبِينࣲ¦44:20:1:وَإِنِّي عُذۡتُ\nT;0;44:20:2:بِرَبِّي وَرَبِّكُمۡ أَن تَرۡجُمُونِ¦44:21:3:وَإِن لَّمۡ تُؤۡمِنُواْ لِي فَٱعۡتَزِلُونِ\nT;0;44:22:3:فَدَعَا رَبَّهُۥٓ أَنَّ هَٰٓؤُلَآءِ قَوۡمࣱ مُّجۡرِمُونَ¦44:23:1:فَأَسۡرِ بِعِبَادِي لَيۡلًا إِنَّكُم\nT;0;44:23:2:مُّتَّبَعُونَ¦44:24:3:وَٱتۡرُكِ ٱلۡبَحۡرَ رَهۡوًاۖ إِنَّهُمۡ جُندࣱ مُّغۡرَقُونَ¦44:25:1:كَمۡ\nT;0;44:25:2:تَرَكُواْ مِن جَنَّٰتࣲ وَعُيُونࣲ¦44:26:3:وَزُرُوعࣲ وَمَقَامࣲ كَرِيمࣲ¦44:27:1:وَنَعۡمَةࣲ\nT;0;44:27:2:كَانُواْ فِيهَا فَٰكِهِينَ¦44:28:3:كَذَٰلِكَۖ وَأَوۡرَثۡنَٰهَا قَوۡمًا ءَاخَرِينَ¦44:29:1:فَمَا\nT;0;44:29:2:بَكَتۡ عَلَيۡهِمُ ٱلسَّمَآءُ وَٱلۡأَرۡضُ وَمَا كَانُواْ مُنظَرِينَ¦44:30:1:وَلَقَدۡ\nT;0;44:30:2:نَجَّيۡنَا بَنِيٓ إِسۡرَٰٓءِيلَ مِنَ ٱلۡعَذَابِ ٱلۡمُهِينِ¦44:31:1:مِن فِرۡعَوۡنَۚ إِنَّهُۥ\nT;0;44:31:2:كَانَ عَالِيࣰا مِّنَ ٱلۡمُسۡرِفِينَ¦44:32:1:وَلَقَدِ ٱخۡتَرۡنَٰهُمۡ عَلَىٰ عِلۡمٍ عَلَى\nT;0;44:32:2:ٱلۡعَٰلَمِينَ¦44:33:3:وَءَاتَيۡنَٰهُم مِّنَ ٱلۡأٓيَٰتِ مَا فِيهِ بَلَٰٓؤࣱاْ مُّبِينٌ\nT;0;44:34:3:إِنَّ هَٰٓؤُلَآءِ لَيَقُولُونَ¦44:35:1:إِنۡ هِيَ إِلَّا مَوۡتَتُنَا ٱلۡأُولَىٰ وَمَا نَحۡنُ\nT;0;44:35:2:بِمُنشَرِينَ¦44:36:3:فَأۡتُواْ بِـَٔابَآئِنَآ إِن كُنتُمۡ صَٰدِقِينَ¦44:37:1:أَهُمۡ\nT;0;44:37:0:خَيۡرٌ أَمۡ قَوۡمُ تُبَّعࣲ وَٱلَّذِينَ مِن قَبۡلِهِمۡ أَهۡلَكۡنَٰهُمۡۚ إِنَّهُمۡ كَانُواْ\nT;0;44:37:2:مُجۡرِمِينَ¦44:38:3:وَمَا خَلَقۡنَا ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَمَا بَيۡنَهُمَا لَٰعِبِينَ\nT;0;44:39:3:مَا خَلَقۡنَٰهُمَآ إِلَّا بِٱلۡحَقِّ وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَعۡلَمُونَ',
  '25;50;2;\nT;0;44:40:3:إِنَّ يَوۡمَ ٱلۡفَصۡلِ مِيقَٰتُهُمۡ أَجۡمَعِينَ¦44:41:1:يَوۡمَ لَا يُغۡنِي\nT;0;44:41:2:مَوۡلًى عَن مَّوۡلࣰى شَيۡـࣰٔا وَلَا هُمۡ يُنصَرُونَ¦44:42:1:إِلَّا مَن رَّحِمَ ٱللَّهُۚ\nT;0;44:42:2:إِنَّهُۥ هُوَ ٱلۡعَزِيزُ ٱلرَّحِيمُ¦44:43:3:إِنَّ شَجَرَتَ ٱلزَّقُّومِ\nT;0;44:44:3:طَعَامُ ٱلۡأَثِيمِ¦44:45:3:كَٱلۡمُهۡلِ يَغۡلِي فِي ٱلۡبُطُونِ\nT;0;44:46:3:كَغَلۡيِ ٱلۡحَمِيمِ¦44:47:1:خُذُوهُ فَٱعۡتِلُوهُ إِلَىٰ سَوَآءِ\nT;0;44:47:2:ٱلۡجَحِيمِ¦44:48:1:ثُمَّ صُبُّواْ فَوۡقَ رَأۡسِهِۦ مِنۡ عَذَابِ\nT;0;44:48:2:ٱلۡحَمِيمِ¦44:49:3:ذُقۡ إِنَّكَ أَنتَ ٱلۡعَزِيزُ ٱلۡكَرِيمُ\nT;0;44:50:3:إِنَّ هَٰذَا مَا كُنتُم بِهِۦ تَمۡتَرُونَ¦44:51:1:إِنَّ ٱلۡمُتَّقِينَ\nT;0;44:51:2:فِي مَقَامٍ أَمِينࣲ¦44:52:3:فِي جَنَّٰتࣲ وَعُيُونࣲ¦44:53:1:يَلۡبَسُونَ\nT;0;44:53:2:مِن سُندُسࣲ وَإِسۡتَبۡرَقࣲ مُّتَقَٰبِلِينَ¦44:54:1:كَذَٰلِكَ\nT;0;44:54:2:وَزَوَّجۡنَٰهُم بِحُورٍ عِينࣲ¦44:55:1:يَدۡعُونَ فِيهَا بِكُلِّ\nT;0;44:55:2:فَٰكِهَةٍ ءَامِنِينَ¦44:56:1:لَا يَذُوقُونَ فِيهَا ٱلۡمَوۡتَ إِلَّا\nT;0;44:56:2:ٱلۡمَوۡتَةَ ٱلۡأُولَىٰۖ وَوَقَىٰهُمۡ عَذَابَ ٱلۡجَحِيمِ¦44:57:1:فَضۡلࣰا مِّن\nT;0;44:57:2:رَّبِّكَۚ ذَٰلِكَ هُوَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ¦44:58:1:فَإِنَّمَا يَسَّرۡنَٰهُ بِلِسَانِكَ\nT;2;44:58:2:لَعَلَّهُمۡ يَتَذَكَّرُونَ¦44:59:3:فَٱرۡتَقِبۡ إِنَّهُم مُّرۡتَقِبُونَ',
  '25;50;2;200\nH;45\nB;45\nT;0;45:1:3:حمٓ¦45:2:3:تَنزِيلُ ٱلۡكِتَٰبِ مِنَ ٱللَّهِ ٱلۡعَزِيزِ ٱلۡحَكِيمِ¦45:3:1:إِنَّ فِي ٱلسَّمَٰوَٰتِ\nT;0;45:3:2:وَٱلۡأَرۡضِ لَأٓيَٰتࣲ لِّلۡمُؤۡمِنِينَ¦45:4:1:وَفِي خَلۡقِكُمۡ وَمَا يَبُثُّ مِن دَآبَّةٍ ءَايَٰتࣱ لِّقَوۡمࣲ\nT;0;45:4:2:يُوقِنُونَ¦45:5:1:وَٱخۡتِلَٰفِ ٱلَّيۡلِ وَٱلنَّهَارِ وَمَآ أَنزَلَ ٱللَّهُ مِنَ ٱلسَّمَآءِ مِن رِّزۡقࣲ\nT;0;45:5:2:فَأَحۡيَا بِهِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَا وَتَصۡرِيفِ ٱلرِّيَٰحِ ءَايَٰتࣱ لِّقَوۡمࣲ يَعۡقِلُونَ\nT;0;45:6:1:تِلۡكَ ءَايَٰتُ ٱللَّهِ نَتۡلُوهَا عَلَيۡكَ بِٱلۡحَقِّۖ فَبِأَيِّ حَدِيثِۭ بَعۡدَ ٱللَّهِ وَءَايَٰتِهِۦ\nT;0;45:6:2:يُؤۡمِنُونَ¦45:7:3:وَيۡلࣱ لِّكُلِّ أَفَّاكٍ أَثِيمࣲ¦45:8:1:يَسۡمَعُ ءَايَٰتِ ٱللَّهِ تُتۡلَىٰ عَلَيۡهِ ثُمَّ\nT;0;45:8:2:يُصِرُّ مُسۡتَكۡبِرࣰا كَأَن لَّمۡ يَسۡمَعۡهَاۖ فَبَشِّرۡهُ بِعَذَابٍ أَلِيمࣲ¦45:9:1:وَإِذَا عَلِمَ مِنۡ ءَايَٰتِنَا\nT;0;45:9:2:شَيۡـًٔا ٱتَّخَذَهَا هُزُوًاۚ أُوْلَٰٓئِكَ لَهُمۡ عَذَابࣱ مُّهِينࣱ¦45:10:1:مِّن وَرَآئِهِمۡ جَهَنَّمُۖ\nT;0;45:10:0:وَلَا يُغۡنِي عَنۡهُم مَّا كَسَبُواْ شَيۡـࣰٔا وَلَا مَا ٱتَّخَذُواْ مِن دُونِ ٱللَّهِ أَوۡلِيَآءَۖ وَلَهُمۡ\nT;0;45:10:2:عَذَابٌ عَظِيمٌ¦45:11:1:هَٰذَا هُدࣰىۖ وَٱلَّذِينَ كَفَرُواْ بِـَٔايَٰتِ رَبِّهِمۡ لَهُمۡ عَذَابࣱ مِّن\nT;0;45:11:2:رِّجۡزٍ أَلِيمٌ¦45:12:1:۞ ٱللَّهُ ٱلَّذِي سَخَّرَ لَكُمُ ٱلۡبَحۡرَ لِتَجۡرِيَ ٱلۡفُلۡكُ فِيهِ بِأَمۡرِهِۦ\nT;0;45:12:2:وَلِتَبۡتَغُواْ مِن فَضۡلِهِۦ وَلَعَلَّكُمۡ تَشۡكُرُونَ¦45:13:1:وَسَخَّرَ لَكُم مَّا فِي ٱلسَّمَٰوَٰتِ\nT;0;45:13:2:وَمَا فِي ٱلۡأَرۡضِ جَمِيعࣰا مِّنۡهُۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتࣲ لِّقَوۡمࣲ يَتَفَكَّرُونَ',
  '25;50;3;\nT;0;45:14:1:قُل لِّلَّذِينَ ءَامَنُواْ يَغۡفِرُواْ لِلَّذِينَ لَا يَرۡجُونَ أَيَّامَ ٱللَّهِ لِيَجۡزِيَ\nT;0;45:14:2:قَوۡمَۢا بِمَا كَانُواْ يَكۡسِبُونَ¦45:15:1:مَنۡ عَمِلَ صَٰلِحࣰا فَلِنَفۡسِهِۦۖ\nT;0;45:15:2:وَمَنۡ أَسَآءَ فَعَلَيۡهَاۖ ثُمَّ إِلَىٰ رَبِّكُمۡ تُرۡجَعُونَ¦45:16:1:وَلَقَدۡ ءَاتَيۡنَا\nT;0;45:16:0:بَنِيٓ إِسۡرَٰٓءِيلَ ٱلۡكِتَٰبَ وَٱلۡحُكۡمَ وَٱلنُّبُوَّةَ وَرَزَقۡنَٰهُم مِّنَ ٱلطَّيِّبَٰتِ\nT;0;45:16:2:وَفَضَّلۡنَٰهُمۡ عَلَى ٱلۡعَٰلَمِينَ¦45:17:1:وَءَاتَيۡنَٰهُم بَيِّنَٰتࣲ مِّنَ ٱلۡأَمۡرِۖ\nT;0;45:17:0:فَمَا ٱخۡتَلَفُوٓاْ إِلَّا مِنۢ بَعۡدِ مَا جَآءَهُمُ ٱلۡعِلۡمُ بَغۡيَۢا بَيۡنَهُمۡۚ إِنَّ رَبَّكَ\nT;0;45:17:2:يَقۡضِي بَيۡنَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ فِيمَا كَانُواْ فِيهِ يَخۡتَلِفُونَ\nT;0;45:18:1:ثُمَّ جَعَلۡنَٰكَ عَلَىٰ شَرِيعَةࣲ مِّنَ ٱلۡأَمۡرِ فَٱتَّبِعۡهَا وَلَا تَتَّبِعۡ\nT;0;45:18:2:أَهۡوَآءَ ٱلَّذِينَ لَا يَعۡلَمُونَ¦45:19:1:إِنَّهُمۡ لَن يُغۡنُواْ عَنكَ مِنَ ٱللَّهِ\nT;0;45:19:2:شَيۡـࣰٔاۚ وَإِنَّ ٱلظَّٰلِمِينَ بَعۡضُهُمۡ أَوۡلِيَآءُ بَعۡضࣲۖ وَٱللَّهُ وَلِيُّ ٱلۡمُتَّقِينَ\nT;0;45:20:3:هَٰذَا بَصَٰٓئِرُ لِلنَّاسِ وَهُدࣰى وَرَحۡمَةࣱ لِّقَوۡمࣲ يُوقِنُونَ\nT;0;45:21:1:أَمۡ حَسِبَ ٱلَّذِينَ ٱجۡتَرَحُواْ ٱلسَّيِّـَٔاتِ أَن نَّجۡعَلَهُمۡ كَٱلَّذِينَ\nT;0;45:21:0:ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ سَوَآءࣰ مَّحۡيَاهُمۡ وَمَمَاتُهُمۡۚ سَآءَ\nT;0;45:21:2:مَا يَحۡكُمُونَ¦45:22:1:وَخَلَقَ ٱللَّهُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ بِٱلۡحَقِّ\nT;0;45:22:2:وَلِتُجۡزَىٰ كُلُّ نَفۡسِۭ بِمَا كَسَبَتۡ وَهُمۡ لَا يُظۡلَمُونَ',
  '25;50;3;\nT;0;45:23:1:أَفَرَءَيۡتَ مَنِ ٱتَّخَذَ إِلَٰهَهُۥ هَوَىٰهُ وَأَضَلَّهُ ٱللَّهُ عَلَىٰ عِلۡمࣲ وَخَتَمَ عَلَىٰ سَمۡعِهِۦ\nT;0;45:23:0:وَقَلۡبِهِۦ وَجَعَلَ عَلَىٰ بَصَرِهِۦ غِشَٰوَةࣰ فَمَن يَهۡدِيهِ مِنۢ بَعۡدِ ٱللَّهِۚ أَفَلَا\nT;0;45:23:2:تَذَكَّرُونَ¦45:24:1:وَقَالُواْ مَا هِيَ إِلَّا حَيَاتُنَا ٱلدُّنۡيَا نَمُوتُ وَنَحۡيَا وَمَا يُهۡلِكُنَآ\nT;0;45:24:2:إِلَّا ٱلدَّهۡرُۚ وَمَا لَهُم بِذَٰلِكَ مِنۡ عِلۡمٍۖ إِنۡ هُمۡ إِلَّا يَظُنُّونَ¦45:25:1:وَإِذَا تُتۡلَىٰ\nT;0;45:25:0:عَلَيۡهِمۡ ءَايَٰتُنَا بَيِّنَٰتࣲ مَّا كَانَ حُجَّتَهُمۡ إِلَّآ أَن قَالُواْ ٱئۡتُواْ بِـَٔابَآئِنَآ إِن\nT;0;45:25:2:كُنتُمۡ صَٰدِقِينَ¦45:26:1:قُلِ ٱللَّهُ يُحۡيِيكُمۡ ثُمَّ يُمِيتُكُمۡ ثُمَّ يَجۡمَعُكُمۡ إِلَىٰ\nT;0;45:26:2:يَوۡمِ ٱلۡقِيَٰمَةِ لَا رَيۡبَ فِيهِ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَعۡلَمُونَ¦45:27:1:وَلِلَّهِ مُلۡكُ\nT;0;45:27:2:ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَيَوۡمَ تَقُومُ ٱلسَّاعَةُ يَوۡمَئِذࣲ يَخۡسَرُ ٱلۡمُبۡطِلُونَ\nT;0;45:28:1:وَتَرَىٰ كُلَّ أُمَّةࣲ جَاثِيَةࣰۚ كُلُّ أُمَّةࣲ تُدۡعَىٰٓ إِلَىٰ كِتَٰبِهَا ٱلۡيَوۡمَ تُجۡزَوۡنَ مَا كُنتُمۡ\nT;0;45:28:2:تَعۡمَلُونَ¦45:29:1:هَٰذَا كِتَٰبُنَا يَنطِقُ عَلَيۡكُم بِٱلۡحَقِّۚ إِنَّا كُنَّا نَسۡتَنسِخُ\nT;0;45:29:2:مَا كُنتُمۡ تَعۡمَلُونَ¦45:30:1:فَأَمَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ\nT;0;45:30:2:فَيُدۡخِلُهُمۡ رَبُّهُمۡ فِي رَحۡمَتِهِۦۚ ذَٰلِكَ هُوَ ٱلۡفَوۡزُ ٱلۡمُبِينُ¦45:31:1:وَأَمَّا\nT;0;45:31:0:ٱلَّذِينَ كَفَرُوٓاْ أَفَلَمۡ تَكُنۡ ءَايَٰتِي تُتۡلَىٰ عَلَيۡكُمۡ فَٱسۡتَكۡبَرۡتُمۡ وَكُنتُمۡ قَوۡمࣰا\nT;0;45:31:2:مُّجۡرِمِينَ¦45:32:1:وَإِذَا قِيلَ إِنَّ وَعۡدَ ٱللَّهِ حَقࣱّ وَٱلسَّاعَةُ لَا رَيۡبَ فِيهَا\nT;0;45:32:2:قُلۡتُم مَّا نَدۡرِي مَا ٱلسَّاعَةُ إِن نَّظُنُّ إِلَّا ظَنࣰّا وَمَا نَحۡنُ بِمُسۡتَيۡقِنِينَ',
  '25;50;3;201\nT;0;45:33:3:وَبَدَا لَهُمۡ سَيِّـَٔاتُ مَا عَمِلُواْ وَحَاقَ بِهِم مَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ\nT;0;45:34:1:وَقِيلَ ٱلۡيَوۡمَ نَنسَىٰكُمۡ كَمَا نَسِيتُمۡ لِقَآءَ يَوۡمِكُمۡ هَٰذَا وَمَأۡوَىٰكُمُ ٱلنَّارُ\nT;0;45:34:2:وَمَا لَكُم مِّن نَّٰصِرِينَ¦45:35:1:ذَٰلِكُم بِأَنَّكُمُ ٱتَّخَذۡتُمۡ ءَايَٰتِ ٱللَّهِ هُزُوࣰا\nT;0;45:35:2:وَغَرَّتۡكُمُ ٱلۡحَيَوٰةُ ٱلدُّنۡيَاۚ فَٱلۡيَوۡمَ لَا يُخۡرَجُونَ مِنۡهَا وَلَا هُمۡ يُسۡتَعۡتَبُونَ\nT;0;45:36:3:فَلِلَّهِ ٱلۡحَمۡدُ رَبِّ ٱلسَّمَٰوَٰتِ وَرَبِّ ٱلۡأَرۡضِ رَبِّ ٱلۡعَٰلَمِينَ\nT;2;45:37:3:وَلَهُ ٱلۡكِبۡرِيَآءُ فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ وَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ\nH;46\nB;46\nT;0;46:1:3:حمٓ¦46:2:3:تَنزِيلُ ٱلۡكِتَٰبِ مِنَ ٱللَّهِ ٱلۡعَزِيزِ ٱلۡحَكِيمِ¦46:3:1:مَا خَلَقۡنَا\nT;0;46:3:0:ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَمَا بَيۡنَهُمَآ إِلَّا بِٱلۡحَقِّ وَأَجَلࣲ مُّسَمࣰّىۚ وَٱلَّذِينَ\nT;0;46:3:2:كَفَرُواْ عَمَّآ أُنذِرُواْ مُعۡرِضُونَ¦46:4:1:قُلۡ أَرَءَيۡتُم مَّا تَدۡعُونَ مِن\nT;0;46:4:0:دُونِ ٱللَّهِ أَرُونِي مَاذَا خَلَقُواْ مِنَ ٱلۡأَرۡضِ أَمۡ لَهُمۡ شِرۡكࣱ فِي\nT;0;46:4:0:ٱلسَّمَٰوَٰتِۖ ٱئۡتُونِي بِكِتَٰبࣲ مِّن قَبۡلِ هَٰذَآ أَوۡ أَثَٰرَةࣲ مِّنۡ عِلۡمٍ إِن كُنتُمۡ\nT;0;46:4:2:صَٰدِقِينَ¦46:5:1:وَمَنۡ أَضَلُّ مِمَّن يَدۡعُواْ مِن دُونِ ٱللَّهِ مَن\nT;0;46:5:2:لَّا يَسۡتَجِيبُ لَهُۥٓ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِ وَهُمۡ عَن دُعَآئِهِمۡ غَٰفِلُونَ',
  '26;51;0;\nT;0;46:6:3:وَإِذَا حُشِرَ ٱلنَّاسُ كَانُواْ لَهُمۡ أَعۡدَآءࣰ وَكَانُواْ بِعِبَادَتِهِمۡ كَٰفِرِينَ¦46:7:1:وَإِذَا\nT;0;46:7:0:تُتۡلَىٰ عَلَيۡهِمۡ ءَايَٰتُنَا بَيِّنَٰتࣲ قَالَ ٱلَّذِينَ كَفَرُواْ لِلۡحَقِّ لَمَّا جَآءَهُمۡ هَٰذَا\nT;0;46:7:2:سِحۡرࣱ مُّبِينٌ¦46:8:1:أَمۡ يَقُولُونَ ٱفۡتَرَىٰهُۖ قُلۡ إِنِ ٱفۡتَرَيۡتُهُۥ فَلَا تَمۡلِكُونَ\nT;0;46:8:0:لِي مِنَ ٱللَّهِ شَيۡـًٔاۖ هُوَ أَعۡلَمُ بِمَا تُفِيضُونَ فِيهِۚ كَفَىٰ بِهِۦ شَهِيدَۢا بَيۡنِي\nT;0;46:8:2:وَبَيۡنَكُمۡۖ وَهُوَ ٱلۡغَفُورُ ٱلرَّحِيمُ¦46:9:1:قُلۡ مَا كُنتُ بِدۡعࣰا مِّنَ ٱلرُّسُلِ\nT;0;46:9:0:وَمَآ أَدۡرِي مَا يُفۡعَلُ بِي وَلَا بِكُمۡۖ إِنۡ أَتَّبِعُ إِلَّا مَا يُوحَىٰٓ إِلَيَّ وَمَآ أَنَا۠\nT;0;46:9:2:إِلَّا نَذِيرࣱ مُّبِينࣱ¦46:10:1:قُلۡ أَرَءَيۡتُمۡ إِن كَانَ مِنۡ عِندِ ٱللَّهِ وَكَفَرۡتُم بِهِۦ\nT;0;46:10:0:وَشَهِدَ شَاهِدࣱ مِّنۢ بَنِيٓ إِسۡرَٰٓءِيلَ عَلَىٰ مِثۡلِهِۦ فَـَٔامَنَ وَٱسۡتَكۡبَرۡتُمۡۚ\nT;0;46:10:2:إِنَّ ٱللَّهَ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّٰلِمِينَ¦46:11:1:وَقَالَ ٱلَّذِينَ كَفَرُواْ\nT;0;46:11:0:لِلَّذِينَ ءَامَنُواْ لَوۡ كَانَ خَيۡرࣰا مَّا سَبَقُونَآ إِلَيۡهِۚ وَإِذۡ لَمۡ يَهۡتَدُواْ بِهِۦ\nT;0;46:11:2:فَسَيَقُولُونَ هَٰذَآ إِفۡكࣱ قَدِيمࣱ¦46:12:1:وَمِن قَبۡلِهِۦ كِتَٰبُ مُوسَىٰٓ\nT;0;46:12:0:إِمَامࣰا وَرَحۡمَةࣰۚ وَهَٰذَا كِتَٰبࣱ مُّصَدِّقࣱ لِّسَانًا عَرَبِيࣰّا لِّيُنذِرَ\nT;0;46:12:2:ٱلَّذِينَ ظَلَمُواْ وَبُشۡرَىٰ لِلۡمُحۡسِنِينَ¦46:13:1:إِنَّ ٱلَّذِينَ قَالُواْ رَبُّنَا\nT;0;46:13:2:ٱللَّهُ ثُمَّ ٱسۡتَقَٰمُواْ فَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ\nT;0;46:14:3:أُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلۡجَنَّةِ خَٰلِدِينَ فِيهَا جَزَآءَۢ بِمَا كَانُواْ يَعۡمَلُونَ',
  '26;51;0;\nT;0;46:15:1:وَوَصَّيۡنَا ٱلۡإِنسَٰنَ بِوَٰلِدَيۡهِ إِحۡسَٰنًاۖ حَمَلَتۡهُ أُمُّهُۥ كُرۡهࣰا وَوَضَعَتۡهُ\nT;0;46:15:0:كُرۡهࣰاۖ وَحَمۡلُهُۥ وَفِصَٰلُهُۥ ثَلَٰثُونَ شَهۡرًاۚ حَتَّىٰٓ إِذَا بَلَغَ أَشُدَّهُۥ وَبَلَغَ\nT;0;46:15:0:أَرۡبَعِينَ سَنَةࣰ قَالَ رَبِّ أَوۡزِعۡنِيٓ أَنۡ أَشۡكُرَ نِعۡمَتَكَ ٱلَّتِيٓ أَنۡعَمۡتَ\nT;0;46:15:0:عَلَيَّ وَعَلَىٰ وَٰلِدَيَّ وَأَنۡ أَعۡمَلَ صَٰلِحࣰا تَرۡضَىٰهُ وَأَصۡلِحۡ لِي فِي ذُرِّيَّتِيٓۖ\nT;0;46:15:2:إِنِّي تُبۡتُ إِلَيۡكَ وَإِنِّي مِنَ ٱلۡمُسۡلِمِينَ¦46:16:1:أُوْلَٰٓئِكَ ٱلَّذِينَ نَتَقَبَّلُ\nT;0;46:16:0:عَنۡهُمۡ أَحۡسَنَ مَا عَمِلُواْ وَنَتَجَاوَزُ عَن سَيِّـَٔاتِهِمۡ فِيٓ أَصۡحَٰبِ\nT;0;46:16:2:ٱلۡجَنَّةِۖ وَعۡدَ ٱلصِّدۡقِ ٱلَّذِي كَانُواْ يُوعَدُونَ¦46:17:1:وَٱلَّذِي قَالَ\nT;0;46:17:0:لِوَٰلِدَيۡهِ أُفࣲّ لَّكُمَآ أَتَعِدَانِنِيٓ أَنۡ أُخۡرَجَ وَقَدۡ خَلَتِ ٱلۡقُرُونُ مِن\nT;0;46:17:0:قَبۡلِي وَهُمَا يَسۡتَغِيثَانِ ٱللَّهَ وَيۡلَكَ ءَامِنۡ إِنَّ وَعۡدَ ٱللَّهِ حَقࣱّ فَيَقُولُ\nT;0;46:17:2:مَا هَٰذَآ إِلَّآ أَسَٰطِيرُ ٱلۡأَوَّلِينَ¦46:18:1:أُوْلَٰٓئِكَ ٱلَّذِينَ حَقَّ عَلَيۡهِمُ ٱلۡقَوۡلُ\nT;0;46:18:0:فِيٓ أُمَمࣲ قَدۡ خَلَتۡ مِن قَبۡلِهِم مِّنَ ٱلۡجِنِّ وَٱلۡإِنسِۖ إِنَّهُمۡ كَانُواْ\nT;0;46:18:2:خَٰسِرِينَ¦46:19:1:وَلِكُلࣲّ دَرَجَٰتࣱ مِّمَّا عَمِلُواْۖ وَلِيُوَفِّيَهُمۡ أَعۡمَٰلَهُمۡ وَهُمۡ لَا\nT;0;46:19:2:يُظۡلَمُونَ¦46:20:1:وَيَوۡمَ يُعۡرَضُ ٱلَّذِينَ كَفَرُواْ عَلَى ٱلنَّارِ أَذۡهَبۡتُمۡ طَيِّبَٰتِكُمۡ فِي\nT;0;46:20:0:حَيَاتِكُمُ ٱلدُّنۡيَا وَٱسۡتَمۡتَعۡتُم بِهَا فَٱلۡيَوۡمَ تُجۡزَوۡنَ عَذَابَ ٱلۡهُونِ بِمَا\nT;0;46:20:2:كُنتُمۡ تَسۡتَكۡبِرُونَ فِي ٱلۡأَرۡضِ بِغَيۡرِ ٱلۡحَقِّ وَبِمَا كُنتُمۡ تَفۡسُقُونَ',
  '26;51;1;202\nT;0;46:21:1:۞ وَٱذۡكُرۡ أَخَا عَادٍ إِذۡ أَنذَرَ قَوۡمَهُۥ بِٱلۡأَحۡقَافِ وَقَدۡ خَلَتِ ٱلنُّذُرُ\nT;0;46:21:0:مِنۢ بَيۡنِ يَدَيۡهِ وَمِنۡ خَلۡفِهِۦٓ أَلَّا تَعۡبُدُوٓاْ إِلَّا ٱللَّهَ إِنِّيٓ أَخَافُ عَلَيۡكُمۡ\nT;0;46:21:2:عَذَابَ يَوۡمٍ عَظِيمࣲ¦46:22:1:قَالُوٓاْ أَجِئۡتَنَا لِتَأۡفِكَنَا عَنۡ ءَالِهَتِنَا فَأۡتِنَا\nT;0;46:22:2:بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ¦46:23:1:قَالَ إِنَّمَا ٱلۡعِلۡمُ عِندَ ٱللَّهِ\nT;0;46:23:2:وَأُبَلِّغُكُم مَّآ أُرۡسِلۡتُ بِهِۦ وَلَٰكِنِّيٓ أَرَىٰكُمۡ قَوۡمࣰا تَجۡهَلُونَ¦46:24:1:فَلَمَّا\nT;0;46:24:0:رَأَوۡهُ عَارِضࣰا مُّسۡتَقۡبِلَ أَوۡدِيَتِهِمۡ قَالُواْ هَٰذَا عَارِضࣱ مُّمۡطِرُنَاۚ\nT;0;46:24:2:بَلۡ هُوَ مَا ٱسۡتَعۡجَلۡتُم بِهِۦۖ رِيحࣱ فِيهَا عَذَابٌ أَلِيمࣱ¦46:25:1:تُدَمِّرُ كُلَّ\nT;0;46:25:0:شَيۡءِۭ بِأَمۡرِ رَبِّهَا فَأَصۡبَحُواْ لَا يُرَىٰٓ إِلَّا مَسَٰكِنُهُمۡۚ كَذَٰلِكَ نَجۡزِي\nT;0;46:25:2:ٱلۡقَوۡمَ ٱلۡمُجۡرِمِينَ¦46:26:1:وَلَقَدۡ مَكَّنَّٰهُمۡ فِيمَآ إِن مَّكَّنَّٰكُمۡ فِيهِ\nT;0;46:26:0:وَجَعَلۡنَا لَهُمۡ سَمۡعࣰا وَأَبۡصَٰرࣰا وَأَفۡـِٔدَةࣰ فَمَآ أَغۡنَىٰ عَنۡهُمۡ سَمۡعُهُمۡ\nT;0;46:26:0:وَلَآ أَبۡصَٰرُهُمۡ وَلَآ أَفۡـِٔدَتُهُم مِّن شَيۡءٍ إِذۡ كَانُواْ يَجۡحَدُونَ بِـَٔايَٰتِ\nT;0;46:26:2:ٱللَّهِ وَحَاقَ بِهِم مَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ¦46:27:1:وَلَقَدۡ أَهۡلَكۡنَا\nT;0;46:27:2:مَا حَوۡلَكُم مِّنَ ٱلۡقُرَىٰ وَصَرَّفۡنَا ٱلۡأٓيَٰتِ لَعَلَّهُمۡ يَرۡجِعُونَ\nT;0;46:28:1:فَلَوۡلَا نَصَرَهُمُ ٱلَّذِينَ ٱتَّخَذُواْ مِن دُونِ ٱللَّهِ قُرۡبَانًا ءَالِهَةَۢۖ\nT;0;46:28:2:بَلۡ ضَلُّواْ عَنۡهُمۡۚ وَذَٰلِكَ إِفۡكُهُمۡ وَمَا كَانُواْ يَفۡتَرُونَ',
];
